subjects.splice(0,subjects.length,...Object.keys(SUBJECT_WORDS));icons.splice(0,icons.length,...subjects.map(s=>SUBJECT_META[s][0]));
function subjectEntries(s){return SUBJECT_WORDS[s].split('\n').map((line,i)=>{const[en,vi,icon]=line.split('|');return{id:'subject-v7-'+subjects.indexOf(s)+'-'+i,en,vi,icon}})}

state.subjectFilter='all';state.subjectSearch='';state.subjectQuiz=null;state.subjectFeedback='';state.subjectQuizIndex=0;
function mathPicture(token){if(/^\d+$/.test(token)||['+','−'].includes(token))return `<span class="math-number">${esc(token)}</span>`;const shapes={circle:'<circle cx="80" cy="65" r="43"/>',triangle:'<path d="M80 17 L133 108 H27 Z"/>',square:'<rect x="35" y="20" width="90" height="90" rx="5"/>',rectangle:'<rect x="17" y="34" width="126" height="65" rx="5"/>',oval:'<ellipse cx="80" cy="65" rx="65" ry="39"/>',cube:'<path d="M80 10 132 38 132 94 80 122 28 94 28 38 Z"/><path d="M28 38 80 68 132 38 M80 68 V122" fill="none"/>',sphere:'<circle cx="80" cy="65" r="48"/><ellipse cx="80" cy="65" rx="21" ry="48" fill="none"/><ellipse cx="80" cy="65" rx="48" ry="16" fill="none"/>'};return `<svg viewBox="0 0 160 132" role="img" aria-label="Minh họa ${esc(token.replace('shape-',''))}" class="math-shape"><g fill="#69d8ef" stroke="#267cbd" stroke-width="4" stroke-linejoin="round">${shapes[token.replace('shape-','')]||''}</g></svg>`}
function subjectArt(w){if(state.subject==='Toán'&&(/^(?:\d+|shape-.+|[+−])$/.test(w.icon)))return mathPicture(w.icon);const url=emojiImage(w.icon);return url?`<img src="${esc(url)}" alt="Hình gợi nhớ ${esc(w.vi)}">`:`<span class="subject-symbol">${esc(w.icon)}</span>`}
chooseSubject=function(s){if(!SUBJECT_WORDS[s])return;state.subject=s;state.subjectFilter='all';state.subjectSearch='';state.subjectQuiz=null;state.subjectFeedback='';goto('subjects')};
function subjectSearch(value){state.subjectSearch=value;render();const input=document.querySelector('#subject-search');input?.focus();if(input?.setSelectionRange)input.setSelectionRange(value.length,value.length)}
function startSubjectQuiz(){state.subjectQuizIndex=0;state.subjectFeedback='';state.subjectQuiz=true;render()}
function answerSubjectQuiz(i){if(state.subjectFeedback)return;const bank=subjectEntries(state.subject),q=bank[state.subjectQuizIndex];state.subjectFeedback=i===state.subjectQuizIndex?'Đúng rồi! '+q.en+' nghĩa là '+q.vi+'.':'Mình cùng nhớ nhé: '+q.en+' nghĩa là '+q.vi+'.';render()}
function nextSubjectQuiz(){state.subjectQuizIndex++;state.subjectFeedback='';if(state.subjectQuizIndex>=5){state.subjectQuiz=null;notify('Em đã hoàn thành 5 câu ôn tập!')}render()}
subjectPage=function(){const bank=subjectEntries(state.subject),meta=SUBJECT_META[state.subject],done=bank.filter(w=>state.progress.learned.includes(w.id)).length;const shown=bank.filter(w=>(state.subjectFilter!=='learned'||state.progress.learned.includes(w.id))&&(w.en+' '+w.vi).toLocaleLowerCase('vi').includes(state.subjectSearch.toLocaleLowerCase('vi')));let quiz='';if(state.subjectQuiz){const q=bank[state.subjectQuizIndex],choices=[0,1,2,3].map(n=>(state.subjectQuizIndex+n*17)%bank.length).sort((a,b)=>a-b);quiz=`<section class="panel subject-quiz"><span class="eyebrow">ÔN NHANH · ${state.subjectQuizIndex+1}/5</span><h2>“${esc(q.en)}” có nghĩa là gì?</h2><button class="speak" onclick="say(${esc(JSON.stringify(q.en))})">🔊 Nghe từ</button><div class="subject-quiz-choices">${choices.map(i=>`<button class="chip" ${state.subjectFeedback?'disabled':''} onclick="answerSubjectQuiz(${i})">${esc(bank[i].vi)}</button>`).join('')}</div>${state.subjectFeedback?`<p role="status">${esc(state.subjectFeedback)}</p><button class="primary" onclick="nextSubjectQuiz()">Tiếp tục →</button>`:''}<button class="chip" onclick="state.subjectQuiz=null;render()">Đóng ôn tập</button></section>`}return header('TỪ VỰNG MÔN '+state.subject.toUpperCase(),meta[1]+' · 100 từ và cụm từ · Nghe, nhìn, ghi nhớ')+`<div class="subject-nav" aria-label="Chọn môn học">${subjects.map(s=>`<button class="subject-mini ${s===state.subject?'on':''}" onclick="chooseSubject(${esc(JSON.stringify(s))})"><span>${SUBJECT_META[s][0]}</span>${esc(s)}</button>`).join('')}</div><section class="subject-welcome"><div><span class="eyebrow">MỖI NGÀY MỘT KHÁM PHÁ</span><h2>${esc(meta[2])}</h2><p>${state.subject==='Toán'?'Khám phá số, phép tính, phân số, hình học, đo lường và thời gian.':'Nhìn hình gợi nhớ, nghe tiếng Anh rồi tìm điều tương tự trong cuộc sống của em.'}</p><div class="subject-progress"><b>${done}/100 từ đã nhớ</b><progress value="${done}" max="100">${done}/100</progress></div></div><img src="assets/student-robot.png" alt="Rô-bốt Mây mời em khám phá môn học"></section><section class="panel"><div class="study-toolbar"><label>Tìm trong môn học<input id="subject-search" class="search" value="${esc(state.subjectSearch)}" placeholder="Tiếng Anh hoặc tiếng Việt" oninput="subjectSearch(this.value)"></label><div class="filters"><button class="chip ${state.subjectFilter==='all'?'on':''}" onclick="state.subjectFilter='all';render()">Tất cả 100 từ</button><button class="chip ${state.subjectFilter==='learned'?'on':''}" onclick="state.subjectFilter='learned';render()">✅ Đã nhớ</button><button class="primary" onclick="startSubjectQuiz()">🎲 Ôn nhanh 5 câu</button></div></div></section>${quiz}<div class="subject-word-grid">${shown.map(w=>`<article class="subject-word"><div class="subject-word-art">${subjectArt(w)}</div><div class="subject-word-body"><span class="subject-word-index">${String(bank.indexOf(w)+1).padStart(2,'0')} · ${esc(state.subject)}</span><h2>${esc(w.en)}</h2><p>${esc(w.vi)}</p><div class="subject-word-actions"><button class="speak" aria-label="Nghe ${esc(w.en)}" onclick="say(${esc(JSON.stringify(w.en))})">🔊 Nghe</button><button class="learn-button ${state.progress.learned.includes(w.id)?'done':''}" onclick="learn(${esc(JSON.stringify(w.id))})">${state.progress.learned.includes(w.id)?'✅ Đã nhớ':'☆ Ghi nhớ'}</button></div></div></article>`).join('')||'<div class="panel">Chưa có từ phù hợp với bộ lọc này.</div>'}</div><p class="notice">Bộ từ bổ trợ theo chủ đề môn học. Hình ngoài môn Toán có thể là hình gợi nhớ. Giọng đọc tùy thiết bị; tiến độ lưu trên trình duyệt này.</p>`};
const landingV7Base=landing;landing=function(){return landingV7Base().replace(/(<span>)(Toán|Tự nhiên &amp; Xã hội|Khoa học|Mĩ thuật|Âm nhạc|Thể dục|Tin học|Lịch sử và Địa lí|Đạo đức|Công nghệ|Hoạt động trải nghiệm)(<\/span>)/g,'$1$2<small>100 từ vựng</small>$3')};
const layoutV7Base=layout;layout=function(body){let html=layoutV7Base(body);return html.replace('class="main',`data-section="${esc(state.page)}" class="main`).replace(/Bản 6\.0/g,'Bản 8.0')};

