const subjectEntriesV7=subjectEntries;
subjectEntries=function(s){const rows=subjectEntriesV7(s),seen=new Set(rows.map(w=>w.en.toLowerCase()));function add(en,vi,icon){en=en.trim();if(!en||seen.has(en.toLowerCase()))return;seen.add(en.toLowerCase());rows.push({id:'subject-v8-'+subjects.indexOf(s)+'-'+en.toLowerCase().replace(/[^a-z0-9]+/g,'-'),en,vi,icon:icon||SUBJECT_META[s][0]})}
if(SUBJECT_ADDITIONS[s])for(const line of SUBJECT_ADDITIONS[s].split('\n')){const[en,vi]=line.split('|');add(en,vi)}
for(const category of SUBJECT_CATEGORIES[s])for(const w of state.data.vocabulary.filter(w=>w.category===category))add(w.en,w.vi,w.icon);
if(rows.length<100)throw new Error('Chưa đủ 100 từ cho '+s);return rows.slice(0,100)};

function schoolFriends(){return `<svg class="school-friends" viewBox="440 245 505 235" role="img" aria-label="Học sinh nam, học sinh nữ và rô-bốt cùng học"><image href="assets/school-cover.jpg" x="0" y="0" width="1376" height="768"/></svg>`}
function schoolFlags(){return `<div class="school-flags" aria-label="Cờ Vương quốc Anh và cờ Việt Nam"><svg viewBox="0 0 60 36" role="img" aria-label="Cờ Vương quốc Anh"><rect width="60" height="36" fill="#163b81"/><path d="M0 0 60 36 M60 0 0 36" stroke="white" stroke-width="8"/><path d="M0 0 60 36 M60 0 0 36" stroke="#d92c37" stroke-width="3"/><path d="M30 0V36 M0 18H60" stroke="white" stroke-width="12"/><path d="M30 0V36 M0 18H60" stroke="#d92c37" stroke-width="7"/></svg><svg viewBox="0 0 60 36" role="img" aria-label="Cờ Việt Nam"><rect width="60" height="36" fill="#da251d"/><path d="M30 6 32.7 14.3 41.4 14.3 34.3 19.4 37 27.7 30 22.6 23 27.7 25.7 19.4 18.6 14.3 27.3 14.3Z" fill="#ffdf00"/></svg></div>`}
header=function(title,subtitle){return `<header class="wood-header storybook-title companions-header"><div class="school-title-text"><span class="wood-eyebrow">NGÔI TRƯỜNG SONG NGỮ ANH – VIỆT</span><h1>${title}</h1><p>${subtitle}</p></div><div class="school-friends-frame">${schoolFriends()}</div></header>`};
const landingBeforeV8=landing;
landing=function(){return landingBeforeV8().replace(/<section class="hero">[\s\S]*?<\/section>/,`<section class="hero school-home"><div class="home-sign">${schoolFlags()}<span class="school-crown">👑</span><h1>NGÔI TRƯỜNG<span>SONG NGỮ ANH – VIỆT</span></h1><p>⭐ Học vui · Thực hành · Phát triển ⭐</p></div><div class="home-friends">${schoolFriends()}</div><span class="hero-badge">Cùng nhau khám phá · Cùng nhau tiến bộ</span></section>`).replace(/20 từ vựng/g,'100 từ vựng')};
const layoutBeforeV8=layout;
layout=function(body){return layoutBeforeV8(body).replace(/Bản [67]\.0/g,'Bản 8.0')};

const regularLayout=layout;layout=body=>regularLayout(body).replace(/assets\/[A-Za-z0-9._-]+\.(?:webp|png|jpg)/g,p=>ASSET_URLS[p]||p);
ASSET_URLS['assets/daingan-trio.png']='./assets/f38416b102eeab8e62620091.webp';
ASSET_URLS['assets/daingan-home.png']='./assets/0e708612831c83c6afd53438.webp';
function schoolFriends(){return `<img class="school-friends" src="assets/daingan-trio.png" alt="Hai học sinh và rô-bốt Đại Ngàn">`}
function mountainRobot(){return `<svg viewBox="765 330 180 200" class="mountain-robot" role="img" aria-label="Rô-bốt Đại Ngàn"><image href="assets/daingan-home.png" width="1672" height="941"/></svg>`}
function openExistingGame(i){state.game=i;state.question=0;goto('quiz')}
