landing=function(){return `<section class="daingan-home" aria-label="Đại Ngàn Song Ngữ"><img class="daingan-home-art" src="assets/daingan-home.png" alt="Đại Ngàn Song Ngữ: học vui bản làng, vươn xa thế giới"><nav class="home-hotspots" aria-label="Điều hướng theo giao diện Đại Ngàn">${dainganLinks.map(([name,x,y,w,h,action])=>`<button class="home-hotspot" style="left:${x}%;top:${y}%;width:${w}%;height:${h}%" aria-label="${esc(name)}" title="${esc(name)}" onclick="${esc(action)}"><span>${esc(name)}</span></button>`).join('')}</nav><div class="daingan-live-honor" aria-label="Thành tích các hồ sơ trên thiết bị">${[0,1,2].map(i=>{const x=state.leaders[i];return `<button onclick="goto('ranking')" aria-label="${x?esc(x.name)+' · '+x.stars+' sao':'Chờ ngôi sao mới'}"><b>${i+1}</b><span>${x?esc(x.name):'Chờ ngôi sao mới'}</span><strong>⭐ ${x?.stars||0}</strong></button>`}).join('')}</div></section>`};
const dainganLayoutBase=layout;
layout=function(body){body=body.replace(/<img[^>]*src="assets\/student-robot\.png"[^>]*>/g,mountainRobot());let html=dainganLayoutBase(body).replace('class="layout v2"',`class="layout v2 mountain-app daingan-app ${state.page==='home'?'is-daingan-home':''}"`);html=html.replace(/<button class="brand-image"[\s\S]*?<\/button>/,`<button class="mountain-brand daingan-brand" onclick="goto('home')" aria-label="Đại Ngàn Song Ngữ"><span>⛰️ ĐẠI NGÀN</span><b>SONG NGỮ</b></button>`).replace(/LỚP HỌC SONG NGỮ ANH - VIỆT/g,'ĐẠI NGÀN SONG NGỮ').replace('<span>Đánh giá</span>','<span>Góc tiến bộ</span>').replace('<span>Kho truyện</span>','<span>Kể chuyện bản làng</span>').replace(/Bản [678]\.0[^<]*/g,'Bản xem trước · Đại Ngàn Song Ngữ');return html};
const dainganHeaderBase=header;
header=function(title,subtitle){return dainganHeaderBase(title,subtitle).replace('NGÔI TRƯỜNG SONG NGỮ ANH – VIỆT','ĐẠI NGÀN SONG NGỮ')};
function existingSubjectNav(){return `<div class="daingan-subject-nav" aria-label="Các môn học đã có">${subjects.map(s=>`<button class="chip" onclick="chooseSubject(${esc(JSON.stringify(s))})">${esc(s)}</button>`).join('')}</div>`}
const dainganVocabularyBase=vocabulary;
vocabulary=function(){return `<nav class="daingan-section-tabs"><button class="chip on">Từ vựng chung</button><button class="chip" onclick="document.querySelector('#existing-subjects').scrollIntoView({behavior:'smooth'})">Từ vựng các môn học</button></nav><details class="panel" id="existing-subjects"><summary>11 môn học · Mỗi môn 100 từ/cụm từ</summary>${existingSubjectNav()}</details>`+dainganVocabularyBase()};
