// Local practice only. No microphone, speech upload or automated phoneme score.
const CARE_KEY='daingan-robot-care-v1';
const careTasks=[['morning','☀️','Chào buổi sáng','Chào, chọn cảm xúc và sạc pin'],['feeding','🌽','Bữa ăn từ vựng','Chọn món, nói câu thật ngắn'],['cleaning','✨','Lau bụi luyện âm','Nghe và thử âm cuối /k/, /t/, /s/'],['goodnight','🌙','Chúc ngủ ngon','Nói lời chúc rồi nghỉ ngơi']];
state.careTask='morning';state.careCue='morning-low';state.careFeeling='';state.careFood='corn';state.careChosenFood='';state.careWord='book';state.careAdult=false;state.careSound=true;
function careDate(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function careIdentity(){return (state.user?.username||'guest')+'|'+careDate()}
function careRead(){try{const all=JSON.parse(localStorage.getItem(CARE_KEY)||'{}');return all[careIdentity()]||{battery:20,completed:[],cleanWords:[],verifiedWords:[],feeling:'',evidence:{}}}catch{return {battery:20,completed:[],cleanWords:[],verifiedWords:[],feeling:'',evidence:{}}}}
function careWrite(edit){try{let all=JSON.parse(localStorage.getItem(CARE_KEY)||'{}');if(!all||typeof all!=='object'||Array.isArray(all))all={};const row=careRead();edit(row);row.updatedAt=new Date().toISOString();all[careIdentity()]=row;localStorage.setItem(CARE_KEY,JSON.stringify(all));return true}catch{notify('Chưa lưu được trên thiết bị. Em vẫn có thể luyện.',false);return false}}
function careLine(id){return robotCareData.find(x=>x.id===id)||robotCareData[0]}
function careChime(){if(!state.careSound)return;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;const ac=new Audio(),osc=ac.createOscillator(),gain=ac.createGain();osc.connect(gain);gain.connect(ac.destination);const kind=careLine(state.careCue).feedback.sound;const tones={'gentle-beep':[440,440],'soft-chime':[520,660],'charge-chime':[440,880],'lullaby-chime':[520,390]}[kind]||[520,660];osc.frequency.setValueAtTime(tones[0],ac.currentTime);osc.frequency.exponentialRampToValueAtTime(tones[1],ac.currentTime+.18);gain.gain.setValueAtTime(.035,ac.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.25);osc.start();osc.stop(ac.currentTime+.27);osc.onended=()=>ac.close()}catch{}}
function careSpeak(text){stopSpeech();if(typeof speechSynthesis==='undefined'||typeof SpeechSynthesisUtterance==='undefined'){notify('Thiết bị chưa có giọng đọc. Em xem câu và nghĩa nhé.',false);return}const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.76;const v=speechSynthesis.getVoices().find(x=>x.lang==='en-US'&&x.localService)||speechSynthesis.getVoices().find(x=>x.lang.startsWith('en'));if(v)u.voice=v;speechSynthesis.speak(u)}
function careSetCue(id,speak=true){state.careCue=id;const line=careLine(id);render();if(line.feedback.sound!=='none')careChime();if(speak)careSpeak(line.robotEn)}
function careSelectTask(task){if(!careTasks.some(t=>t[0]===task))return;stopSpeech();state.careTask=task;state.careAdult=false;state.careChosenFood='';state.careCue={morning:'morning-low',feeding:'feed-'+state.careFood,cleaning:'clean-help',goodnight:'night-sleepy'}[task];render()}
function careFeeling(feeling){if(!['happy','tired','excited'].includes(feeling))return;state.careFeeling=feeling;careWrite(x=>{x.feeling=feeling});careSetCue('feeling-'+feeling)}
function careComplete(task,evidence='self-reported-practice'){careWrite(x=>{if(!x.completed.includes(task))x.completed.push(task);x.evidence[task]=evidence;if(task==='morning')x.battery=100})}
function careMorningDone(){if(!state.careFeeling&&!careRead().feeling){notify('Em chọn cảm xúc của mình trước nhé.',false);return}careComplete('morning');careSetCue('morning-charged')}
function careWantFood(food){if(!['corn','fish','rice','apple'].includes(food))return;state.careFood=food;state.careChosenFood='';careSetCue('feed-'+food)}
function careGiveFood(food){state.careChosenFood=food;if(food!==state.careFood){careSetCue('feed-retry');return}careSetCue('feed-'+food,false)}
function careFoodDone(){if(state.careChosenFood!==state.careFood){notify('Em tìm món rô-bốt đang muốn ăn nhé.',false);return}careComplete('feeding');careSetCue('feed-yummy')}
function carePickWord(word){if(!['book','cat','bus'].includes(word))return;state.careWord=word;state.careAdult=false;careSetCue('clean-'+word)}
function careCleanTry(){careWrite(x=>{if(!x.cleanWords.includes(state.careWord))x.cleanWords.push(state.careWord);if(x.cleanWords.length===3){if(!x.completed.includes('cleaning'))x.completed.push('cleaning');x.evidence.cleaning='self-reported-practice'}});careSetCue(careRead().cleanWords.length===3?'clean-done':'clean-effort')}
function careAdultVerify(){if(!state.careAdult)return;careWrite(x=>{if(!x.verifiedWords.includes(state.careWord))x.verifiedWords.push(state.careWord)});state.careAdult=false;careSetCue('clean-verified')}
function careNightDone(){careComplete('goodnight');careSetCue('night-goodnight')}
function careScriptTable(){return `<details class="panel care-script"><summary>Kịch bản Anh–Việt và IPA · ${robotCareData.length} tình huống</summary><div class="table-scroll"><table><thead><tr><th>Tình huống / Hành động</th><th>Rô-bốt nói</th><th>IPA</th><th>Học sinh nói</th><th>Nghĩa tiếng Việt</th><th>Cử chỉ / Âm thanh</th></tr></thead><tbody>${robotCareData.map(x=>`<tr><td>${esc(x.situation)}</td><td>${esc(x.robotEn)}</td><td class="ipa">${esc(x.robotIpa)}</td><td>${esc(x.studentEn)}<br><small class="ipa">${esc(x.studentIpa)}</small></td><td>Rô-bốt: ${esc(x.vietnamese.robot)}<br>Em: ${esc(x.vietnamese.student)}</td><td>${esc(x.feedback.animation)}<br>${esc(x.feedback.sound)}</td></tr>`).join('')}</tbody></table></div></details>`}
function carePage(){const db=careRead(),cue=careLine(state.careCue),task=state.careTask;let work='';if(task==='morning'){const feeling=state.careFeeling||db.feeling;const model=careLine('feeling-'+(feeling||'happy'));work=`<h2>Hôm nay em cảm thấy…</h2><div class="care-choices">${[['happy','😊','Happy','Vui'],['tired','😴','Tired','Mệt'],['excited','🤩','Excited','Hào hứng']].map(([id,icon,en,vi])=>`<button class="care-choice ${feeling===id?'on':''}" onclick="careFeeling('${id}')"><span>${icon}</span><b>${en}</b><small>${vi}</small></button>`).join('')}</div><div class="care-student"><span>Đến lượt em</span><h3>Good morning!</h3><p>Chào buổi sáng!</p><h3>${esc(model.studentEn)}</h3><p>${esc(model.vietnamese.student)}</p><button class="chip" onclick="careSpeak('Good morning! '+${esc(JSON.stringify(model.studentEn))})">🔊 Nghe câu của em</button></div><button class="primary" onclick="careMorningDone()">Em đã chào và thử nói</button><p class="small">Mệt cũng không sao. Em có thể luyện ít hoặc nghỉ; không bị trừ sao.</p>`}
else if(task==='feeding'){const foods=[['corn','🌽','Corn','Bắp ngô'],['fish','🐟','Fish','Cá suối'],['rice','🍚','Bamboo rice','Cơm lam'],['apple','🍎','Apple','Táo']],line=careLine('feed-'+state.careFood);work=`<h2>Mình cùng chuẩn bị bữa ăn</h2><label>Chọn yêu cầu để luyện <select onchange="careWantFood(this.value)">${foods.map(([id,_,en,vi])=>`<option value="${id}" ${state.careFood===id?'selected':''}>${en} · ${vi}</option>`).join('')}</select></label><p>Tìm món rô-bốt muốn ăn: <b>${esc(line.robotEn)}</b></p><div class="care-choices">${foods.map(([id,icon,en,vi])=>`<button class="care-choice ${state.careChosenFood===id?'on':''}" onclick="careGiveFood('${id}')"><span>${icon}</span><b>${en}</b><small>${vi}</small></button>`).join('')}</div><div class="care-student"><span>Đưa món rồi thử nói</span><h3>${esc(line.studentEn)}</h3><p>${esc(line.vietnamese.student)}</p><button class="chip" onclick="careSpeak(${esc(JSON.stringify(line.studentEn))})">🔊 Nghe mẫu</button></div><button class="primary" ${state.careChosenFood!==state.careFood?'disabled':''} onclick="careFoodDone()">Em đã đưa món và thử nói</button><p class="small">Biểu tượng cơm chỉ gợi nhớ; món được học ở đây là cơm lam. Cá trong tình huống là cá suối, từ fish chỉ cá nói chung.</p>`}
else if(task==='cleaning'){const tips={book:['/k/','Khép phần sau lưỡi, rồi bật nhẹ; không thêm “cờ”.'],cat:['/t/','Chạm đầu lưỡi phía sau răng trên, rồi thả nhẹ; không thêm “tờ”.'],bus:['/s/','Cho hơi đi nhẹ qua khe răng; không thêm “sờ”.']};const line=careLine('clean-'+state.careWord),tip=tips[state.careWord];work=`<h2>Lau ba vết bụi, thử ba âm cuối</h2><div class="care-choices">${[['book','📘'],['cat','🐱'],['bus','🚌']].map(([w,icon])=>`<button class="care-choice ${state.careWord===w?'on':''}" onclick="carePickWord('${w}')"><span>${icon}</span><b>${w}</b><small>${tips[w][0]} ${db.cleanWords.includes(w)?'· đã thử':''}</small></button>`).join('')}</div><div class="care-student"><span>Nghe cả từ rồi thử nói</span><h3>${esc(line.studentEn)} <small class="ipa">${esc(line.studentIpa)}</small></h3><p>${esc(tip[1])}</p><button class="primary" onclick="careSpeak(${esc(JSON.stringify(state.careWord))})">🔊 Nghe từ mẫu</button> <button class="chip" onclick="careSetCue('clean-repeat')">Em muốn thử lại</button></div><button class="primary" onclick="careCleanTry()">Em đã thử nói · Lau một vết bụi</button><p class="notice">Vết bụi biến mất để ghi nhận em đã luyện. App không tự kết luận em phát âm đúng.</p><details class="care-adult"><summary>Dành cho phụ huynh / giáo viên</summary><p>Nghe học sinh đọc cả từ. Chỉ xác nhận khi âm cuối ${esc(tip[0])} nghe rõ, không thêm âm “ờ”. Có thể nghe mẫu và thử lại; không cần ép em đọc nhiều lần.</p><label><input type="checkbox" ${state.careAdult?'checked':''} onchange="state.careAdult=this.checked;render()"> Tôi đã nghe và xác nhận âm cuối từ ${esc(state.careWord)} rõ.</label><button class="chip" ${state.careAdult?'':'disabled'} onclick="careAdultVerify()">Xác nhận của người lớn</button><small>${db.verifiedWords.includes(state.careWord)?'Đã có xác nhận của người lớn cho từ này.':'Chưa có xác nhận; lượt tự luyện vẫn được ghi nhận.'}</small></details>`}
else{work=`<h2>Một lời chúc trước giờ ngủ</h2><div class="care-student"><span>Đến lượt em</span><h3>Good night, my friend.</h3><p>Chúc bạn ngủ ngon.</p><button class="chip" onclick="careSpeak('Good night, my friend.')">🔊 Nghe mẫu</button></div><button class="primary" onclick="careNightDone()">Em đã chúc ngủ ngon</button><button class="chip" onclick="careSetCue('night-see-you')">Hẹn gặp ngày mai</button><p class="small">Có thể đóng vai vào bất cứ lúc nào, không cần chờ đến tối. Rời app nghỉ ngơi khi em muốn.</p>`}
return header('CHĂM SÓC RÔ-BỐT','Bạn Rô-bốt bản làng · Nghe, nói và chăm sóc mỗi ngày')+`<div class="care-toolbar"><button class="chip" onclick="goto('vocab')">📚 Học từ vựng</button><label><input type="checkbox" ${state.careSound?'checked':''} onchange="state.careSound=this.checked"> Âm hiệu nhẹ</label><span>${state.user?'Hồ sơ: '+esc(state.user.name):'Hồ sơ khách · Chọn hồ sơ khi dùng chung máy'}</span>${state.user?'':'<button class="chip" onclick="openAuth()">Chọn hồ sơ</button>'}</div><nav class="care-task-tabs" aria-label="Bốn nhiệm vụ chăm sóc">${careTasks.map(([id,icon,title,desc])=>`<button class="${task===id?'on':''}" onclick="careSelectTask('${id}')"><span>${icon}</span><b>${title}</b><small>${desc}</small>${db.completed.includes(id)?'<em>✓ Đã luyện</em>':''}</button>`).join('')}</nav><section class="care-room"><aside class="panel care-mascot animation-${esc(cue.feedback.animation)}"><div class="care-battery"><b>🔋 Pin ${db.battery}%</b><progress value="${db.battery}" max="100">${db.battery}%</progress></div><div class="care-robot-stage">${mountainRobot()}${task==='cleaning'?Array.from({length:Math.max(0,3-db.cleanWords.length)},(_,i)=>`<span class="care-dust dust-${i}" aria-hidden="true">✦</span>`).join(''):''}${task==='goodnight'&&db.completed.includes('goodnight')?'<span class="care-zzz">Z z z</span>':''}</div><span class="care-name">Bạn Rô-bốt bản làng</span><div class="care-speech" aria-live="polite"><h2>${esc(cue.robotEn)}</h2><p class="ipa">${esc(cue.robotIpa)}</p><p>${esc(cue.vietnamese.robot)}</p><button class="primary" onclick="careSpeak(${esc(JSON.stringify(cue.robotEn))})">🔊 Nghe rô-bốt</button></div><p>${db.completed.length}/4 nhiệm vụ đã luyện hôm nay</p><small>Không mất pin hoặc sao khi nghỉ học. Ngày mới có lượt luyện mới.</small></aside><section class="panel care-work">${work}</section></section><p class="notice">Em nói trực tiếp với rô-bốt rồi bấm xác nhận đã luyện. Không bật micro hoặc gửi giọng nói đi. IPA theo giọng Anh Mỹ; giọng đọc phụ thuộc thiết bị. Đây là ghi nhận luyện tập, không phải điểm phát âm.</p>${careScriptTable()}`}
const careRenderBase=render;render=function(){if(state.page==='care'){$('#app').innerHTML=layout(carePage());return}careRenderBase()};
const careGotoBase=goto;goto=function(page){if(state.page==='care'&&page!=='care'){stopSpeech();state.careAdult=false}if(page==='care'&&state.page!=='care'){state.careTask='morning';state.careCue='morning-low';state.careFeeling='';state.careAdult=false}careGotoBase(page)};
const careAuthBase=openAuth;openAuth=function(){state.careAdult=false;state.careFeeling='';state.careTask='morning';state.careCue='morning-low';stopSpeech();careAuthBase()};
const careLink=dainganLinks.find(x=>x[0].startsWith('Chăm sóc Rô bốt'));careLink[0]='Chăm sóc Rô bốt';careLink[5]="goto('care')";


const DN_ROBOT_EMBEDDED="./assets/b9ed34b66e9d8de145cb390a.webp";
