// Popup luyện nói độc lập: không khởi tạo micro khi tải trang.
let dnSession=null;
const dnGuestAwards=new Set();
const dnElement=id=>document.getElementById('dn-'+id);
function dnNormalize(text){return String(text).toLowerCase().replace(/[’']/g,'').replace(/\bi[’']?m\b/g,'i am').replace(/[^a-z0-9]+/g,' ').trim()}
function dnMatches(text,lesson){return [lesson.target,...(lesson.alternatives||[])].some(answer=>dnNormalize(text)===dnNormalize(answer))}
function dnStatus(text){if(dnElement('status'))dnElement('status').textContent=text}
function dnPose(pose){const stage=dnElement('stage');if(!stage)return;stage.dataset.state=pose;dnElement('state').textContent={idle:'Sẵn sàng cùng em',speaking:'Rô-bốt đang nói',listening:'Rô-bốt đang lắng nghe',happy:'Em đã làm được rồi!',help:'Mình cùng thử lại nhé!'}[pose]||''}
// Hủy phiên trước; callback muộn không được chấm nhầm câu mới.
function dnStopMic(){const s=dnSession;if(!s)return;s.ticket++;clearTimeout(s.micTimer);clearTimeout(s.stopTimer);const rec=s.rec;s.rec=null;s.phase='idle';try{if(rec)rec.abort()}catch{}const mic=dnElement('mic');if(mic){mic.setAttribute('aria-pressed','false');mic.setAttribute('aria-label','Bật micro để nói')}dnPose('idle')}
function dnCancelVoice(){const s=dnSession;if(s){s.voice++;clearTimeout(s.voiceTimer)}try{window.speechSynthesis?.cancel()}catch{}}
// Giọng đọc hoàn toàn độc lập với API micro, gồm cả khi không cấp quyền.
function dnSpeak(text,rate=.85,lang='en-US',pose='idle'){
 if(!dnSession)return;dnStopMic();dnCancelVoice();const s=dnSession,token=s.voice;
 try{if(!window.speechSynthesis||typeof window.SpeechSynthesisUtterance!=='function')throw new Error('voice');const u=new window.SpeechSynthesisUtterance(text);u.lang=lang;u.rate=rate;u.pitch=1;
 const voices=window.speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang===lang&&v.localService)||voices.find(v=>v.lang===lang)||null;
 u.onstart=()=>{if(dnSession===s&&token===s.voice)dnPose(pose==='happy'?'happy':'speaking')};u.onend=()=>{if(dnSession===s&&token===s.voice){clearTimeout(s.voiceTimer);dnPose(pose)}};
 u.onerror=()=>{if(dnSession===s&&token===s.voice){dnPose(pose);dnStatus('Giọng mẫu chưa phát được. Em vẫn chuyển câu và đọc cùng người lớn nhé.')}};
 window.speechSynthesis.speak(u);s.voiceTimer=setTimeout(()=>{if(dnSession===s&&token===s.voice)dnPose(pose)},Math.max(4000,text.length*160/rate))
 }catch{dnPose(pose);dnStatus('Máy chưa có giọng đọc phù hợp. Em vẫn xem câu mẫu, chuyển câu và luyện cùng người lớn được.')}
}
function dnKnownAwards(){if(!state.user)return Array.from(dnGuestAwards);try{return offlineStore().attempts.filter(a=>a.username===state.user.username&&a.activity?.startsWith('classroom-speaking-v1:')&&a.stars===2).map(a=>a.activity.slice(22))}catch{return []}}
// Mỗi tình huống chỉ được cộng +2 sao một lần cho mỗi hồ sơ.
function dnAward(id,source){
 if(!state.user){const duplicate=dnGuestAwards.has(id);dnGuestAwards.add(id);return {ok:true,duplicate,guest:true}}
 try{const db=offlineStore(),user=state.user.username,activity='classroom-speaking-v1:'+id;if(db.user!==user)return {ok:false};if(db.attempts.some(a=>a.username===user&&a.activity===activity&&a.stars===2))return {ok:true,duplicate:true};
 db.attempts.push({username:user,activity,skill:'Nói',stars:2,date:new Date().toISOString(),source});db.learned[user]??=[];if(!db.learned[user].includes(activity))db.learned[user].push(activity);saveOffline(db);refresh().catch(()=>{});return {ok:true}
 }catch{return {ok:false}}
}
function dnUpdateScore(){if(!dnSession)return;dnElement('score').textContent='⭐ '+dnSession.awarded.size*2+' sao · '+dnSession.awarded.size+'/8 câu'}
function dnGrade(correct,source='adult'){
 const s=dnSession;if(!s)return;dnStopMic();dnCancelVoice();clearTimeout(s.nextTimer);const lesson=classroomConversations[s.index];
 if(correct){const award=dnAward(lesson.id,source);if(award.ok)s.awarded.add(lesson.id);dnUpdateScore();dnPose('happy');dnElement('reward').textContent='⭐ ⭐ ⭐';
 dnStatus(!award.ok?'Em đã làm được! Chưa lưu được sao; em có thể thử lại.':award.duplicate?'Rất tốt! Câu này đã được thưởng sao trước đó.':award.guest?'Rất tốt! +2 sao trong phiên khách. Chọn hồ sơ ở trang chủ để lưu thành tích.':'Rất tốt! +2 sao đã được thêm vào bảng vinh danh.');
 dnSpeak('Excellent! Good job!',.85,'en-US','happy');
 if(award.ok&&s.index<7)s.nextTimer=setTimeout(()=>{if(dnSession===s)dnLoad(s.index+1)},4500);
 }else{dnElement('reward').textContent='';dnElement('hint').hidden=false;dnPose('help');dnStatus('Cảm ơn em đã thử! Mình nghe chậm rồi nói lại nhé. Không trừ sao.');dnSpeak('Good try! Listen again!',.85,'en-US','help');s.nextTimer=setTimeout(()=>{if(dnSession===s)dnSpeak(lesson.target,.6,'en-US','help')},2400)}
}
// Nút chuyển câu luôn dùng được, kể cả không có Internet hoặc micro.
function dnLoad(index){const s=dnSession;if(!s)return;clearTimeout(s.nextTimer);dnStopMic();dnCancelVoice();s.index=(index+8)%8;const l=classroomConversations[s.index];
 for(const [id,value] of Object.entries({topic:l.topic,title:l.title,question:l.robot,translation:l.robotVi,target:l.target,meaning:l.vi,ipa:l.ipa,art:l.art,hint:l.hint}))dnElement(id).textContent=value;
 dnElement('art').setAttribute('aria-label',l.artLabel);dnElement('select').value=String(s.index);dnElement('reward').textContent='';dnElement('heard').textContent='';dnElement('hint').hidden=true;dnElement('next').textContent=s.index===7?'Về câu đầu ↻':'Câu tiếp theo →';dnElement('manual').open=false;dnStatus('Bấm loa nghe mẫu, sau đó bấm micro để nói.');dnPose('idle');dnUpdateScore()
}
function dnFinishMic(){const s=dnSession;if(!s)return;if(s.phase==='starting'){s.stopWhenReady=true;return}if(s.phase!=='listening')return;s.phase='processing';clearTimeout(s.micTimer);dnElement('mic').setAttribute('aria-pressed','false');dnStatus('Đang chuyển lời nói thành văn bản…');try{s.rec.stop()}catch{dnStopMic();dnStatus('Micro đã dừng. Em có thể nghe mẫu hoặc thử lại.');return}const ticket=s.ticket;s.stopTimer=setTimeout(()=>{if(dnSession===s&&s.ticket===ticket){dnStopMic();dnStatus('Chưa có kết quả nhận dạng. Em vẫn chuyển câu hoặc nhờ người lớn chấm được.')}},7000)}
// Bảo vệ cả constructor, start, stop và các callback của Web Speech API.
function dnStartMic(){
 const s=dnSession;if(!s)return;if(s.phase!=='idle'){dnFinishMic();return}
 if(!dnElement('consent').checked){dnStatus('Người lớn đọc và đánh dấu đồng ý trước khi bật micro. Em vẫn nghe mẫu, chuyển câu và chấm thủ công được.');dnElement('consent').focus();return}
 clearTimeout(s.nextTimer);dnCancelVoice();dnStopMic();const ticket=s.ticket,index=s.index;let got=false;
 try{const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(typeof Recognition!=='function'){dnStatus('Trình duyệt chưa hỗ trợ nhận dạng. Em vẫn nghe mẫu, chuyển câu và nhờ người lớn chấm được.');return}
 const rec=new Recognition();s.rec=rec;s.phase='starting';s.stopWhenReady=false;rec.lang='en-US';rec.continuous=false;rec.interimResults=false;rec.maxAlternatives=1;dnElement('mic').setAttribute('aria-pressed','true');dnPose('listening');dnStatus('Đang mở micro… Em cho phép micro nếu trình duyệt hỏi nhé.');
 const active=()=>dnSession===s&&s.ticket===ticket&&s.index===index;
 rec.onstart=()=>{if(!active())return;s.phase='listening';dnElement('mic').setAttribute('aria-label','Dừng micro');dnStatus('Đang lắng nghe em nói...');clearTimeout(s.micTimer);s.micTimer=setTimeout(dnFinishMic,12000);if(s.stopWhenReady)dnFinishMic()};
 rec.onspeechend=()=>{if(active())dnFinishMic()};
 rec.onresult=event=>{if(!active()||got)return;try{const text=event.results?.[0]?.[0]?.transcript;if(!text?.trim())return;got=true;dnElement('heard').textContent='Máy nghe được: “'+text+'”';dnGrade(dnMatches(text,classroomConversations[index]),'recognition')}catch{dnStopMic();dnStatus('Chưa đọc được kết quả. Em thử lại hoặc nhờ người lớn chấm nhé.')}};
 rec.onerror=event=>{if(!active()||got)return;const messages={'not-allowed':'Micro bị chặn quyền.','service-not-allowed':'Dịch vụ nhận dạng đang bị chặn.','audio-capture':'Chưa tìm thấy micro.','network':'Nhận dạng cần mạng hoặc đang lỗi mạng.','no-speech':'Chưa nghe rõ câu của em.','aborted':'Đã dừng micro.'};dnStopMic();dnStatus((messages[event.error]||'Micro chưa dùng được.')+' Em vẫn nghe mẫu, chuyển câu và chấm thủ công được.')};
 rec.onend=()=>{if(!active()||got)return;dnStopMic();dnStatus('Chưa nhận được câu nói. Em thử lại khi sẵn sàng nhé.')};
 s.micTimer=setTimeout(()=>{if(active()){dnStopMic();dnStatus('Micro chưa khởi động được. Em vẫn nghe mẫu và chuyển câu được.')}},12000);rec.start()
 }catch{dnStopMic();dnStatus('Không mở được micro. Kiểm tra quyền hoặc dùng phần chấm của người lớn; các nút khác vẫn hoạt động.')}
}
function dnClose(){const s=dnSession;if(!s)return;clearTimeout(s.nextTimer);dnStopMic();dnCancelVoice();document.removeEventListener('keydown',dnKey);document.removeEventListener('visibilitychange',dnVisibility);dnSession=null;dnElement('speaking');document.getElementById('dn-speaking')?.remove();const app=document.getElementById('app');if(app)app.inert=false;document.body.style.overflow=s.overflow;
 const restore=()=>{if(dnSession)return;try{render();if(s.focus?.isConnected)s.focus.focus();else document.querySelector('.home-hotspot[aria-label="Luyện nói cùng rô bốt"]')?.focus()}catch{}};if(state.user)refresh().then(restore).catch(restore);else restore()
}
function dnKey(event){if(!dnSession)return;if(event.key==='Escape'){event.preventDefault();dnClose();return}if(event.key==='Tab'){const nodes=Array.from(document.getElementById('dn-speaking').querySelectorAll('button,select,input,summary')).filter(n=>!n.disabled&&n.getClientRects().length);const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}}
function dnVisibility(){if(document.hidden&&dnSession){clearTimeout(dnSession.nextTimer);dnStopMic();dnCancelVoice()}}
function dnOpen(){
 if(dnSession)return;try{if(typeof releaseRobotAudio==='function')releaseRobotAudio();window.speechSynthesis?.cancel()}catch{}
 const s={index:0,ticket:0,voice:0,phase:'idle',rec:null,awarded:new Set(dnKnownAwards()),overflow:document.body.style.overflow,focus:document.activeElement};dnSession=s;
 const popup=document.createElement('section');popup.id='dn-speaking';popup.setAttribute('role','dialog');popup.setAttribute('aria-modal','true');popup.setAttribute('aria-labelledby','dn-heading');
 popup.innerHTML=`<header class="dn-bar"><div><h2 id="dn-heading">Luyện nói cùng Rô-bốt Dẻ Triêng</h2><p>Đại Ngàn Song Ngữ · Cùng em tự tin mỗi ngày</p></div><button id="dn-close" type="button" aria-label="Đóng luyện nói">✕ Đóng</button></header><div class="dn-wrap"><div class="dn-trim"></div><div class="dn-toolbar"><label>Tình huống <select id="dn-select" aria-label="Chọn tình huống">${classroomConversations.map((l,i)=>`<option value="${i}">${i+1}/8 · ${esc(l.title)}</option>`).join('')}</select></label><span class="dn-score" id="dn-score"></span></div><div class="dn-grid"><div class="dn-scene"><div class="dn-stage" id="dn-stage" data-state="idle"><img class="dn-robot" id="dn-robot" alt="Bạn Rô-bốt Dẻ Triêng mặc trang phục thổ cẩm" draggable="false"><span class="dn-star" aria-hidden="true">✦</span><span class="dn-waves" aria-hidden="true">)))</span><span class="dn-fireworks" aria-hidden="true">⭐ ✨ ⭐</span></div><p class="dn-state" id="dn-state"></p><div id="dn-reward" aria-live="polite"></div></div><section class="dn-lesson"><p class="dn-topic" id="dn-topic"></p><div class="dn-art" id="dn-art" role="img"></div><h3 id="dn-title"></h3><div class="dn-bubble"><p id="dn-question" lang="en"></p><small id="dn-translation"></small></div><small>Em nói:</small><p class="dn-target" id="dn-target" lang="en"></p><p class="dn-vi" id="dn-meaning"></p><p class="dn-ipa" id="dn-ipa"></p><div class="dn-actions"><button id="dn-question-audio" type="button">🔊 Nghe rô-bốt hỏi</button><button id="dn-sample" type="button">🔊 Nghe câu trả lời</button><button id="dn-slow" type="button">🐢 Nghe chậm 0.6x</button></div><div class="dn-microw"><button id="dn-mic" type="button" aria-label="Bật micro để nói" aria-pressed="false"><svg viewBox="0 0 32 32" aria-hidden="true"><rect x="11" y="3" width="10" height="17" rx="5" fill="currentColor"/><path d="M7 15v2a9 9 0 0018 0v-2M16 26v4M11 30h10" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg></button><p id="dn-status" role="status" aria-live="polite"></p></div><p class="dn-heard" id="dn-heard"></p><p class="dn-hint" id="dn-hint" hidden></p><label class="dn-consent"><input id="dn-consent" type="checkbox">Người lớn đồng ý bật micro. Dịch vụ nhận dạng của trình duyệt có thể gửi giọng nói qua mạng; ứng dụng không lưu bản ghi âm.</label><div class="dn-nav"><button id="dn-prev" type="button">← Câu trước</button><button id="dn-next" type="button">Câu tiếp theo →</button></div></section></div><details id="dn-manual"><summary>Phụ huynh / giáo viên chấm khi không dùng micro</summary><p>Nghe học sinh nói rồi chọn nhận xét. Mỗi câu đạt được +2 sao một lần.</p><div class="dn-manual"><button id="dn-adult-good" type="button">Đã nói được · +2 sao</button><button id="dn-adult-retry" type="button">Cùng thử lại</button></div></details><p class="dn-note">Nhận dạng chỉ đối chiếu câu chữ máy nghe được, không xác định chính xác âm cuối. Nếu nhận dạng chưa dùng được khi mở tệp trực tiếp, em vẫn nghe giọng có sẵn, chuyển đủ 8 câu và luyện cùng người lớn. ${state.user?'Sao được lưu vào hồ sơ đang chọn.':'Phiên khách: sao chỉ giữ trong phiên này; chọn hồ sơ ở trang chủ để lưu thành tích.'}</p></div>`;
 document.body.append(popup);document.body.style.overflow='hidden';const app=document.getElementById('app');if(app)app.inert=true;
 dnElement('close').onclick=dnClose;dnElement('prev').onclick=()=>dnLoad(s.index-1);dnElement('next').onclick=()=>dnLoad(s.index+1);dnElement('select').onchange=e=>dnLoad(Number(e.target.value));
 dnElement('sample').onclick=()=>{clearTimeout(s.nextTimer);dnSpeak(classroomConversations[s.index].target)};dnElement('question-audio').onclick=()=>{clearTimeout(s.nextTimer);const l=classroomConversations[s.index];dnSpeak(l.robot,.85,l.robotLang||'en-US')};dnElement('slow').onclick=()=>{clearTimeout(s.nextTimer);dnSpeak(classroomConversations[s.index].target,.6)};dnElement('mic').onclick=dnStartMic;
 dnElement('consent').onchange=e=>{if(!e.target.checked){dnStopMic();dnStatus('Đã tắt micro. Em vẫn nghe mẫu và chuyển câu được.')}};
 dnElement('adult-good').onclick=()=>dnGrade(true,'adult');dnElement('adult-retry').onclick=()=>dnGrade(false,'adult');const img=dnElement('robot');img.onerror=()=>{img.onerror=null;img.src=DN_ROBOT_EMBEDDED};img.src=ROBOT_IMG_URL||DN_ROBOT_EMBEDDED;
 document.addEventListener('keydown',dnKey);document.addEventListener('visibilitychange',dnVisibility);dnLoad(0);dnElement('close').focus()
}
const dnOriginalGoto=goto;goto=function(page){if(page==='speaking'){dnOpen();return}if(dnSession)dnClose();dnOriginalGoto(page)};
window.addEventListener('pagehide',()=>{if(dnSession){clearTimeout(dnSession.nextTimer);dnStopMic();dnCancelVoice()}});

