document.documentElement.style.setProperty("--dn-original-art-4",'url("'+ASSET_URLS["assets/story-robot.webp"]+'")');
document.documentElement.style.setProperty("--dn-original-art-5",'url("'+ASSET_URLS["assets/garden-world.webp"]+'")');
