// Dữ liệu cũ hỏng hoặc quyền lưu bị chặn không được làm trắng trang chủ.
offlineStore=function(){try{const db=JSON.parse(localStorage.getItem(OFFLINE_KEY)||'null');if(!db||typeof db!=='object'||Array.isArray(db))throw 0;db.profiles=Array.isArray(db.profiles)?db.profiles.filter(p=>p&&typeof p.username==='string'):[];db.attempts=Array.isArray(db.attempts)?db.attempts.filter(a=>a&&typeof a==='object'):[];db.learned=db.learned&&typeof db.learned==='object'&&!Array.isArray(db.learned)?db.learned:{};return db}catch{return {profiles:[],user:null,attempts:[],learned:{}}}};
const dnOriginalSay=say;say=function(text){try{dnOriginalSay(text)}catch{try{notify('Máy chưa phát được giọng đọc. Em vẫn xem học liệu được.',false)}catch{}}};
stopSpeech=function(){speechSession++;try{window.speechSynthesis?.cancel()}catch{}};
const dnAssetLayout=layout;layout=function(body){return dnAssetLayout(body).replace(/assets\/[A-Za-z0-9._-]+\.(?:webp|png|jpg|jpeg)/g,p=>ASSET_URLS[p]||p)};
// Tải học liệu trực tiếp từ chính tệp HTML, không cần máy chủ hoặc file phụ.
boot=async function(){state.data=window.EMBEDDED_DATA.content;state.lessons=window.EMBEDDED_DATA.lessons;try{state.user=(await offlineApi('/api/me')).user;if(state.user)await refresh()}catch{state.user=null}try{render()}catch(error){state.user=null;state.page='home';render();console.warn('Đã phục hồi trang chủ:',error.message)}};


