// Quy trình chăm sóc mới. Không thay đổi các phân hệ học tập khác.
const CG_KEY='daingan-care-v2';
const cgMemory={};
const cg={tab:'warmup',person:'',target:null,command:'',queue:[],selected:'',solved:false,pose:'idle',message:'',audioNote:'',recognition:null,listenToken:0,voiceToken:0,timers:[],speechTimer:null,micTimer:null,consent:false};
function cgDay(){const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function cgIdentity(){return (state.user?.username||'guest')+'|'+cgDay()}
function cgProgress(){const key=cgIdentity();let raw=cgMemory[key];if(!raw){try{raw=JSON.parse(localStorage.getItem(CG_KEY)||'{}')[key]}catch{}raw=raw&&typeof raw==='object'?raw:{};raw={battery:raw.battery===100?100:20,feeling:['happy','tired','excited'].includes(raw.feeling)?raw.feeling:'',awarded:Array.isArray(raw.awarded)?raw.awarded.filter(id=>cgItems.some(i=>i.id===id)):[]};cgMemory[key]=raw}
 if(state.user){try{const prefix='care-v2:'+cgDay()+':';raw.awarded=offlineStore().attempts.filter(a=>a.username===state.user.username&&a.stars===2&&a.activity?.startsWith(prefix)).map(a=>a.activity.slice(prefix.length))}catch{}}return raw}
function cgSave(edit){const row=cgProgress();edit(row);cgMemory[cgIdentity()]=row;try{let all=JSON.parse(localStorage.getItem(CG_KEY)||'{}');if(!all||typeof all!=='object'||Array.isArray(all))all={};all[cgIdentity()]=row;localStorage.setItem(CG_KEY,JSON.stringify(all));return true}catch{return false}}
function cgAward(item){const p=cgProgress();if(p.awarded.includes(item.id))return {ok:true,duplicate:true};if(!state.user){cgSave(r=>r.awarded.push(item.id));return {ok:true,guest:true}}
 try{const db=offlineStore(),name=state.user.username,activity='care-v2:'+cgDay()+':'+item.id;if(db.user!==name)return {ok:false};if(db.attempts.some(a=>a.username===name&&a.activity===activity&&a.stars===2))return {ok:true,duplicate:true};db.attempts.push({username:name,activity,skill:'Nghe',stars:2,date:new Date().toISOString(),source:'care-picture-match'});db.learned[name]??=[];if(!db.learned[name].includes(activity))db.learned[name].push(activity);saveOffline(db);refresh().catch(()=>{});return {ok:true}}catch{return {ok:false}}
}
function cgSetMessage(text){cg.message=text;const node=document.getElementById('cg-feedback');if(node)node.textContent=text}
function cgSetPose(pose){cg.pose=pose;const node=document.getElementById('cg-stage');if(node)node.dataset.pose=pose}
function cgSetAudioNote(text){cg.audioNote=text;const node=document.getElementById('cg-audio-note');if(node)node.textContent=text}
function cgCancelVoice(){cg.voiceToken++;clearTimeout(cg.speechTimer);try{window.speechSynthesis?.cancel()}catch{}}
function cgStopMic(){cg.listenToken++;clearTimeout(cg.micTimer);const r=cg.recognition;cg.recognition=null;try{r?.abort()}catch{}const b=document.getElementById('cg-mic');if(b)b.setAttribute('aria-pressed','false')}
function cgStop(){cgStopMic();cgCancelVoice();cg.timers.forEach(clearTimeout);cg.timers=[];cg.pose='idle'}
// Giọng đọc an toàn; thiếu giọng đọc hoặc dịch vụ bị chặn không làm hỏng trang.
function cgSpeak(text,rate=.85,after=null,rest='idle'){
 cgStopMic();cgCancelVoice();const token=cg.voiceToken,person=cgIdentity();let ended=false;
 const finish=()=>{if(ended||token!==cg.voiceToken||person!==cgIdentity()||state.page!=='care')return;ended=true;clearTimeout(cg.speechTimer);cgSetPose(rest);if(after)after()};
 try{if(!window.speechSynthesis||typeof window.SpeechSynthesisUtterance!=='function')throw new Error('no-voice');const u=new window.SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=rate;const voices=window.speechSynthesis.getVoices();const voice=voices.find(v=>v.lang==='en-US'&&v.localService)||voices.find(v=>v.lang.startsWith('en'));if(voice)u.voice=voice;
 u.onstart=()=>{if(token===cg.voiceToken){cgSetAudioNote('');cgSetPose(rest==='happy'?'happy':'talking')}};u.onend=finish;u.onerror=()=>{if(token!==cg.voiceToken)return;cgSetAudioNote('Chưa phát được giọng đọc. Người lớn có thể mở lời gợi ý để đọc cho em nghe.');finish()};window.speechSynthesis.speak(u);if(!ended)cg.speechTimer=setTimeout(finish,Math.max(7000,text.length*180/rate))
 }catch{cgSetAudioNote('Máy chưa có giọng đọc. Mở lời gợi ý để người lớn đọc, hoặc thử nút loa khi đã cài giọng tiếng Anh.');finish()}
}
function cgBell(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;const ac=new Audio();if(ac.state==='suspended')ac.resume().catch(()=>{});[660,880,1100].forEach((f,i)=>{const osc=ac.createOscillator(),gain=ac.createGain(),at=ac.currentTime+i*.12;osc.connect(gain);gain.connect(ac.destination);osc.frequency.value=f;gain.gain.setValueAtTime(.035,at);gain.gain.exponentialRampToValueAtTime(.001,at+.24);osc.start(at);osc.stop(at+.25)});const t=setTimeout(()=>{ac.close().catch(()=>{})},750);cg.timers.push(t)}catch{}}
function cgShuffle(items){const a=items.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function cgCommands(item){if(item.commands)return item.commands;if(item.tab==='meals'){const request=['noodles','soup','salad','bread','pizza','water','milk','juice','lemonade'].includes(item.id)?'some '+item.en:'the '+item.en;return ['Can you give me '+request+'?','I want '+request+', please!']}
 return item.tab==='dress'?['Please give me my '+item.en+'!',(item.plural?'Where are my ':'Where is my ')+item.en+'?']:['Can you find my '+item.en+'?','Give me my '+item.en+', please!']}
function cgSelect(tab){if(!cgTabs.some(t=>t[0]===tab))return;cgStop();cg.tab=tab;cg.queue=[];cg.target=null;cg.selected='';cg.solved=false;cg.message='';cg.audioNote='';if(tab==='warmup'){render();cgSpeak(Math.random()<.5?'Good morning, friend!':'Hello, how are you today?');return}cgNext()}
function cgNext(){if(cg.tab==='warmup')return;cgStop();const previous=cg.target?.id;if(!cg.queue.length){cg.queue=cgShuffle(cgItems.filter(i=>i.tab===cg.tab));if(cg.queue.length>1&&cg.queue[cg.queue.length-1].id===previous)[cg.queue[0],cg.queue[cg.queue.length-1]]=[cg.queue[cg.queue.length-1],cg.queue[0]]}cg.target=cg.queue.pop();const phrases=cgCommands(cg.target);cg.command=phrases[Math.floor(Math.random()*phrases.length)];cg.selected='';cg.solved=false;cg.message='Nghe yêu cầu rồi chạm vào một hình nhé.';cg.audioNote='';cg.pose='idle';render();cgSpeak(cg.command)}
function cgChoose(id){if(!cg.target||cg.solved||state.page!=='care')return;const item=cgItems.find(i=>i.id===id&&i.tab===cg.tab);if(!item)return;cgStop();cg.selected=id;
 if(id===cg.target.id){cg.solved=true;const award=cgAward(item);cg.pose='happy';cg.message=award.ok?(award.duplicate?'Em chọn đúng rồi! Món này đã nhận sao hôm nay.':'Đúng rồi! +2 sao '+(award.guest?'cho phiên khách.':'đã được thêm vào bảng vinh danh.')):'Em chọn đúng rồi! Chưa lưu được sao trên thiết bị này.';render();cgBell();cgSpeak('Thank you! '+(item.plural?'These are my ':'This is my ')+item.en+'!',.85,null,'happy')}
 else{cg.pose='help';cg.message='Cảm ơn em đã thử! Mình nghe chậm và chọn lại nhé. Không trừ sao.';render();cgSpeak('Oops! Listen again, please!',.85,()=>cgSpeak(cg.command,.6,null,'help'),'help')}
}
function cgFeeling(feeling){if(!['happy','tired','excited'].includes(feeling))return;cgStop();cgSave(p=>{p.feeling=feeling;p.battery=100});cg.pose='happy';cg.message='Cảm ơn em! Pin đã đầy. Hôm nay mình cùng học thật vui nhé!';render();cgBell();cgSpeak('Thank you! I feel great!',.85,null,'happy')}
// Micro chỉ được bật trong tab Khởi động, sau thao tác và đồng ý của người lớn.
function cgMicro(){if(cg.recognition){cgStopMic();cgSetMessage('Đã dừng micro. Em vẫn chọn cảm xúc để sạc pin được.');return}if(!cg.consent){cgSetMessage('Người lớn đọc và đồng ý trước khi bật micro. Em có thể chọn cảm xúc thay thế.');document.getElementById('cg-consent')?.focus();return}cgCancelVoice();cgStopMic();const ticket=cg.listenToken,person=cgIdentity();let got=false;
 try{const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(typeof Recognition!=='function'){cgSetMessage('Máy chưa hỗ trợ nhận dạng. Chọn một khuôn mặt để nạp pin nhé!');return}const rec=new Recognition();cg.recognition=rec;rec.lang='en-US';rec.continuous=false;rec.interimResults=false;rec.maxAlternatives=1;const active=()=>ticket===cg.listenToken&&person===cgIdentity()&&state.page==='care'&&cg.tab==='warmup';
 document.getElementById('cg-mic')?.setAttribute('aria-pressed','true');cgSetMessage('Đang mở micro…');
 rec.onstart=()=>{if(active())cgSetMessage('Đang lắng nghe em nói...')};
 rec.onresult=e=>{if(!active()||got)return;try{const text=e.results?.[0]?.[0]?.transcript||'';if(!text.trim())return;got=true;cgStopMic();const normalized=dnNormalize(text);const feeling=['happy','tired','excited'].find(f=>normalized==='i am '+f);if(feeling||['hello robot','hello','good morning','good morning robot'].includes(normalized)){cgFeeling(feeling||cgProgress().feeling||'happy')}else{cgSetMessage('Mình cùng thử câu “Hello Robot!” hoặc “I am happy!” nhé. Em cũng có thể chọn khuôn mặt.');cgSpeak('Hello Robot!',.6)}}catch{cgStopMic();cgSetMessage('Chưa nhận được lời chào. Em chọn cảm xúc để sạc pin nhé.')}};
 rec.onerror=e=>{if(!active()||got)return;cgStopMic();cgSetMessage((e.error==='not-allowed'?'Micro bị chặn quyền. ':e.error==='network'?'Nhận dạng đang lỗi mạng. ':'Chưa nghe rõ lời chào. ')+'Em vẫn chọn cảm xúc để sạc pin được.')};rec.onend=()=>{if(active()&&!got){cgStopMic();cgSetMessage('Em thử lại khi sẵn sàng, hoặc chọn cảm xúc nhé.')}};
 cg.micTimer=setTimeout(()=>{if(active()){cgStopMic();cgSetMessage('Micro đã dừng. Chọn cảm xúc hoặc bấm micro thử lại nhé.')}},15000);rec.start()
 }catch{cgStopMic();cgSetMessage('Không mở được micro. Trang vẫn hoạt động: em chọn cảm xúc để sạc pin nhé!')}
}
function cgPicture(item){if(item.icon)return `<img class="${item.blue?'cg-blue':''}" src="${esc(emojiImage(item.icon))}" alt="" draggable="false">`;const [x,y,w,h]=item.crop,[sw,sh]=cgSpriteSizes[item.sprite];return `<span class="cg-art" style="--ratio:${w}/${h};--bg:var(--cg-${item.sprite});--size:${sw/w*100}%;--px:${x/(sw-w)*100}%;--py:${y/(sh-h)*100}%" aria-hidden="true"></span>`}
function cgCard(item){return `<button type="button" class="cg-card ${cg.selected===item.id?(cg.solved?'cg-correct':'cg-retry'):''}" aria-label="Chọn ${esc(item.vi)}" onclick="cgChoose('${item.id}')">${cgPicture(item)}</button>`}
function cgWarmup(){const p=cgProgress();return `<h2>Chào ngày mới, bạn nhỏ!</h2><p class="cg-intro">Chọn cảm xúc hoặc nói một lời chào để nạp pin.</p><div class="cg-feelings">${[['happy','😊','Happy','Vui'],['tired','🥱','Tired','Mệt'],['excited','🥳','Excited','Hào hứng']].map(([id,face,en,vi])=>`<button class="${p.feeling===id?'on':''}" onclick="cgFeeling('${id}')" aria-pressed="${p.feeling===id}"><span class="face">${face}</span><b>${en}</b><small>${vi}</small></button>`).join('')}</div><div class="cg-model"><p>Em có thể nói:</p><b lang="en">Hello Robot!</b><p>Chào bạn Rô-bốt!</p><b lang="en">I am happy!</b><p>Mình đang vui!</p><button class="chip" onclick="cgSpeak('Hello Robot! I am happy!',.6)">🔊 Nghe mẫu chậm</button></div><button id="cg-mic" class="cg-mic" onclick="cgMicro()" aria-label="Bật hoặc dừng micro chào rô-bốt" aria-pressed="false">🎤</button><span> Bấm để nói lời chào</span><label class="cg-consent"><input id="cg-consent" type="checkbox" ${cg.consent?'checked':''} onchange="cg.consent=this.checked;if(!this.checked)cgStopMic()">Người lớn đồng ý dùng micro. Dịch vụ của trình duyệt có thể gửi giọng nói qua mạng; ứng dụng không lưu bản ghi âm.</label><p class="cg-note">Nhận dạng chỉ đối chiếu câu chữ, không đánh giá chính xác phát âm. Nếu không có micro hoặc mạng, chọn cảm xúc vẫn sạc đầy pin.</p>`}
carePage=function(){const who=cgIdentity();if(cg.person!==who){cgStop();cg.person=who;cg.tab='warmup';cg.target=null;cg.queue=[];cg.selected='';cg.solved=false;cg.consent=false;cg.message='Chào em! Hôm nay em cảm thấy thế nào?'}const p=cgProgress(),tab=cgTabs.find(t=>t[0]===cg.tab)||cgTabs[0];let work='';
 if(cg.tab==='warmup')work=cgWarmup();else{const items=cgItems.filter(i=>i.tab===cg.tab);let group='';work=`<h2>${esc(tab[2])}</h2><p class="cg-intro">Chạm đúng hình theo lời rô-bốt. Không cần đọc chữ dưới tranh.</p><div class="cg-picture-grid">${items.map(item=>{let label='';if(item.group&&item.group!==group){group=item.group;label='<div class="cg-group">'+esc(group)+'</div>'}return label+cgCard(item)}).join('')}</div><div class="cg-next-row"><button class="primary" onclick="cgSpeak(cg.command)">🔊 Nghe yêu cầu</button><button class="chip" onclick="cgSpeak(cg.command,.6)">🐢 Nghe chậm 0.6x</button><button class="chip" onclick="cgNext()">${cg.solved?'Món tiếp theo →':'Đổi yêu cầu ↻'}</button></div>`}
 const instruction=cg.tab==='warmup'?'Good morning, friend!':cg.command;
 return header('CHĂM SÓC RÔ-BỐT','Nghe thật kỹ · Chọn đúng hình · Cùng bạn Rô-bốt Dẻ Triêng')+`<section class="cg-app"><div class="cg-sessionbar"><p>${state.user?'Hồ sơ: '+esc(state.user.name):'Phiên khách · Chọn hồ sơ ở trang chủ để lưu sao vào bảng vinh danh'}</p><span class="cg-score">⭐ ${p.awarded.length*2} sao hôm nay</span></div><nav class="cg-tabs" role="tablist" aria-label="Bốn hoạt động chăm sóc">${cgTabs.map(([id,icon,title,en])=>`<button role="tab" id="cg-tab-${id}" aria-controls="cg-tabpanel" aria-selected="${cg.tab===id}" onclick="cgSelect('${id}')"><span class="cg-tab-icon">${icon}</span><b>${title}</b><small>${en}</small></button>`).join('')}</nav><div class="cg-room"><aside class="cg-mascot"><div class="cg-battery">🔋 Pin ${p.battery}% <progress value="${p.battery}" max="100">${p.battery}%</progress></div><div class="cg-stage" id="cg-stage" data-pose="${cg.pose}"><img src="${esc(CG_ROBOT_IMAGE)}" alt="Bạn Rô-bốt Dẻ Triêng" draggable="false" onerror="this.onerror=null;this.src=DN_ROBOT_EMBEDDED"><span class="cg-stars" aria-hidden="true">${cg.pose==='happy'?'⭐ ✨ ⭐':''}</span></div><div class="cg-speech"><h3>${cg.tab==='warmup'?'Mình cùng chào buổi sáng!':'Nghe xem mình cần gì nhé!'}</h3><button class="primary" onclick="cgSpeak(${esc(JSON.stringify(instruction))})">🔊 Nghe rô-bốt</button><details><summary>Lời gợi ý cho người lớn</summary><p lang="en">${esc(instruction)}</p><p>${cg.target&&cg.tab!=='warmup'?'Rô-bốt cần: '+esc(cg.target.vi):'Chào buổi sáng, bạn nhỏ! Em có thể chọn cảm xúc hoặc nói lời chào.'}</p></details><p class="cg-audio-note" id="cg-audio-note">${esc(cg.audioNote)}</p></div><p class="cg-note">Mỗi món chọn đúng được +2 sao một lần mỗi ngày. Chọn chưa đúng không bị trừ sao.</p></aside><section id="cg-tabpanel" role="tabpanel" aria-labelledby="cg-tab-${cg.tab}" class="cg-work">${work}<p class="cg-feedback" id="cg-feedback" role="status" aria-live="polite">${esc(cg.message)}</p></section></div></section>`
};
const cgGotoBase=goto;goto=function(page){const entering=page==='care'&&state.page!=='care';if(state.page==='care'&&page!=='care')cgStop();cgGotoBase(page);if(entering)cgSpeak('Good morning, friend!')};
const cgOpenAuthBase=openAuth;openAuth=function(){if(state.page==='care'){cgStop();cg.person=''}cgOpenAuthBase()};
const cgLogoutBase=logout;logout=async function(){cgStop();cg.person='';await cgLogoutBase()};
window.addEventListener('pagehide',cgStop);document.addEventListener('visibilitychange',()=>{if(document.hidden)cgStop()});

for(const [name,url] of Object.entries(CG_SPRITES))document.documentElement.style.setProperty("--cg-"+name,'url("'+url+'")');


const SCHOOL500_REFERENCE="./assets/6b5a6dce4e970f8db0b5a86e.webp";
// Dữ liệu state.lessons được thay trực tiếp bằng 500 câu nguyên văn từ tài liệu Word.
// Dùng URL nội bộ ngắn để ảnh PNG lớn không vượt giới hạn biến CSS trên Chrome.
function school500ImageSource(){if(!SCHOOL500_REFERENCE.startsWith("data:"))return SCHOOL500_REFERENCE;try{const parts=SCHOOL500_REFERENCE.split(','),bytes=Uint8Array.from(atob(parts[1]),c=>c.charCodeAt(0));return URL.createObjectURL(new Blob([bytes],{type:'image/png'}))}catch{return SCHOOL500_REFERENCE}}
const school500Cards=[[278,354,137,166],[422,354,132,166],[560,354,133,166],[698,354,132,166],[836,354,132,166],[975,354,129,166],[1109,354,130,166],[1243,354,132,166],[1380,354,131,166],[1518,354,131,166]];
function school500Sprite(x,y,w,h){return `--s500-ratio:${w}/${h};--s500-size:${1672/w*100}%;--s500-x:${x/(1672-w)*100}%;--s500-y:${y/(941-h)*100}%`}
function school500Star(active){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 2.6 2.9 5.9 6.5.95-4.7 4.58 1.1 6.47L12 17.45l-5.8 3.05 1.1-6.47L2.6 9.45l6.5-.95Z" fill="${active?'#ffd353':'none'}" stroke="${active?'#ac6b18':'#8da8b5'}" stroke-width="1.7" stroke-linejoin="round"/></svg>`}
function school500Favorite(id){if(!state.lessons.some(l=>l.groups[0].sentences.some(s=>s.id===id)))return;let saved=favorites();if(!Array.isArray(saved))saved=[];const active=!saved.includes(id);const next=active?[...saved,id]:saved.filter(x=>x!==id);try{localStorage.setItem('songngu-favorites',JSON.stringify(next));document.querySelectorAll('[data-school500-favorite="'+id+'"]').forEach(button=>{button.innerHTML=school500Star(active);button.setAttribute('aria-pressed',String(active));button.setAttribute('aria-label',(active?'Bỏ lưu':'Lưu yêu thích')+' câu '+button.dataset.number)})}catch{notify('Chưa lưu được yêu thích. Hãy cho phép trình duyệt lưu dữ liệu trên thiết bị.',false)}}
function school500Select(index){if(!Number.isInteger(index)||index<0||index>=state.lessons.length)return;stopSpeech();state.lesson=index;render();const button=document.querySelector('[data-school500-lesson="'+index+'"]');button?.focus({preventScroll:true})}
function school500Page(){
 const index=Number.isInteger(state.lesson)&&state.lesson>=0&&state.lesson<10?state.lesson:0;state.lesson=index;const lesson=state.lessons[index],rows=lesson.groups[0].sentences,saved=favorites(),favoritesSet=new Set(Array.isArray(saved)?saved:[]);
 const nav=[['home','Trang chủ'],['vocab','Từ vựng'],['games','Luyện tập'],['evaluation','Góc tiến bộ'],['ranking','Thành tích'],['settings','Cài đặt']];
 return `<div class="school500-screen"><aside class="school500-sidebar"><button class="s500-brand" aria-label="Đại Ngàn Song Ngữ · về trang chủ" onclick="goto('home')"></button><nav aria-label="Điều hướng ứng dụng">${nav.map(([page,label],i)=>`<button class="s500-nav-item s500-nav-${i}" onclick="goto('${page}')" aria-label="${label}"></button>`).join('')}</nav></aside><main class="school500-main"><header class="s500-hero" aria-label="Đại Ngàn Song Ngữ · 500 mẫu câu giao tiếp trong trường học"><h1 class="s500-sr">500 mẫu câu giao tiếp trong trường học</h1><button class="s500-login" onclick="openAuth()" aria-label="${state.user?'Hồ sơ học sinh':'Đăng nhập hoặc chọn hồ sơ'}"></button></header><section class="s500-lessons" aria-labelledby="s500-lessons-title"><h2 id="s500-lessons-title">📖 10 BÀI HỌC</h2><div class="s500-card-strip" role="tablist" aria-label="Chọn một trong 10 bài học">${state.lessons.map((l,i)=>`<button class="s500-lesson-card ${i===index?'selected':''}" style="${school500Sprite(...school500Cards[i])}" id="s500-tab-${i}" data-school500-lesson="${i}" role="tab" aria-selected="${i===index}" aria-controls="s500-content" aria-label="Bài ${l.id}: ${esc(l.title)} · 50 câu" onclick="school500Select(${i})"><span class="s500-sr">Bài ${l.id}: ${esc(l.title)}</span></button>`).join('')}</div></section><section class="s500-content-panel" id="s500-content" role="tabpanel" aria-labelledby="s500-tab-${index}"><div class="s500-heading"><span class="s500-school-art" style="${school500Sprite(295,540,125,92)}" aria-hidden="true"></span><h2>BÀI ${lesson.id}: ${esc(lesson.title)}</h2><span class="s500-count">50 câu</span></div><div class="s500-row-list">${rows.map(row=>{const favorite=favoritesSet.has(row.id);return `<article class="s500-row" id="${row.id}"><span class="s500-number" aria-label="Câu ${row.number}">${row.number}</span><p class="s500-english" lang="en">${esc(row.en)}</p><div class="s500-audio-actions"><button class="s500-speak" aria-label="Nghe câu ${row.number}" onclick="say(${esc(JSON.stringify(row.en))})"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 9h4l5-4v14l-5-4H3Z" fill="currentColor"/><path d="M15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg></button><button class="s500-practice" aria-label="Luyện nói câu ${row.number}" onclick="practiceSentence(${esc(JSON.stringify(row.en))})"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="9" y="2" width="6" height="12" rx="3" fill="currentColor"/><path d="M6 11v1a6 6 0 0 0 12 0v-1m-6 7v4m-4 0h8" fill="none" stroke="currentColor" stroke-width="2"/></svg></button></div><p class="s500-vietnamese" lang="vi">${esc(row.vi)}</p><button class="s500-favorite" data-number="${row.number}" data-school500-favorite="${row.id}" aria-label="${favorite?'Bỏ lưu':'Lưu yêu thích'} câu ${row.number}" aria-pressed="${favorite}" onclick="school500Favorite('${row.id}')">${school500Star(favorite)}</button></article>`}).join('')}</div><footer class="s500-footer"><span>10 bài · 500 câu Anh–Việt · Chạm loa để nghe, ngôi sao để lưu</span><button onclick="goto('grammar')">📚 Cấu trúc & ngữ pháp</button></footer></section></main></div>`
}
const school500LayoutBase=layout;layout=function(body){return state.page==='lessons'?body:school500LayoutBase(body)};

document.documentElement.style.setProperty("--school500-reference",'url("'+school500ImageSource()+'")');

const PG_REFERENCE="./assets/1911b60597784a916039c6f4.webp";
// Dashboard mới dùng đúng 9 trò chơi, học liệu và cơ chế ghi kết quả đã có.
const pgCards=[[282,280,346,202],[642,280,334,202],[989,280,331,202],[282,493,346,195],[642,493,334,195],[989,493,331,195],[282,700,346,199],[642,700,334,199],[989,700,331,199]];
let pgTicker=null,pgMicToken=0,pgRun=0,pgSession=null;
function pgImageSource(){if(!PG_REFERENCE.startsWith("data:"))return PG_REFERENCE;try{const data=Uint8Array.from(atob(PG_REFERENCE.split(',')[1]),c=>c.charCodeAt(0));return URL.createObjectURL(new Blob([data],{type:'image/png'}))}catch{return PG_REFERENCE}}
function pgSprite(x,y,w,h){return `--pg-ratio:${w}/${h};--pg-size:${1672/w*100}%;--pg-x:${x/(1672-w)*100}%;--pg-y:${y/(941-h)*100}%`}
function pgStop(){clearInterval(pgTicker);pgTicker=null;pgMicToken++;try{if(recognition)recognition.abort()}catch{}recognition=null;try{window.speechSynthesis?.cancel()}catch{}}
stopListening=pgStop;
function pgOpenGame(id){if(!Number.isInteger(id)||id<0||id>=games.length)return;pgStop();closeRobot();pgSession={id,run:++pgRun,startStars:total(),correct:0};state.game=id;state.question=0;goto('quiz')}
openExistingGame=pgOpenGame;
function pgSide(){return `<aside class="pg-sidebar"><button class="pg-brand" onclick="goto('home')" aria-label="Đại Ngàn Song Ngữ · Trang chủ"></button><nav aria-label="Điều hướng chính">${[['home','Trang chủ'],['vocab','Từ vựng'],['games','Luyện tập'],['evaluation','Góc tiến bộ'],['ranking','Thành tích'],['settings','Cài đặt']].map(([p,n],i)=>`<button class="pg-nav pg-nav-${i}" onclick="goto('${p}')" aria-label="${n}"></button>`).join('')}</nav></aside>`}
function pgShell(content){return `<div class="pg-screen">${pgSide()}<main class="pg-main"><header class="pg-banner"><h1 class="pg-sr">Đại Ngàn Song Ngữ · Luyện tập · Học vui mỗi ngày</h1></header>${content}</main></div>`}
gamesPage=function(){return pgShell(`<div class="pg-dashboard"><section class="pg-shortcuts pg-six-shortcuts" aria-label="Chọn một trong 6 trò chơi">${games.map((g,i)=>({g,i})).filter(({i})=>![5,6,8].includes(i)).map(({g,i},n)=>`<button type="button" class="pg-card" style="${pgSprite(...pgCards[i])}" onclick="pgOpenGame(${i})" aria-label="Bắt đầu ${esc(g[0])}" data-pg-game="${i}"><span class="pg-renumber" aria-hidden="true">${n+1}</span><span class="pg-sr">${n+1}. ${esc(g[0])} · ${g[1]} · Bắt đầu</span></button>`).join('')}</section><aside class="pg-journey"><section class="pg-score-panel"><h2>⭐ Hành trình học tập</h2><strong class="pg-total">${total()}<small>sao</small></strong><p>Mỗi câu đúng +2 sao</p></section><section class="pg-skills" aria-label="Sao theo kỹ năng">${['Nghe','Nói','Đọc','Viết'].map((skill,i)=>`<p><span>${['🎧','🎤','📖','✏️'][i]}</span>${skill}: <b>${state.progress.skills.find(x=>x.skill===skill)?.stars||0}</b></p>`).join('')}</section><button class="pg-mascot" style="${pgSprite(1340,687,330,244)}" onclick="robot('Mình giúp em nhé!','<p>Chạm vào một thẻ để mở trò chơi. Nghe mẫu, thử trả lời, rồi đọc hướng dẫn của mình nếu gặp câu khó.</p>',false)" aria-label="Rô-bốt hướng dẫn cách luyện tập"></button>${state.user?`<p class="pg-profile">Hồ sơ: ${esc(state.user.name)}</p>`:`<button class="pg-profile-button" onclick="openAuth()">Chọn hồ sơ để lưu sao</button>`}</aside></div>`)};
const pgOldChoiceMarkup=choiceMarkup;
choiceMarkup=function(q){if(state.game!==0&&state.game!==8)return pgOldChoiceMarkup(q);return `<div class="pg-picture-options">${q.options.map(x=>{const image=ASSET_URLS[x.image]||x.image||emojiImage(x.icon||'📚');return `<button class="quiz-option" onclick="answer(${esc(JSON.stringify(x.id))})">${image?`<img src="${esc(image)}" alt="" draggable="false">`:''}<span>${esc(x.vi)}</span></button>`}).join('')}</div>`};
const pgOldGameView=gameView;
gameView=function(){const old=pgOldGameView(),start=old.indexOf('<section class="panel quiz">');let activity=old.slice(start).replace(/<div class="row space">[\s\S]*?<\/div>/,'');const g=games[state.game],segment=Math.floor(state.question/10)+1,n=state.question%10;
 activity=resolveAssetMarkup(decorateImages(activity));
 return pgShell(`<section class="pg-play game-mode-${state.game}"><div class="pg-play-head"><button class="pg-back" onclick="goto('games')">← Menu Luyện tập</button><span class="pg-play-name">${g[2]} ${esc(g[0])}</span><span class="pg-play-stars" id="pg-stars">⭐ ${total()} sao</span></div><div class="pg-progress-row"><label for="pg-progress">Chặng ${segment} · Câu ${n+1}/10</label><span id="pg-session-score">Lượt này: +${pgSession?.id===state.game?Math.max(0,total()-pgSession.startStars):0} sao</span>${state.game===8?'<strong class="pg-clock" id="pg-clock" role="timer">15 giây</strong>':''}</div><progress id="pg-progress" value="${n}" max="10">${n}/10</progress>${state.user?'':`<div class="pg-profile-notice">Chọn hồ sơ học sinh để chấm đáp án và lưu sao. <button onclick="openAuth()">Chọn hồ sơ</button></div>`}<div class="pg-game-stage" id="pg-game-stage" data-feedback="idle">${activity}<div class="pg-celebrate" aria-hidden="true">⭐ ✨ ⭐</div></div><p class="pg-live" id="pg-live" role="status" aria-live="polite">Em có thể nghe mẫu rồi thử trả lời. Rô-bốt sẽ giúp em khi gặp câu khó.</p><footer class="pg-play-footer"><button onclick="goto('games')">🎮 Đổi trò chơi</button><button onclick="say(${esc(JSON.stringify(state.game===6?state.lessons[state.question%state.lessons.length].groups[0].sentences[0].en:activeQuestion().correct.en))})">🔊 Nghe mẫu</button><span>Nghe · Nói · Đọc · Viết</span></footer></section>`)
};
function pgUpdateHud(good){const stage=document.getElementById('pg-game-stage');if(stage)stage.dataset.feedback=good?'correct':'retry';const score=document.getElementById('pg-stars');if(score)score.textContent='⭐ '+total()+' sao';const gain=document.getElementById('pg-session-score');if(gain)gain.textContent='Lượt này: +'+Math.max(0,total()-(pgSession?.startStars||0))+' sao';const progress=document.getElementById('pg-progress');if(progress&&good)progress.value=state.question%10+1;const live=document.getElementById('pg-live');if(live)live.textContent=good?'Em làm được rồi! +2 sao. Chọn “Câu tiếp theo” để tiếp tục.':'Cảm ơn em đã thử! Nghe hướng dẫn của rô-bốt rồi thử lại. Không trừ sao.'}
function pgChime(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;const ac=new Audio();[660,880].forEach((tone,i)=>{const o=ac.createOscillator(),g=ac.createGain(),time=ac.currentTime+i*.14;o.connect(g);g.connect(ac.destination);o.frequency.value=tone;g.gain.setValueAtTime(.025,time);g.gain.exponentialRampToValueAtTime(.001,time+.25);o.start(time);o.stop(time+.26)});setTimeout(()=>ac.close().catch(()=>{}),700)}catch{}}
// Lớp hiển thị gọi nguyên hàm chấm điểm cũ, không tự ghi hay cộng sao lần thứ hai.
const pgOldCompleteAnswer=completeAnswer;
completeAnswer=async function(good,q,chosen){if(!state.user){openAuth();return}const run=pgSession?.run,game=state.game,question=state.question,person=state.user.username,before=offlineStore().attempts.length;await pgOldCompleteAnswer(good,q,chosen);if(state.page!=='quiz'||state.game!==game||state.question!==question||state.user?.username!==person||pgSession?.run!==run){closeRobot();return}const recorded=offlineStore().attempts.length>before;if(recorded){pgUpdateHud(good);if(good){clearInterval(pgTicker);pgTicker=null;if(pgSession)pgSession.correct++;pgChime()}const overlay=document.getElementById('robot-overlay');if(overlay)overlay.dataset.gameFeedback=good?'correct':'retry'}};
const pgOldNextQuestion=nextQuestion;
nextQuestion=function(){pgStop();pgOldNextQuestion()};
// Giữ cách so khớp câu cũ, bảo vệ micro và bỏ qua callback của câu đã rời đi.
startSpeaking=function(phrase){const status=document.getElementById('speech-status');if(!status)return;if(!state.user){openAuth();return}pgStop();const token=pgMicToken,game=state.game,question=state.question,person=state.user.username;
 try{const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(typeof Speech!=='function'){status.textContent='Thiết bị chưa hỗ trợ nhận dạng. Em vẫn nghe và đọc theo mẫu được; phần nói không tự cộng sao.';say(phrase);return}recognition=new Speech();recognition.lang='en-US';recognition.interimResults=false;const active=()=>token===pgMicToken&&state.page==='quiz'&&state.game===game&&state.question===question&&state.user?.username===person;status.textContent='🎤 Đang lắng nghe… Em hãy đọc câu trên.';recognition.onresult=e=>{if(!active())return;try{const said=e.results?.[0]?.[0]?.transcript;if(!said)return;status.textContent='Máy nghe được: '+said;pgStop();completeAnswer(normalize(said)===normalize(phrase),{correct:{en:phrase,vi:'Nghe mẫu và đọc lại rõ từng từ.'}},said)}catch{status.textContent='Chưa đọc được kết quả. Em bấm nghe mẫu rồi thử lại nhé.'}};recognition.onerror=e=>{if(!active())return;pgStop();status.textContent='Chưa nghe được: '+e.error+'. Em vẫn nghe mẫu và quay lại menu được.'};recognition.start()
 }catch{pgStop();status.textContent='Không mở được micro. Em vẫn nghe mẫu, đọc theo hoặc chọn trò khác được.'}
};
function pgStartTicker(){clearInterval(pgTicker);pgTicker=null;if(state.page!=='quiz'||state.game!==8)return;const update=()=>{const clock=document.getElementById('pg-clock');if(!clock)return;const left=Math.max(0,Math.ceil((15000-(Date.now()-gameStarted))/1000));clock.textContent=left?left+' giây':'Hết giờ · thử lại';clock.classList.toggle('urgent',left<=5);if(!left){clearInterval(pgTicker);pgTicker=null}};update();pgTicker=setInterval(update,250)}
const pgOldLayout=layout;layout=function(body){return ['games','quiz'].includes(state.page)?body:pgOldLayout(body)};
const pgOldRender=render;render=function(){clearInterval(pgTicker);pgTicker=null;if(state.page==='quiz'&&!state.user)document.querySelector('#app').innerHTML=gameView();else pgOldRender();pgStartTicker()};
const pgOldGoto=goto;goto=function(page){if(state.page==='quiz'||page==='games')pgStop();if(page==='quiz'&&(!pgSession||pgSession.id!==state.game))pgSession={id:state.game,run:++pgRun,startStars:total(),correct:0};pgOldGoto(page)};
const pgOldLogout=logout;logout=async function(){pgStop();pgSession=null;await pgOldLogout()};
window.addEventListener('pagehide',pgStop);

document.documentElement.style.setProperty("--pg-reference",'url("'+pgImageSource()+'")');

