// Kho ảnh mới chỉ mở rộng Chăm sóc Rô-bốt, giữ các khóa và cơ chế thưởng cũ.
for(const item of care3Data.items)cgItems.push(item);
const care3={identity:'',visible:[],pool:[],bags:{},round:0,emotion:'',previousOrder:''};
const care3Tabs=[['warmup','Khởi động','Warm-up',[410,183,83,72]],['meals','Bữa ăn','Meals & Drinks',[724,183,111,75]],['dress','Trang phục','Dressing up',[1051,185,80,68]],['school','Chuẩn bị tới trường','Back to School',[1394,177,70,80]]];
function care3Shuffle(rows){const a=rows.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function care3Take(group,count){const source=care3Data.items.filter(x=>group==='dress'||group==='school'?x.tab===group:x.sheet===group);let bag=care3.bags[group]||[];const taken=[];while(taken.length<count){if(!bag.length)bag=care3Shuffle(source);const item=bag.pop();if(!taken.some(x=>x.id===item.id)&&!taken.some(x=>x.concept===item.concept))taken.push(item)}care3.bags[group]=bag;return taken}
function care3Batch(tab){let visible=[],pool=[];if(tab==='warmup'){visible=care3Shuffle(care3Data.feelings);pool=visible.slice()}else if(tab==='meals'){const categories=['food','drinks','fruits'];categories.forEach((group,i)=>{const count=(care3.round%3===i?4:3),picked=care3Take(group,count);visible.push(...picked);const rest=care3Shuffle(care3Data.items.filter(x=>x.sheet===group&&!picked.some(p=>p.id===x.id)));pool.push(...picked,...rest.slice(0,10-count))});visible=care3Shuffle(visible)}else{visible=care3Shuffle(care3Take(tab,10));pool=care3Data.items.filter(x=>x.tab===tab)}
 if(visible.map(x=>x.id).join('|')===care3.previousOrder)visible.push(visible.shift());care3.previousOrder=visible.map(x=>x.id).join('|');care3.visible=visible;care3.pool=pool;care3.round++;return visible}
function care3EmotionRead(){try{const all=JSON.parse(localStorage.getItem('daingan-care-emotions-v3')||'{}');const value=all[cgIdentity()];return care3Data.feelings.some(x=>x.en===value)?value:''}catch{return ''}}
function care3Ensure(){const key=cgIdentity();if(care3.identity===key)return;cgStop();care3.identity=key;care3.bags={};care3.round=0;care3.emotion=care3EmotionRead();cg.person=key;cg.tab='warmup';cg.target=null;cg.selected='';cg.solved=false;cg.consent=false;cg.message='Hôm nay em cảm thấy thế nào? Nghe rồi chọn một hình nhé.';cg.audioNote='';care3Batch('warmup')}
function care3Command(item){if(item.tab==='meals'){if(item.sheet==='drinks')return care3Shuffle(['Can you give me '+item.en+'?','I am thirsty! I want some '+item.en+', please!'])[0];if(item.sheet==='fruits')return care3Shuffle(['Where '+(item.plural?'are the ':'is the ')+item.en+'?','I like fruit. Give me some '+item.en+', please!'])[0];return care3Shuffle(['I am hungry! I want some '+item.en+', please!','Can you give me some '+item.en+'?'])[0]}if(item.tab==='dress')return care3Shuffle(['Please give me my '+item.en+'!','Help me find my '+item.en+'!'])[0];return care3Shuffle(['Time for school! Where '+(item.plural?'are my ':'is my ')+item.en+'?','Can you find my '+item.en+'?'])[0]}
function care3Next(){care3Ensure();cgStop();const old=cg.target?.id;care3Batch(cg.tab);cg.selected='';cg.solved=false;cg.audioNote='';cg.pose='idle';if(cg.tab==='warmup'){cg.command='How are you today?';cg.target=null;cg.message='Nghe câu hỏi rồi chọn cảm xúc của em.'}else{const candidates=care3.visible.filter(x=>x.id!==old);cg.target=candidates[Math.floor(Math.random()*candidates.length)];cg.command=care3Command(cg.target);cg.message='Nghe yêu cầu rồi chạm vào một hình nhé.'}render();cgSpeak(cg.command)}
function care3Select(tab){if(!care3Tabs.some(x=>x[0]===tab))return;care3Ensure();cg.tab=tab;care3Next()}
function care3Choose(id){if(!care3.visible.some(x=>x.id===id))return;if(cg.tab==='warmup'){care3Feeling(care3.visible.find(x=>x.id===id).en);return}const selected=care3.visible.find(x=>x.id===id);if(selected.concept===cg.target?.concept)cgChoose(cg.target.id);else cgChoose(id)}
function care3Feeling(feeling){if(!care3Data.feelings.some(x=>x.en===feeling))return;cgStop();care3.emotion=feeling;cgSave(p=>{p.battery=100;if(['happy','tired','excited'].includes(feeling))p.feeling=feeling});try{let all=JSON.parse(localStorage.getItem('daingan-care-emotions-v3')||'{}');if(!all||typeof all!=='object'||Array.isArray(all))all={};all[cgIdentity()]=feeling;localStorage.setItem('daingan-care-emotions-v3',JSON.stringify(all))}catch{}cg.pose='happy';cg.selected='feeling-'+feeling;cg.message='Cảm ơn em đã chia sẻ! Pin đã đầy. Mình cùng học nhé.';render();cgBell();cgSpeak('Thank you for sharing!',.85,null,'happy')}
function care3Micro(){if(cg.recognition){cgStopMic();cgSetMessage('Đã dừng micro. Em vẫn chọn một hình cảm xúc được.');return}if(!cg.consent){cgSetMessage('Người lớn đồng ý trước khi bật micro. Em có thể chạm vào hình để trả lời.');document.getElementById('cg-consent')?.focus();return}cgCancelVoice();cgStopMic();const ticket=cg.listenToken,key=cgIdentity();let received=false;try{const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(typeof Recognition!=='function'){cgSetMessage('Máy chưa hỗ trợ nhận dạng. Em chạm một hình cảm xúc để sạc pin nhé.');return}const rec=new Recognition();cg.recognition=rec;rec.lang='en-US';rec.continuous=false;rec.interimResults=false;const active=()=>ticket===cg.listenToken&&key===cgIdentity()&&state.page==='care'&&cg.tab==='warmup';document.getElementById('cg-mic')?.setAttribute('aria-pressed','true');cgSetMessage('Đang mở micro…');rec.onstart=()=>{if(active())cgSetMessage('Đang lắng nghe em nói...')};rec.onresult=e=>{if(!active()||received)return;try{const text=e.results?.[0]?.[0]?.transcript||'',answer=dnNormalize(text);if(!answer)return;received=true;cgStopMic();const feeling=care3Data.feelings.find(f=>answer==='i am '+f.en||answer===f.en);if(feeling)care3Feeling(feeling.en);else if(['hello','hello robot','good morning','good morning robot'].includes(answer)){cgSave(p=>{p.battery=100});cg.pose='happy';cg.message='Rô-bốt đã nghe lời chào của em. Pin đã đầy!';render();cgSpeak('Good morning, friend!',.85,null,'happy')}else{cgSetMessage('Mình cùng nghe rồi thử lại, hoặc chọn hình cảm xúc nhé.');cgSpeak('How are you today?',.6)}}catch{cgStopMic();cgSetMessage('Chưa nghe rõ. Em chọn hình cảm xúc nhé.')}};rec.onerror=e=>{if(!active()||received)return;cgStopMic();cgSetMessage((e.error==='not-allowed'?'Micro bị chặn quyền. ':'Chưa nhận được lời nói. ')+'Em vẫn chọn hình và nghe mẫu được.')};rec.onend=()=>{if(active()&&!received){cgStopMic();cgSetMessage('Em chọn một hình cảm xúc hoặc bấm micro thử lại nhé.')}};cg.micTimer=setTimeout(()=>{if(active()){cgStopMic();cgSetMessage('Micro đã dừng. Em vẫn chạm vào hình để trả lời được.')}},15000);rec.start()}catch{cgStopMic();cgSetMessage('Không mở được micro. Em chạm vào một hình cảm xúc để sạc pin nhé.')}}
function care3Sprite(sheet,crop,size){const [x,y,w,h]=crop,[sw,sh]=size;return `--c3-sheet:var(--care3-${sheet});--c3-ratio:${w}/${h};--c3-size:${sw/w*100}%;--c3-x:${x/(sw-w)*100}%;--c3-y:${y/(sh-h)*100}%`}
function care3Picture(item){if(item.sheet==='emotions'){
  const index=care3Data.feelings.findIndex(f=>f.id===item.id);
  const xs=[10,318,623,930,1233], widths=[297,295,295,293,295];
  const crop=[xs[index%5],index<5?135:550,widths[index%5],index<5?400:422];
  const vi={great:'Tôi rất tuyệt!',happy:'Tôi vui vẻ!',good:'Tôi ổn!',fine:'Tôi khỏe!',excited:'Tôi hào hứng!',tired:'Tôi mệt!',sad:'Tôi buồn!',angry:'Tôi tức giận!',nervous:'Tôi lo lắng!',sick:'Tôi không khỏe!'};
  return `<span class="c3-picture c3-emotion-full" style="${care3Sprite('emotions',crop,item.sourceSize)}" aria-hidden="true"></span><span class="c3-sr"><span lang="en">I'm ${esc(item.en)}!</span> / <span lang="vi">${esc(vi[item.en])}</span></span>`;
}return `<span class="c3-picture ${item.sheet==='clothes'?'c3-number-mask':''}" style="${care3Sprite(item.sheet,item.crop,item.sourceSize)}" aria-hidden="true"></span>`}
function care3Cards(){return care3.visible.map((item,i)=>`<button type="button" class="c3-card c3-color-${i%5} ${cg.selected===item.id?(cg.tab==='warmup'||cg.solved?'c3-correct':'c3-retry'):''}" data-care3-card="${item.id}" aria-label="${cg.tab==='warmup'?'Em cảm thấy ':'Chọn '}${esc(item.vi)}" onclick="care3Choose('${item.id}')">${care3Picture(item)}</button>`).join('')}
carePage=function(){care3Ensure();const p=cgProgress(),warm=cg.tab==='warmup',tab=care3Tabs.find(x=>x[0]===cg.tab),command=warm?'How are you today?':cg.command;return `<div class="care3-screen"><aside class="c3-sidebar"><button class="c3-brand" onclick="goto('home')" aria-label="Đại Ngàn Song Ngữ · về Trang chủ"></button><nav aria-label="Điều hướng ứng dụng">${[['home','Trang chủ'],['vocab','Từ vựng'],['games','Luyện tập'],['evaluation','Góc tiến bộ'],['ranking','Thành tích'],['settings','Cài đặt']].map(([page,label],i)=>`<button class="c3-nav c3-nav-${i}" onclick="goto('${page}')" aria-label="${label}"></button>`).join('')}</nav></aside><main class="c3-main"><header class="c3-hero"><h1 class="c3-sr">Chăm sóc Rô-bốt · Đại Ngàn Song Ngữ</h1></header><nav class="c3-tabs" role="tablist" aria-label="Bốn hoạt động chăm sóc">${care3Tabs.map(([id,title,en,crop])=>`<button role="tab" id="care3-tab-${id}" aria-selected="${id===cg.tab}" aria-controls="care3-panel" onclick="care3Select('${id}')"><span class="c3-tab-art" style="${care3Sprite('ui',crop,[1672,941])}" aria-hidden="true"></span><b>${title}</b><small>${en}</small></button>`).join('')}</nav><div class="c3-room"><aside class="c3-robot-panel"><div class="c3-battery"><span aria-hidden="true">🔋</span><b>Pin ${p.battery}%</b><progress value="${p.battery}" max="100">${p.battery}%</progress></div><div class="c3-robot-scene" id="cg-stage" data-pose="${cg.pose}"><span class="c3-robot-image" style="${care3Sprite('ui',[336,400,449,311],[1672,941])}" role="img" aria-label="Bạn Rô-bốt Dẻ Triêng ngồi tại bàn"></span>${cg.pose==='happy'?'<span class="c3-stars" aria-hidden="true">⭐ ✨ ⭐</span>':''}</div><div class="c3-robot-talk"><h3>${warm?'Hôm nay em thế nào?':'Nghe xem mình cần gì nhé!'}</h3><button class="c3-primary" onclick="cgSpeak(${esc(JSON.stringify(command))})">🔊 Nghe rô-bốt</button><details><summary>Lời gợi ý cho người lớn</summary><p lang="en">${esc(command)}</p><p>${warm?'Nghe và chọn cảm xúc của em.':cg.target?'Rô-bốt cần: '+esc(cg.target.vi):''}</p></details><p id="cg-audio-note" class="c3-audio-note">${esc(cg.audioNote)}</p></div><p class="c3-small">Mỗi món đúng được +2 sao một lần mỗi ngày.<br>Chọn chưa đúng không bị trừ sao.</p><span class="c3-score">⭐ ${p.awarded.length*2} sao hôm nay</span></aside><section class="c3-work" id="care3-panel" role="tabpanel" aria-labelledby="care3-tab-${cg.tab}"><h2>${tab[1]}</h2><p class="c3-intro">${warm?'How are you today? · Nghe rồi chọn một hình cảm xúc.':'Chạm đúng hình theo lời rô-bốt. Không cần đọc chữ dưới tranh.'}</p><div class="c3-cards" aria-label="10 hình để chọn">${care3Cards()}</div><div class="c3-actions"><button class="c3-primary" onclick="cgSpeak(${esc(JSON.stringify(command))})">🔊 Nghe yêu cầu</button><button onclick="cgSpeak(${esc(JSON.stringify(command))},.6)">🐢 Nghe chậm 0.6x</button><button onclick="care3Next()">↻ Đổi yêu cầu</button>${warm?'<button id="cg-mic" class="c3-micro" aria-label="Bật hoặc dừng micro" aria-pressed="false" onclick="care3Micro()">🎤 Nói lời chào</button>':''}</div>${warm?`<label class="c3-consent"><input id="cg-consent" type="checkbox" ${cg.consent?'checked':''} onchange="cg.consent=this.checked;if(!this.checked)cgStopMic()">Người lớn đồng ý bật micro. Trình duyệt có thể gửi giọng nói qua mạng; ứng dụng không lưu bản ghi âm. Có thể chọn hình thay thế.</label>`:''}<p id="cg-feedback" class="c3-feedback" role="status" aria-live="polite">${esc(cg.message)}</p><p class="c3-profile">${state.user?'Hồ sơ: '+esc(state.user.name):'Phiên khách · Chọn hồ sơ ở Trang chủ để lưu sao vào bảng vinh danh.'}</p></section></div></main></div>`};
const care3LayoutBase=layout;layout=function(body){return state.page==='care'?body:care3LayoutBase(body)};
function care3ImageUrl(uri){if(!uri.startsWith("data:"))return uri;try{const p=uri.split(','),bytes=Uint8Array.from(atob(p[1]),x=>x.charCodeAt(0));return URL.createObjectURL(new Blob([bytes],{type:p[0].slice(5).split(';')[0]}))}catch{return uri}}
for(const [name,image] of Object.entries(CARE3_SHEETS))document.documentElement.style.setProperty('--care3-'+name,'url("'+care3ImageUrl(image)+'")');


// Ngân hàng luyện nói: nguyên văn tài liệu Word đính kèm.
const SP500_TOPICS=[{"number":1,"title":"ĐẦU GIỜ VÀ ỔN ĐỊNH LỚP HỌC","titleEn":"STARTING CLASS","sentences":[{"id":"school500-01-001","number":1,"speaker":"Cô giáo","en":"Good morning, class!","vi":"Cô chào cả lớp!","ipa":"/ɡʊd ˈmɔrnɪŋ klæs/"},{"id":"school500-01-002","number":2,"speaker":"Học sinh","en":"Good morning, teacher!","vi":"Chúng em chào cô ạ!","ipa":"/ɡʊd ˈmɔrnɪŋ ˈtitʃər/"},{"id":"school500-01-003","number":3,"speaker":"Cô giáo","en":"How are you today?","vi":"Hôm nay các con thế nào?","ipa":"/haʊ ər ju təˈdeɪ/"},{"id":"school500-01-004","number":4,"speaker":"Học sinh","en":"I am happy, thank you!","vi":"Chúng em rất vui, cảm ơn cô ạ!","ipa":"/aɪ æm ˈhæpi θæŋk ju/"},{"id":"school500-01-005","number":5,"speaker":"Học sinh","en":"I am fine, thank you!","vi":"Em khỏe, cảm ơn cô ạ!","ipa":"/aɪ æm faɪn θæŋk ju/"},{"id":"school500-01-006","number":6,"speaker":"Cô giáo","en":"Stand up, please!","vi":"Cô mời cả lớp đứng lên nào!","ipa":"/stænd əp pliz/"},{"id":"school500-01-007","number":7,"speaker":"Cô giáo","en":"Sit down, please!","vi":"Cô mời cả lớp ngồi xuống nào!","ipa":"/sɪt daʊn pliz/"},{"id":"school500-01-008","number":8,"speaker":"Cô giáo","en":"Be quiet, please!","vi":"Cả lớp giữ trật tự nhé!","ipa":"/bi kwaɪət pliz/"},{"id":"school500-01-009","number":9,"speaker":"Học sinh","en":"Yes, teacher!","vi":"Vâng ạ!","ipa":"/jɛs ˈtitʃər/"},{"id":"school500-01-010","number":10,"speaker":"Cô giáo","en":"Look at me, please!","vi":"Các con hãy nhìn về phía cô nhé!","ipa":"/lʊk æt mi pliz/"},{"id":"school500-01-011","number":11,"speaker":"Cô giáo","en":"Are you ready?","vi":"Các con đã sẵn sàng chưa?","ipa":"/ər ju ˈrɛdi/"},{"id":"school500-01-012","number":12,"speaker":"Học sinh","en":"Yes, we are ready!","vi":"Chúng em sẵn sàng rồi ạ!","ipa":"/jɛs wi ər ˈrɛdi/"},{"id":"school500-01-013","number":13,"speaker":"Cô giáo","en":"Put your hands on the table.","vi":"Các con đặt tay ngay ngắn lên bàn nào.","ipa":"/pʊt jʊr hænz ɔn ðə ˈteɪbəl/"},{"id":"school500-01-014","number":14,"speaker":"Cô giáo","en":"Sit nicely, everyone.","vi":"Các con ngồi thật đẹp nào.","ipa":"/sɪt ˈnaɪsli ˈɛvriˌwən/"},{"id":"school500-01-015","number":15,"speaker":"Cô giáo","en":"Who is absent today?","vi":"Hôm nay lớp mình có bạn nào vắng mặt không?","ipa":"/hu ɪz ˈæbsənt təˈdeɪ/"},{"id":"school500-01-016","number":16,"speaker":"Học sinh","en":"No one is absent today.","vi":"Thưa cô, hôm nay lớp đủ ạ.","ipa":"/noʊ wən ɪz ˈæbsənt təˈdeɪ/"},{"id":"school500-01-017","number":17,"speaker":"Cô giáo","en":"Welcome to our Math class today!","vi":"Chào mừng các con đến với tiết Toán hôm nay!","ipa":"/ˈwɛlkəm tɪ ɑr mæθ klæs təˈdeɪ/"},{"id":"school500-01-018","number":18,"speaker":"Cô giáo","en":"Say hello to our Robot friend!","vi":"Các con hãy chào bạn Rô-bốt nào!","ipa":"/seɪ hɛˈloʊ tɪ ɑr ˈroʊˌbət frɛnd/"},{"id":"school500-01-019","number":19,"speaker":"Học sinh","en":"Hello, Robot!","vi":"Chào bạn Rô-bốt!","ipa":"/hɛˈloʊ ˈroʊˌbət/"},{"id":"school500-01-020","number":20,"speaker":"Cô giáo","en":"Let's start our lesson now!","vi":"Bây giờ chúng ta cùng bắt đầu bài học nhé!","ipa":"/lɛts stɑrt ɑr ˈlɛsən naʊ/"},{"id":"school500-01-021","number":21,"speaker":"Cô giáo","en":"Good morning, boys and girls!","vi":"Cô chào tất cả các bạn nam và bạn nữ!","ipa":"/ɡʊd ˈmɔrnɪŋ bɔɪz ənd ɡərlz/"},{"id":"school500-01-022","number":22,"speaker":"Học sinh","en":"Good morning, dear teacher!","vi":"Chúng em kính chào cô giáo kính yêu ạ!","ipa":"/ɡʊd ˈmɔrnɪŋ dɪr ˈtitʃər/"},{"id":"school500-01-023","number":23,"speaker":"Cô giáo","en":"Did you have breakfast this morning?","vi":"Sáng nay các con đã ăn sáng chưa?","ipa":"/dɪd ju hæv ˈbrɛkfəst ðɪs ˈmɔrnɪŋ/"},{"id":"school500-01-024","number":24,"speaker":"Học sinh","en":"Yes, we did, teacher!","vi":"Dạ rồi ạ, chúng em ăn rồi thưa cô!","ipa":"/jɛs wi dɪd ˈtitʃər/"},{"id":"school500-01-025","number":25,"speaker":"Cô giáo","en":"How is the weather today?","vi":"Hôm nay thời tiết thế nào các con nhỉ?","ipa":"/haʊ ɪz ðə ˈwɛðər təˈdeɪ/"},{"id":"school500-01-026","number":26,"speaker":"Học sinh","en":"It is sunny and warm today.","vi":"Hôm nay trời nắng và ấm áp ạ.","ipa":"/ɪt ɪz ˈsəni ənd wɔrm təˈdeɪ/"},{"id":"school500-01-027","number":27,"speaker":"Học sinh","en":"It is a bit cold today.","vi":"Hôm nay trời hơi se lạnh ạ.","ipa":"/ɪt ɪz ə bɪt koʊld təˈdeɪ/"},{"id":"school500-01-028","number":28,"speaker":"Cô giáo","en":"Keep yourself warm, children.","vi":"Các con nhớ mặc ấm giữ gìn sức khỏe nhé.","ipa":"/kip ˈjɔrsɛlf wɔrm ˈtʃɪldrən/"},{"id":"school500-01-029","number":29,"speaker":"Cô giáo","en":"Take a deep breath and smile.","vi":"Cả lớp cùng hít thở sâu và cười thật tươi nào.","ipa":"/teɪk ə dip brɛθ ənd smaɪl/"},{"id":"school500-01-030","number":30,"speaker":"Học sinh","en":"We are feeling energetic today!","vi":"Hôm nay chúng em tràn đầy năng lượng ạ!","ipa":"/wi ər ˈfilɪŋ ˌɛnərˈdʒɛtɪk təˈdeɪ/"},{"id":"school500-01-031","number":31,"speaker":"Cô giáo","en":"Class monitor, report the attendance, please.","vi":"Bạn lớp trưởng hãy báo cáo sĩ số giúp cô nào.","ipa":"/klæs ˈmɑnətər rɪˈpɔrt ðə əˈtɛndəns pliz/"},{"id":"school500-01-032","number":32,"speaker":"Lớp trưởng","en":"Teacher, everyone is present today.","vi":"Thưa cô, hôm nay lớp mình đi học đầy đủ ạ.","ipa":"/ˈtitʃər ˈɛvriˌwən ɪz ˈprɛzənt təˈdeɪ/"},{"id":"school500-01-033","number":33,"speaker":"Cô giáo","en":"Very good! Thank you, class monitor.","vi":"Rất tốt! Cô cảm ơn bạn lớp trưởng nhé.","ipa":"/ˈvɛri ɡʊd θæŋk ju klæs ˈmɑnətər/"},{"id":"school500-01-034","number":34,"speaker":"Cô giáo","en":"Who is late today?","vi":"Hôm nay có bạn nào đi học muộn không?","ipa":"/hu ɪz leɪt təˈdeɪ/"},{"id":"school500-01-035","number":35,"speaker":"Học sinh","en":"No one is late today, teacher.","vi":"Thưa cô, không có ai đi muộn ạ.","ipa":"/noʊ wən ɪz leɪt təˈdeɪ ˈtitʃər/"},{"id":"school500-01-036","number":36,"speaker":"Cô giáo","en":"Give yourselves a big clap!","vi":"Cả lớp hãy tự thưởng cho mình một tràng pháo tay nào!","ipa":"/ɡɪv ˈjɔrsɛlvz ə bɪɡ klæp/"},{"id":"school500-01-037","number":37,"speaker":"Cô giáo","en":"Stop talking and look to the front.","vi":"Các con dừng nói chuyện và nhìn lên phía trước nhé.","ipa":"/stɑp ˈtɔkɪŋ ənd lʊk tɪ ðə frənt/"},{"id":"school500-01-038","number":38,"speaker":"Cô giáo","en":"Eyes on the board, please.","vi":"Mắt các con hướng lên bảng nào.","ipa":"/aɪz ɔn ðə bɔrd pliz/"},{"id":"school500-01-039","number":39,"speaker":"Cô giáo","en":"Put away your toys, children.","vi":"Các con cất hết đồ chơi vào cặp nhé.","ipa":"/pʊt əˈweɪ jʊr tɔɪz ˈtʃɪldrən/"},{"id":"school500-01-040","number":40,"speaker":"Học sinh","en":"Yes, we put them away.","vi":"Vâng ạ, chúng em đã cất gọn rồi ạ.","ipa":"/jɛs wi pʊt ðɛm əˈweɪ/"},{"id":"school500-01-041","number":41,"speaker":"Cô giáo","en":"Show me your warm smiles!","vi":"Cho cô xem nụ cười rạng rỡ của các con nào!","ipa":"/ʃoʊ mi jʊr wɔrm smaɪlz/"},{"id":"school500-01-042","number":42,"speaker":"Học sinh","en":"Here is our happy smile!","vi":"Nụ cười vui vẻ của chúng em đây ạ!","ipa":"/hir ɪz ɑr ˈhæpi smaɪl/"},{"id":"school500-01-043","number":43,"speaker":"Cô giáo","en":"Who loves learning English and Math?","vi":"Bạn nào yêu thích học Tiếng Anh và môn Toán nào?","ipa":"/hu ləvz ˈlərnɪŋ ˈɪŋlɪʃ ənd mæθ/"},{"id":"school500-01-044","number":44,"speaker":"Cả lớp","en":"We all love them, teacher!","vi":"Tất cả chúng em đều yêu thích thưa cô!","ipa":"/wi ɔl ləv ðɛm ˈtitʃər/"},{"id":"school500-01-045","number":45,"speaker":"Cô giáo","en":"Let's sing a warm-up song together.","vi":"Chúng mình cùng hát một bài hát khởi động nhé.","ipa":"/lɛts sɪŋ ə wɔrm əp sɔŋ təˈɡɛðər/"},{"id":"school500-01-046","number":46,"speaker":"Học sinh","en":"Yay! Let's sing and clap hands!","vi":"Hoan hô! Cùng hát và vỗ tay theo nhịp nào!","ipa":"/jeɪ lɛts sɪŋ ənd klæp hænz/"},{"id":"school500-01-047","number":47,"speaker":"Cô giáo","en":"Stand in line and do morning exercise.","vi":"Các con đứng thẳng hàng tập vài động tác thể dục nào.","ipa":"/stænd ɪn laɪn ənd du ˈmɔrnɪŋ ˈɛksərˌsaɪz/"},{"id":"school500-01-048","number":48,"speaker":"Học sinh","en":"One, two, three, stretch your arms!","vi":"Một, hai, ba, cùng vươn cao đôi tay nào!","ipa":"/wən tu θri strɛtʃ jʊr ɑrmz/"},{"id":"school500-01-049","number":49,"speaker":"Cô giáo","en":"Now take your seat quietly.","vi":"Bây giờ các con hãy nhẹ nhàng về chỗ ngồi nhé.","ipa":"/naʊ teɪk jʊr sit kˈwaɪətli/"},{"id":"school500-01-050","number":50,"speaker":"Cả lớp","en":"We are ready for an exciting day!","vi":"Chúng em đã sẵn sàng cho một ngày học thật hào hứng!","ipa":"/wi ər ˈrɛdi fər ən ɪkˈsaɪtɪŋ deɪ/"}]},{"number":2,"title":"XIN PHÉP VÀ QUY TẮC LỚP HỌC","titleEn":"ASKING PERMISSION","sentences":[{"id":"school500-02-001","number":1,"speaker":"Học sinh","en":"May I go out, teacher?","vi":"Thưa cô, cho em xin phép ra ngoài ạ!","ipa":"/meɪ aɪ ɡoʊ aʊt ˈtitʃər/"},{"id":"school500-02-002","number":2,"speaker":"Cô giáo","en":"Yes, you may.","vi":"Được chứ, em ra đi.","ipa":"/jɛs ju meɪ/"},{"id":"school500-02-003","number":3,"speaker":"Cô giáo","en":"Please come back soon.","vi":"Em nhớ quay lại lớp sớm nhé.","ipa":"/pliz kəm bæk sun/"},{"id":"school500-02-004","number":4,"speaker":"Học sinh","en":"May I come in, teacher?","vi":"Thưa cô, cho em xin phép vào lớp ạ!","ipa":"/meɪ aɪ kəm ɪn ˈtitʃər/"},{"id":"school500-02-005","number":5,"speaker":"Cô giáo","en":"Yes, please come in.","vi":"Được rồi, mời em vào lớp.","ipa":"/jɛs pliz kəm ɪn/"},{"id":"school500-02-006","number":6,"speaker":"Cô giáo","en":"Go to your seat, please.","vi":"Em về chỗ ngồi của mình nhé.","ipa":"/ɡoʊ tɪ jʊr sit pliz/"},{"id":"school500-02-007","number":7,"speaker":"Học sinh","en":"Thank you, teacher!","vi":"Em cảm ơn cô ạ!","ipa":"/θæŋk ju ˈtitʃər/"},{"id":"school500-02-008","number":8,"speaker":"Học sinh","en":"May I drink some water?","vi":"Thưa cô, cho em xin phép uống nước ạ!","ipa":"/meɪ aɪ drɪŋk səm ˈwɔtər/"},{"id":"school500-02-009","number":9,"speaker":"Cô giáo","en":"Yes, go ahead.","vi":"Được, em uống đi.","ipa":"/jɛs ɡoʊ əˈhɛd/"},{"id":"school500-02-010","number":10,"speaker":"Học sinh","en":"May I wash my hands?","vi":"Thưa cô, cho em xin phép đi rửa tay ạ!","ipa":"/meɪ aɪ wɑʃ maɪ hænz/"},{"id":"school500-02-011","number":11,"speaker":"Cô giáo","en":"Sure, be careful.","vi":"Được, em đi cẩn thận nhé.","ipa":"/ʃʊr bi ˈkɛrfəl/"},{"id":"school500-02-012","number":12,"speaker":"Học sinh","en":"May I ask a question?","vi":"Thưa cô, cho em xin phép hỏi một câu ạ!","ipa":"/meɪ aɪ æsk ə kˈwɛʃən/"},{"id":"school500-02-013","number":13,"speaker":"Cô giáo","en":"Yes, what is your question?","vi":"Được, câu hỏi của con là gì nào?","ipa":"/jɛs wət ɪz jʊr kˈwɛʃən/"},{"id":"school500-02-014","number":14,"speaker":"Học sinh","en":"May I sharpen my pencil?","vi":"Thưa cô, cho em xin phép gọt bút chì ạ!","ipa":"/meɪ aɪ ˈʃɑrpən maɪ ˈpɛnsəl/"},{"id":"school500-02-015","number":15,"speaker":"Cô giáo","en":"Yes, do it quickly.","vi":"Được, con gọt nhanh rồi về chỗ nhé.","ipa":"/jɛs du ɪt kˈwɪkli/"},{"id":"school500-02-016","number":16,"speaker":"Học sinh","en":"May I throw this into the trash can?","vi":"Thưa cô, cho em xin phép bỏ rác vào thùng ạ!","ipa":"/meɪ aɪ θroʊ ðɪs ˈɪntu ðə træʃ kən/"},{"id":"school500-02-017","number":17,"speaker":"Cô giáo","en":"Good boy / Good girl, go ahead.","vi":"Ngoan lắm, con bỏ vào thùng rác đi.","ipa":"/ɡʊd bɔɪ ɡʊd ɡərl ɡoʊ əˈhɛd/"},{"id":"school500-02-018","number":18,"speaker":"Học sinh","en":"I am sorry, I am late.","vi":"Thưa cô, em xin lỗi vì em đi học muộn ạ.","ipa":"/aɪ æm ˈsɑri aɪ æm leɪt/"},{"id":"school500-02-019","number":19,"speaker":"Cô giáo","en":"That's okay, sit down please.","vi":"Không sao, con vào chỗ ngồi đi.","ipa":"/ðæts ˌoʊˈkeɪ sɪt daʊn pliz/"},{"id":"school500-02-020","number":20,"speaker":"Cô giáo","en":"Try to be on time next time.","vi":"Lần sau con cố gắng đi học đúng giờ nhé.","ipa":"/traɪ tɪ bi ɔn taɪm nɛkst taɪm/"},{"id":"school500-02-021","number":21,"speaker":"Học sinh","en":"May I open the window, teacher?","vi":"Thưa cô, cho em xin phép mở cửa sổ ạ!","ipa":"/meɪ aɪ ˈoʊpən ðə ˈwɪndoʊ ˈtitʃər/"},{"id":"school500-02-022","number":22,"speaker":"Cô giáo","en":"Yes, let the fresh air in.","vi":"Được, con mở cho thoáng khí trong lành nhé.","ipa":"/jɛs lɛt ðə frɛʃ ɛr ɪn/"},{"id":"school500-02-023","number":23,"speaker":"Học sinh","en":"May I close the window, teacher?","vi":"Thưa cô, cho em xin phép đóng cửa sổ ạ!","ipa":"/meɪ aɪ kloʊz ðə ˈwɪndoʊ ˈtitʃər/"},{"id":"school500-02-024","number":24,"speaker":"Cô giáo","en":"Yes, it is windy outside.","vi":"Được con, bên ngoài gió đang thổi mạnh đấy.","ipa":"/jɛs ɪt ɪz ˈwɪndi ˈaʊtˈsaɪd/"},{"id":"school500-02-025","number":25,"speaker":"Học sinh","en":"May I turn on the light, please?","vi":"Thưa cô, cho em xin phép bật đèn lớp học ạ!","ipa":"/meɪ aɪ tərn ɔn ðə laɪt pliz/"},{"id":"school500-02-026","number":26,"speaker":"Cô giáo","en":"Sure, it is getting dark.","vi":"Được chứ, trời đang tối dần rồi đấy con.","ipa":"/ʃʊr ɪt ɪz ˈɡɪtɪŋ dɑrk/"},{"id":"school500-02-027","number":27,"speaker":"Học sinh","en":"May I turn on the electric fan?","vi":"Thưa cô, cho em xin phép bật quạt điện ạ!","ipa":"/meɪ aɪ tərn ɔn ðə ɪˈlɛktrɪk fæn/"},{"id":"school500-02-028","number":28,"speaker":"Cô giáo","en":"Yes, it is quite hot now.","vi":"Được, bây giờ thời tiết khá nóng rồi.","ipa":"/jɛs ɪt ɪz kwaɪt hɑt naʊ/"},{"id":"school500-02-029","number":29,"speaker":"Học sinh","en":"May I wipe the chalkboard?","vi":"Thưa cô, em xin phép lau bảng giúp cô ạ!","ipa":"/meɪ aɪ waɪp ðə ˈtʃɔkˌbɔrd/"},{"id":"school500-02-030","number":30,"speaker":"Cô giáo","en":"Thank you, that is very helpful.","vi":"Cô cảm ơn con, con ngoan và giúp ích lắm.","ipa":"/θæŋk ju ðət ɪz ˈvɛri ˈhɛlpfəl/"},{"id":"school500-02-031","number":31,"speaker":"Học sinh","en":"May I speak Vietnamese, teacher?","vi":"Thưa cô, em xin phép nói tiếng Việt được không ạ?","ipa":"/meɪ aɪ spik viˌɛtnɑˈmis ˈtitʃər/"},{"id":"school500-02-032","number":32,"speaker":"Cô giáo","en":"Try your best in English first, dear.","vi":"Con hãy cố gắng nói tiếng Anh trước đã nhé.","ipa":"/traɪ jʊr bɛst ɪn ˈɪŋlɪʃ fərst dɪr/"},{"id":"school500-02-033","number":33,"speaker":"Học sinh","en":"May I borrow a red pen from Lan?","vi":"Thưa cô, cho em xin phép mượn bút đỏ của bạn Lan ạ!","ipa":"/meɪ aɪ ˈbɑˌroʊ ə rɛd pɛn frəm læn/"},{"id":"school500-02-034","number":34,"speaker":"Cô giáo","en":"Yes, ask her politely.","vi":"Được, con hãy hỏi bạn thật lịch sự nhé.","ipa":"/jɛs æsk hər pəˈlaɪtli/"},{"id":"school500-02-035","number":35,"speaker":"Học sinh","en":"May I change my seat, teacher?","vi":"Thưa cô, cho em xin phép đổi chỗ ngồi được không ạ?","ipa":"/meɪ aɪ tʃeɪndʒ maɪ sit ˈtitʃər/"},{"id":"school500-02-036","number":36,"speaker":"Cô giáo","en":"Why do you want to change your seat?","vi":"Tại sao con lại muốn đổi chỗ ngồi thế?","ipa":"/waɪ du ju wɔnt tɪ tʃeɪndʒ jʊr sit/"},{"id":"school500-02-037","number":37,"speaker":"Học sinh","en":"I cannot see the board clearly from here.","vi":"Dạ từ chỗ này em nhìn bảng không được rõ ạ.","ipa":"/aɪ ˈkænɑt si ðə bɔrd ˈklɪrli frəm hir/"},{"id":"school500-02-038","number":38,"speaker":"Cô giáo","en":"Alright, move to the front row.","vi":"Được rồi, con chuyển lên bàn đầu ngồi nhé.","ipa":"/ˌɔˈlraɪt muv tɪ ðə frənt roʊ/"},{"id":"school500-02-039","number":39,"speaker":"Học sinh","en":"May I go to the nurse's room?","vi":"Thưa cô, cho em xin phép xuống phòng y tế ạ!","ipa":"/meɪ aɪ ɡoʊ tɪ ðə ˈnərsɪz rum/"},{"id":"school500-02-040","number":40,"speaker":"Cô giáo","en":"Are you feeling unwell, my dear?","vi":"Con cảm thấy không được khỏe phải không?","ipa":"/ər ju ˈfilɪŋ ənˈwɛl maɪ dɪr/"},{"id":"school500-02-041","number":41,"speaker":"Học sinh","en":"Yes, I have a headache, teacher.","vi":"Dạ vâng, em bị đau đầu thưa cô.","ipa":"/jɛs aɪ hæv ə ˈhɛˌdeɪk ˈtitʃər/"},{"id":"school500-02-042","number":42,"speaker":"Cô giáo","en":"Nam, please walk your friend to the medical room.","vi":"Nam ơi, con đưa bạn xuống phòng y tế giúp cô nhé.","ipa":"/næm pliz wɔk jʊr frɛnd tɪ ðə ˈmɛdɪkəl rum/"},{"id":"school500-02-043","number":43,"speaker":"Học sinh","en":"May I tie my shoelace, teacher?","vi":"Thưa cô, cho em xin phép buộc lại dây giày ạ!","ipa":"/meɪ aɪ taɪ maɪ ˈʃuˌleɪs ˈtitʃər/"},{"id":"school500-02-044","number":44,"speaker":"Cô giáo","en":"Yes, tie it safely so you don't fall.","vi":"Được, con buộc cẩn thận kẻo vấp ngã nhé.","ipa":"/jɛs taɪ ɪt ˈseɪfli soʊ ju doʊnt fɔl/"},{"id":"school500-02-045","number":45,"speaker":"Học sinh","en":"May I blow my nose, teacher?","vi":"Thưa cô, cho em xin phép xì mũi ạ!","ipa":"/meɪ aɪ bloʊ maɪ noʊz ˈtitʃər/"},{"id":"school500-02-046","number":46,"speaker":"Cô giáo","en":"Yes, use a tissue paper, please.","vi":"Được, con dùng giấy ăn lau sạch nhé.","ipa":"/jɛs juz ə ˈtɪʃu ˈpeɪpər pliz/"},{"id":"school500-02-047","number":47,"speaker":"Học sinh","en":"May I go to the school library?","vi":"Thưa cô, em có thể lên thư viện trường được không ạ?","ipa":"/meɪ aɪ ɡoʊ tɪ ðə skul ˈlaɪbrɛˌri/"},{"id":"school500-02-048","number":48,"speaker":"Cô giáo","en":"You can go during break time.","vi":"Giờ ra chơi con hãy lên thư viện nhé.","ipa":"/ju kən ɡoʊ ˈdʊrɪŋ breɪk taɪm/"},{"id":"school500-02-049","number":49,"speaker":"Học sinh","en":"May I pick up my dropped ruler?","vi":"Thưa cô, cho em xin cúi nhặt cây thước bị rơi ạ!","ipa":"/meɪ aɪ pɪk əp maɪ drɑpt ˈrulər/"},{"id":"school500-02-050","number":50,"speaker":"Cô giáo","en":"Yes, pick it up quietly, dear.","vi":"Được, con nhặt lên thật khẽ khàng nhé.","ipa":"/jɛs pɪk ɪt əp kˈwaɪətli dɪr/"}]},{"number":3,"title":"TIẾN TRÌNH TIẾT HỌC VÀ HIỆU LỆNH","titleEn":"DURING THE LESSON","sentences":[{"id":"school500-03-001","number":1,"speaker":"Cô giáo","en":"Open your book, please.","vi":"Các con mở sách ra nào.","ipa":"/ˈoʊpən jʊr bʊk pliz/"},{"id":"school500-03-002","number":2,"speaker":"Cô giáo","en":"Open page number ten.","vi":"Các con mở trang số mười nhé.","ipa":"/ˈoʊpən peɪdʒ ˈnəmbər tɛn/"},{"id":"school500-03-003","number":3,"speaker":"Cô giáo","en":"Close your book, please.","vi":"Các con gấp sách lại nào.","ipa":"/kloʊz jʊr bʊk pliz/"},{"id":"school500-03-004","number":4,"speaker":"Cô giáo","en":"Look at the board, please.","vi":"Các con hãy nhìn lên bảng nhé.","ipa":"/lʊk æt ðə bɔrd pliz/"},{"id":"school500-03-005","number":5,"speaker":"Cô giáo","en":"Listen carefully.","vi":"Các con hãy lắng nghe thật kỹ nhé.","ipa":"/ˈlɪsən ˈkɛrfəli/"},{"id":"school500-03-006","number":6,"speaker":"Cô giáo","en":"Listen and repeat after me.","vi":"Lắng nghe và nhắc lại theo cô nhé.","ipa":"/ˈlɪsən ənd rɪˈpit ˈæftər mi/"},{"id":"school500-03-007","number":7,"speaker":"Cô giáo","en":"Read aloud, please.","vi":"Mời các con đọc to lên nào.","ipa":"/rɛd əˈlaʊd pliz/"},{"id":"school500-03-008","number":8,"speaker":"Cô giáo","en":"Raise your hand, please.","vi":"Các con giơ tay phát biểu nào.","ipa":"/reɪz jʊr hænd pliz/"},{"id":"school500-03-009","number":9,"speaker":"Học sinh","en":"May I answer, teacher?","vi":"Thưa cô, cho em xin phép trả lời ạ!","ipa":"/meɪ aɪ ˈænsər ˈtitʃər/"},{"id":"school500-03-010","number":10,"speaker":"Học sinh","en":"I know the answer!","vi":"Thưa cô, em biết câu trả lời ạ!","ipa":"/aɪ noʊ ðə ˈænsər/"},{"id":"school500-03-011","number":11,"speaker":"Cô giáo","en":"Please stand up and answer.","vi":"Mời con đứng dậy trả lời nào.","ipa":"/pliz stænd əp ənd ˈænsər/"},{"id":"school500-03-012","number":12,"speaker":"Học sinh","en":"The answer is number five.","vi":"Thưa cô, câu trả lời là số năm ạ.","ipa":"/ðə ˈænsər ɪz ˈnəmbər faɪv/"},{"id":"school500-03-013","number":13,"speaker":"Cô giáo","en":"Good job! You are correct.","vi":"Làm tốt lắm! Con trả lời đúng rồi.","ipa":"/ɡʊd dʒɑb ju ər kərˈɛkt/"},{"id":"school500-03-014","number":14,"speaker":"Cô giáo","en":"Excellent! Give him a big hand.","vi":"Xuất sắc! Cả lớp thưởng bạn một tràng pháo tay nào.","ipa":"/ˈɛksələnt ɡɪv ɪm ə bɪɡ hænd/"},{"id":"school500-03-015","number":15,"speaker":"Cô giáo","en":"Do you understand the lesson?","vi":"Các con có hiểu bài không nào?","ipa":"/du ju ˌəndərˈstænd ðə ˈlɛsən/"},{"id":"school500-03-016","number":16,"speaker":"Học sinh","en":"Yes, we understand!","vi":"Thưa cô, chúng em hiểu bài rồi ạ!","ipa":"/jɛs wi ˌəndərˈstænd/"},{"id":"school500-03-017","number":17,"speaker":"Cô giáo","en":"Let's practice together.","vi":"Chúng ta cùng nhau luyện tập nhé.","ipa":"/lɛts ˈpræktɪs təˈɡɛðər/"},{"id":"school500-03-018","number":18,"speaker":"Cô giáo","en":"Work in pairs, please.","vi":"Các con hãy thảo luận theo cặp đôi nhé.","ipa":"/wərk ɪn pɛrz pliz/"},{"id":"school500-03-019","number":19,"speaker":"Cô giáo","en":"Time is up, everyone!","vi":"Đã hết giờ làm bài rồi các con ơi!","ipa":"/taɪm ɪz əp ˈɛvriˌwən/"},{"id":"school500-03-020","number":20,"speaker":"Cô giáo","en":"Put your pens down, please.","vi":"Các con đặt bút xuống bàn nào.","ipa":"/pʊt jʊr pɛnz daʊn pliz/"},{"id":"school500-03-021","number":21,"speaker":"Cô giáo","en":"Write this down in your notebook.","vi":"Các con hãy ghi chép bài này vào vở nhé.","ipa":"/raɪt ðɪs daʊn ɪn jʊr ˈnoʊtˌbʊk/"},{"id":"school500-03-022","number":22,"speaker":"Học sinh","en":"Teacher, I have finished writing.","vi":"Thưa cô, em đã viết bài xong rồi ạ.","ipa":"/ˈtitʃər aɪ hæv ˈfɪnɪʃt ˈraɪtɪŋ/"},{"id":"school500-03-023","number":23,"speaker":"Cô giáo","en":"Show me your notebook, please.","vi":"Con đưa vở cho cô kiểm tra nào.","ipa":"/ʃoʊ mi jʊr ˈnoʊtˌbʊk pliz/"},{"id":"school500-03-024","number":24,"speaker":"Cô giáo","en":"Your handwriting is very neat!","vi":"Chữ viết của con nắn nót và sạch đẹp lắm!","ipa":"/jʊr ˈhænˌdraɪtɪŋ ɪz ˈvɛri nit/"},{"id":"school500-03-025","number":25,"speaker":"Cô giáo","en":"Read paragraph one, please, Hoa.","vi":"Mời Hoa đọc đoạn văn thứ nhất nào.","ipa":"/rɛd ˈpɛrəˌɡræf wən pliz hwɑː/"},{"id":"school500-03-026","number":26,"speaker":"Học sinh","en":"I will read now, teacher.","vi":"Dạ em xin phép đọc bài thưa cô.","ipa":"/aɪ wɪl rɛd naʊ ˈtitʃər/"},{"id":"school500-03-027","number":27,"speaker":"Cô giáo","en":"Pronounce this sound again: /th/.","vi":"Con phát âm lại âm này nhé: /th/.","ipa":"/prəˈnaʊns ðɪs saʊnd əˈɡɛn ˈtiˈeɪtʃ/"},{"id":"school500-03-028","number":28,"speaker":"Học sinh","en":"Thank you, I will pronounce it better.","vi":"Em cảm ơn cô, em sẽ phát âm chuẩn hơn ạ.","ipa":"/θæŋk ju aɪ wɪl prəˈnaʊns ɪt ˈbɛtər/"},{"id":"school500-03-029","number":29,"speaker":"Cô giáo","en":"Who wants to come to the blackboard?","vi":"Bạn nào muốn lên bảng làm bài tập này nào?","ipa":"/hu wɔnts tɪ kəm tɪ ðə ˈblækˌbɔrd/"},{"id":"school500-03-030","number":30,"speaker":"Học sinh","en":"Teacher, please call me!","vi":"Thưa cô, cô gọi em đi ạ!","ipa":"/ˈtitʃər pliz kɔl mi/"},{"id":"school500-03-031","number":31,"speaker":"Cô giáo","en":"Take the piece of chalk, Minh.","vi":"Minh hãy cầm viên phấn lên viết bài nhé.","ipa":"/teɪk ðə pis əv tʃɔk mɪn/"},{"id":"school500-03-032","number":32,"speaker":"Học sinh","en":"I will solve this math equation.","vi":"Em sẽ giải bài toán này ạ.","ipa":"/aɪ wɪl sɑlv ðɪs mæθ ɪkˈweɪʒən/"},{"id":"school500-03-033","number":33,"speaker":"Cô giáo","en":"Check your classmate's answer, everyone.","vi":"Cả lớp hãy cùng nhận xét câu trả lời của bạn nào.","ipa":"/tʃɛk jʊr ˈklæsˌmeɪts ˈænsər ˈɛvriˌwən/"},{"id":"school500-03-034","number":34,"speaker":"Học sinh","en":"His answer is completely right!","vi":"Thưa cô, đáp án của bạn hoàn toàn chính xác ạ!","ipa":"/hɪz ˈænsər ɪz kəmˈplitli raɪt/"},{"id":"school500-03-035","number":35,"speaker":"Cô giáo","en":"Spell this new word, class.","vi":"Cả lớp cùng đánh vần từ mới này nào.","ipa":"/spɛl ðɪs nu wərd klæs/"},{"id":"school500-03-036","number":36,"speaker":"Cả lớp","en":"M - A - T - H, Math!","vi":"M - A - T - H, Math (Môn Toán)!","ipa":"/ɛm ə ti eɪtʃ mæθ/"},{"id":"school500-03-037","number":37,"speaker":"Cô giáo","en":"What is the meaning of this word?","vi":"Ý nghĩa của từ này là gì các con?","ipa":"/wət ɪz ðə ˈminɪŋ əv ðɪs wərd/"},{"id":"school500-03-038","number":38,"speaker":"Học sinh","en":"It means forest in Vietnamese.","vi":"Thưa cô, từ đó có nghĩa là khu rừng ạ.","ipa":"/ɪt minz ˈfɔrɪst ɪn viˌɛtnɑˈmis/"},{"id":"school500-03-039","number":39,"speaker":"Cô giáo","en":"Look at picture number three.","vi":"Các con hãy nhìn vào bức tranh số ba.","ipa":"/lʊk æt ˈpɪktʃər ˈnəmbər θri/"},{"id":"school500-03-040","number":40,"speaker":"Học sinh","en":"I see a cute bird on the branch.","vi":"Em nhìn thấy một chú chim non trên cành cây ạ.","ipa":"/aɪ si ə kjut bərd ɔn ðə bræntʃ/"},{"id":"school500-03-041","number":41,"speaker":"Cô giáo","en":"Count from one to twenty together.","vi":"Cả lớp cùng đếm từ một đến hai mươi nào.","ipa":"/kaʊnt frəm wən tɪ tˈwɛnti təˈɡɛðər/"},{"id":"school500-03-042","number":42,"speaker":"Cả lớp","en":"One, two, three... twenty!","vi":"Một, hai, ba... hai mươi!","ipa":"/wən tu θri tˈwɛnti/"},{"id":"school500-03-043","number":43,"speaker":"Cô giáo","en":"Don't copy your neighbor's work.","vi":"Các con tự làm bài, không nhìn bài của bạn bên cạnh nhé.","ipa":"/doʊnt ˈkɑpi jʊr ˈneɪbərz wərk/"},{"id":"school500-03-044","number":44,"speaker":"Học sinh","en":"Yes, I will do it by myself.","vi":"Vâng, em sẽ tự giác làm bài của mình ạ.","ipa":"/jɛs aɪ wɪl du ɪt baɪ ˌmaɪˈsɛlf/"},{"id":"school500-03-045","number":45,"speaker":"Cô giáo","en":"Raise your pencil if you are done.","vi":"Bạn nào làm xong rồi thì giơ bút chì lên nhé.","ipa":"/reɪz jʊr ˈpɛnsəl ɪf ju ər dən/"},{"id":"school500-03-046","number":46,"speaker":"Học sinh","en":"Teacher, I am done!","vi":"Thưa cô, em đã làm xong bài rồi ạ!","ipa":"/ˈtitʃər aɪ æm dən/"},{"id":"school500-03-047","number":47,"speaker":"Cô giáo","en":"You get a red star for this good answer!","vi":"Con được tặng một ngôi sao đỏ vì câu trả lời rất hay!","ipa":"/ju ɡɪt ə rɛd stɑr fər ðɪs ɡʊd ˈænsər/"},{"id":"school500-03-048","number":48,"speaker":"Học sinh","en":"Yay! Thank you very much, teacher!","vi":"A, em cảm ơn cô giáo nhiều lắm ạ!","ipa":"/jeɪ θæŋk ju ˈvɛri mətʃ ˈtitʃər/"},{"id":"school500-03-049","number":49,"speaker":"Cô giáo","en":"Review the lesson for one minute.","vi":"Các con hãy xem lại bài trong một phút nhé.","ipa":"/ˌrivˈju ðə ˈlɛsən fər wən ˈmɪnət/"},{"id":"school500-03-050","number":50,"speaker":"Cả lớp","en":"We have understood today's lesson!","vi":"Chúng em đều đã nắm vững bài học hôm nay rồi ạ!","ipa":"/wi hæv ˌəndərˈstʊd ˈtudeɪz ˈlɛsən/"}]},{"number":4,"title":"THẢO LUẬN NHÓM VÀ THUYẾT TRÌNH BÀI TẬP","titleEn":"GROUP WORK & PRESENTATION","sentences":[{"id":"school500-04-001","number":1,"speaker":"Cô giáo","en":"Make groups of four, please.","vi":"Các con hãy chia thành từng nhóm bốn bạn nhé.","ipa":"/meɪk ɡrups əv fɔr pliz/"},{"id":"school500-04-002","number":2,"speaker":"Cô giáo","en":"Choose a group leader, please.","vi":"Mỗi nhóm hãy bầu ra một bạn nhóm trưởng nào.","ipa":"/tʃuz ə ɡrup ˈlidər pliz/"},{"id":"school500-04-003","number":3,"speaker":"Học sinh A","en":"I am the group leader.","vi":"Tớ sẽ làm nhóm trưởng nhé.","ipa":"/aɪ æm ðə ɡrup ˈlidər/"},{"id":"school500-04-004","number":4,"speaker":"Học sinh B","en":"Let's work together!","vi":"Chúng mình cùng làm việc chung nhé!","ipa":"/lɛts wərk təˈɡɛðər/"},{"id":"school500-04-005","number":5,"speaker":"Học sinh A","en":"What is your idea?","vi":"Ý kiến của bạn thế nào?","ipa":"/wət ɪz jʊr aɪˈdiə/"},{"id":"school500-04-006","number":6,"speaker":"Học sinh B","en":"I think we should draw a chart.","vi":"Tớ nghĩ nhóm mình nên vẽ một sơ đồ.","ipa":"/aɪ θɪŋk wi ʃʊd drɔ ə tʃɑrt/"},{"id":"school500-04-007","number":7,"speaker":"Học sinh C","en":"I agree with you.","vi":"Tớ đồng ý với ý kiến của bạn.","ipa":"/aɪ əˈɡri wɪθ ju/"},{"id":"school500-04-008","number":8,"speaker":"Học sinh D","en":"I have another idea.","vi":"Tớ có một ý kiến khác này.","ipa":"/aɪ hæv əˈnəðər aɪˈdiə/"},{"id":"school500-04-009","number":9,"speaker":"Học sinh A","en":"Who will write the answers?","vi":"Ai sẽ là người viết câu trả lời nhỉ?","ipa":"/hu wɪl raɪt ðə ˈænsərz/"},{"id":"school500-04-010","number":10,"speaker":"Học sinh B","en":"I can write the answers.","vi":"Tớ có thể viết câu trả lời cho nhóm.","ipa":"/aɪ kən raɪt ðə ˈænsərz/"},{"id":"school500-04-011","number":11,"speaker":"Học sinh C","en":"Let me color the poster.","vi":"Để tớ tô màu bức tranh nhóm nhé.","ipa":"/lɛt mi ˈkələr ðə ˈpoʊstər/"},{"id":"school500-04-012","number":12,"speaker":"Cô giáo","en":"Two minutes left for your group!","vi":"Các nhóm còn hai phút nữa nhé!","ipa":"/tu ˈmɪnəts lɛft fər jʊr ɡrup/"},{"id":"school500-04-013","number":13,"speaker":"Học sinh A","en":"We are finished, teacher!","vi":"Thưa cô, nhóm em đã hoàn thành rồi ạ!","ipa":"/wi ər ˈfɪnɪʃt ˈtitʃər/"},{"id":"school500-04-014","number":14,"speaker":"Cô giáo","en":"Group One, please come to the board.","vi":"Cô mời Nhóm Một lên bảng thuyết trình nào.","ipa":"/ɡrup wən pliz kəm tɪ ðə bɔrd/"},{"id":"school500-04-015","number":15,"speaker":"Học sinh đại diện","en":"Hello everyone, this is our project.","vi":"Xin chào cô và các bạn, đây là bài tập của nhóm mình.","ipa":"/hɛˈloʊ ˈɛvriˌwən ðɪs ɪz ɑr ˈprɑdʒɛkt/"},{"id":"school500-04-016","number":16,"speaker":"Học sinh đại diện","en":"Here is our solution for problem one.","vi":"Đây là cách giải của nhóm mình cho bài toán một.","ipa":"/hir ɪz ɑr səˈluʃən fər ˈprɑbləm wən/"},{"id":"school500-04-017","number":17,"speaker":"Học sinh đại diện","en":"Does anyone have any questions?","vi":"Có bạn nào có câu hỏi gì cho nhóm mình không?","ipa":"/dɪz ˈɛniˌwən hæv ˈɛni kˈwɛstʃənz/"},{"id":"school500-04-018","number":18,"speaker":"Học sinh khác","en":"Why did you choose this answer?","vi":"Tại sao nhóm bạn lại chọn đáp án này?","ipa":"/waɪ dɪd ju tʃuz ðɪs ˈænsər/"},{"id":"school500-04-019","number":19,"speaker":"Học sinh đại diện","en":"Thank you for listening to our group.","vi":"Cảm ơn cô và các bạn đã lắng nghe nhóm mình.","ipa":"/θæŋk ju fər ˈlɪsənɪŋ tɪ ɑr ɡrup/"},{"id":"school500-04-020","number":20,"speaker":"Cô giáo","en":"Great presentation! Give them a big cheer!","vi":"Phần thuyết trình rất hay! Cả lớp cổ vũ nhóm bạn nào!","ipa":"/ɡreɪt ˌprɛzənˈteɪʃən ɡɪv ðɛm ə bɪɡ tʃɪr/"},{"id":"school500-04-021","number":21,"speaker":"Cô giáo","en":"Move your chairs together to form a circle.","vi":"Các con xếp ghế lại gần nhau thành hình tròn nhé.","ipa":"/muv jʊr tʃɛrz təˈɡɛðər tɪ fɔrm ə ˈsərkəl/"},{"id":"school500-04-022","number":22,"speaker":"Học sinh A","en":"Please sit next to me, Linh.","vi":"Linh ơi, cậu ngồi cạnh tớ nhé.","ipa":"/pliz sɪt nɛkst tɪ mi lɪn/"},{"id":"school500-04-023","number":23,"speaker":"Học sinh B","en":"Let's read the task carefully first.","vi":"Trước tiên chúng mình cùng đọc kỹ đề bài nhé.","ipa":"/lɛts rɛd ðə tæsk ˈkɛrfəli fərst/"},{"id":"school500-04-024","number":24,"speaker":"Học sinh C","en":"Who will keep time for our group?","vi":"Ai sẽ làm người bấm giờ cho nhóm mình đây?","ipa":"/hu wɪl kip taɪm fər ɑr ɡrup/"},{"id":"school500-04-025","number":25,"speaker":"Học sinh D","en":"I will keep track of the time.","vi":"Tớ sẽ theo dõi thời gian cho cả nhóm.","ipa":"/aɪ wɪl kip træk əv ðə taɪm/"},{"id":"school500-04-026","number":26,"speaker":"Học sinh A","en":"Speak louder so we can hear you.","vi":"Cậu nói to hơn một chút cho cả nhóm cùng nghe nhé.","ipa":"/spik ˈlaʊdər soʊ wi kən hir ju/"},{"id":"school500-04-027","number":27,"speaker":"Học sinh B","en":"Do you agree with step number two?","vi":"Cậu có đồng ý với bước làm thứ hai không?","ipa":"/du ju əˈɡri wɪθ stɛp ˈnəmbər tu/"},{"id":"school500-04-028","number":28,"speaker":"Học sinh C","en":"Yes, that step is very clear and logic.","vi":"Có, bước đó rất rõ ràng và hợp lý.","ipa":"/jɛs ðət stɛp ɪz ˈvɛri klɪr ənd ˈlɑdʒɪk/"},{"id":"school500-04-029","number":29,"speaker":"Học sinh D","en":"Let's check the calculation again.","vi":"Chúng mình cùng tính lại phép tính này xem sao nhé.","ipa":"/lɛts tʃɛk ðə ˌkælkjəˈleɪʃən əˈɡɛn/"},{"id":"school500-04-030","number":30,"speaker":"Học sinh A","en":"Three plus seven equals ten.","vi":"Ba cộng bảy bằng mười nè.","ipa":"/θri pləs ˈsɛvən ˈikwəlz tɛn/"},{"id":"school500-04-031","number":31,"speaker":"Học sinh B","en":"Hold the poster steady, please.","vi":"Cậu giữ tấm bảng báo cáo cho thật chắc nhé.","ipa":"/hoʊld ðə ˈpoʊstər ˈstɛdi pliz/"},{"id":"school500-04-032","number":32,"speaker":"Học sinh C","en":"I will use green crayon for the tree.","vi":"Tớ sẽ dùng sáp màu xanh lá cây để tô cái cây.","ipa":"/aɪ wɪl juz ɡrin kreɪɑn fər ðə tri/"},{"id":"school500-04-033","number":33,"speaker":"Cô giáo","en":"Discuss in a low voice, don't shout.","vi":"Các con thảo luận vừa đủ nghe, không nói to nhé.","ipa":"/dɪˈskəs ɪn ə loʊ vɔɪs doʊnt ʃaʊt/"},{"id":"school500-04-034","number":34,"speaker":"Học sinh A","en":"Yes, we will whisper quietly.","vi":"Vâng, nhóm mình sẽ nói nhỏ nhẹ thôi.","ipa":"/jɛs wi wɪl ˈwɪspər kˈwaɪətli/"},{"id":"school500-04-035","number":35,"speaker":"Học sinh B","en":"Are we all agreed on the final answer?","vi":"Tất cả chúng mình đã thống nhất câu trả lời cuối cùng chưa?","ipa":"/ər wi ɔl əˈɡrid ɔn ðə ˈfaɪnəl ˈænsər/"},{"id":"school500-04-036","number":36,"speaker":"Học sinh C","en":"Yes, we are one hundred percent sure!","vi":"Rồi, nhóm mình chắc chắn một trăm phần trăm!","ipa":"/jɛs wi ər wən ˈhənərd pərˈsɛnt ʃʊr/"},{"id":"school500-04-037","number":37,"speaker":"Cô giáo","en":"Times up! Stick your poster on the board.","vi":"Hết giờ rồi! Các nhóm dán bài lên bảng nào.","ipa":"/taɪmz əp stɪk jʊr ˈpoʊstər ɔn ðə bɔrd/"},{"id":"school500-04-038","number":38,"speaker":"Học sinh A","en":"I will tape our poster on the left side.","vi":"Tớ sẽ dán bài của nhóm mình bên góc trái nhé.","ipa":"/aɪ wɪl teɪp ɑr ˈpoʊstər ɔn ðə lɛft saɪd/"},{"id":"school500-04-039","number":39,"speaker":"Cô giáo","en":"Now let's listen to Group Two.","vi":"Bây giờ cả lớp cùng lắng nghe Nhóm Hai nhé.","ipa":"/naʊ lɛts ˈlɪsən tɪ ɡrup tu/"},{"id":"school500-04-040","number":40,"speaker":"Đại diện nhóm 2","en":"Good morning, teacher and friends.","vi":"Kính chào cô giáo và các bạn học sinh.","ipa":"/ɡʊd ˈmɔrnɪŋ ˈtitʃər ənd frɛndz/"},{"id":"school500-04-041","number":41,"speaker":"Đại diện nhóm 2","en":"Today our group presents about geometric shapes.","vi":"Hôm nay nhóm mình xin thuyết trình về các hình học.","ipa":"/təˈdeɪ ɑr ɡrup ˈprɛzənts əˈbaʊt ˌdʒiəˈmɛtrɪk ʃeɪps/"},{"id":"school500-04-042","number":42,"speaker":"Đại diện nhóm 2","en":"This is a circle, and this is a square.","vi":"Đây là hình tròn, và đây là hình vuông.","ipa":"/ðɪs ɪz ə ˈsərkəl ənd ðɪs ɪz ə skwɛr/"},{"id":"school500-04-043","number":43,"speaker":"Đại diện nhóm 2","en":"Squares have four equal sides.","vi":"Hình vuông có bốn cạnh bằng nhau.","ipa":"/skwɛrz hæv fɔr ˈikwəl saɪdz/"},{"id":"school500-04-044","number":44,"speaker":"Cô giáo","en":"Does anyone want to comment on Group Two?","vi":"Có bạn nào muốn nhận xét cho Nhóm Hai không?","ipa":"/dɪz ˈɛniˌwən wɔnt tɪ ˈkɑmɛnt ɔn ɡrup tu/"},{"id":"school500-04-045","number":45,"speaker":"Học sinh nhóm khác","en":"Their drawing is very colorful and clear.","vi":"Tranh vẽ của nhóm bạn rất nhiều màu sắc và rõ ràng.","ipa":"/ðɛr drɔɪŋ ɪz ˈvɛri ˈkələrfəl ənd klɪr/"},{"id":"school500-04-046","number":46,"speaker":"Học sinh nhóm khác","en":"The speaker spoke clearly and confidently.","vi":"Bạn thuyết trình nói rất to, rõ và tự tin.","ipa":"/ðə ˈspikər spoʊk ˈklɪrli ənd ˈkɑnfədəntli/"},{"id":"school500-04-047","number":47,"speaker":"Đại diện nhóm 2","en":"Thank you for your kind feedback!","vi":"Nhóm mình cảm ơn những lời góp ý quý báu của các bạn!","ipa":"/θæŋk ju fər jʊr kaɪnd ˈfidˌbæk/"},{"id":"school500-04-048","number":48,"speaker":"Cô giáo","en":"Both groups worked wonderfully together.","vi":"Cả hai nhóm đều đã làm việc đồng đội rất tuyệt vời.","ipa":"/boʊθ ɡrups wərkt ˈwəndərfəli təˈɡɛðər/"},{"id":"school500-04-049","number":49,"speaker":"Cô giáo","en":"Teamwork makes the dream work!","vi":"Tinh thần đồng đội sẽ tạo nên thành công lớn!","ipa":"/ˈtimˌwərk meɪks ðə drim wərk/"},{"id":"school500-04-050","number":50,"speaker":"Cả lớp","en":"Yay, we love working in teams!","vi":"Hoan hô, chúng em rất thích làm bài tập nhóm!","ipa":"/jeɪ wi ləv ˈwərkɪŋ ɪn timz/"}]},{"number":5,"title":"THẮC MẮC VÀ HỎI ĐÁP KHI CHƯA HIỂU BÀI","titleEn":"ASKING FOR HELP & CLARIFICATION","sentences":[{"id":"school500-05-001","number":1,"speaker":"Học sinh","en":"Excuse me, teacher!","vi":"Thưa cô, em xin phép ạ!","ipa":"/ɪkˈskjuz mi ˈtitʃər/"},{"id":"school500-05-002","number":2,"speaker":"Cô giáo","en":"Yes, what is the matter?","vi":"Ừ, có chuyện gì thế con?","ipa":"/jɛs wət ɪz ðə ˈmætər/"},{"id":"school500-05-003","number":3,"speaker":"Học sinh","en":"I don't understand this problem.","vi":"Thưa cô, em chưa hiểu bài toán này ạ.","ipa":"/aɪ doʊnt ˌəndərˈstænd ðɪs ˈprɑbləm/"},{"id":"school500-05-004","number":4,"speaker":"Cô giáo","en":"Which part don't you understand?","vi":"Con chưa hiểu ở phần nào?","ipa":"/wɪtʃ pɑrt doʊnt ju ˌəndərˈstænd/"},{"id":"school500-05-005","number":5,"speaker":"Học sinh","en":"I don't understand question number two.","vi":"Dạ thưa cô, em chưa hiểu câu hỏi số hai.","ipa":"/aɪ doʊnt ˌəndərˈstænd kˈwɛʃən ˈnəmbər tu/"},{"id":"school500-05-006","number":6,"speaker":"Học sinh","en":"Can you explain that again, please?","vi":"Cô có thể giải thích lại giúp em được không ạ?","ipa":"/kən ju ɪkˈspleɪn ðət əˈɡɛn pliz/"},{"id":"school500-05-007","number":7,"speaker":"Cô giáo","en":"Sure, look here and listen carefully.","vi":"Được chứ, con nhìn vào đây và lắng nghe kỹ nhé.","ipa":"/ʃʊr lʊk hir ənd ˈlɪsən ˈkɛrfəli/"},{"id":"school500-05-008","number":8,"speaker":"Học sinh","en":"What does this word mean, teacher?","vi":"Thưa cô, từ này có nghĩa là gì ạ?","ipa":"/wət dɪz ðɪs wərd min ˈtitʃər/"},{"id":"school500-05-009","number":9,"speaker":"Cô giáo","en":"It means addition in Math.","vi":"Từ này có nghĩa là phép cộng trong môn Toán.","ipa":"/ɪt minz əˈdɪʃən ɪn mæθ/"},{"id":"school500-05-010","number":10,"speaker":"Học sinh","en":"How do you pronounce this word?","vi":"Từ này phát âm như thế nào ạ cô?","ipa":"/haʊ du ju prəˈnaʊns ðɪs wərd/"},{"id":"school500-05-011","number":11,"speaker":"Cô giáo","en":"Listen to me: Triangle.","vi":"Con nghe cô phát âm nhé: Triangle (Hình tam giác).","ipa":"/ˈlɪsən tɪ mi ˈtraɪˌæŋɡəl/"},{"id":"school500-05-012","number":12,"speaker":"Học sinh","en":"Can you speak more slowly, please?","vi":"Cô có thể nói chậm lại một chút được không ạ?","ipa":"/kən ju spik mɔr sˈloʊli pliz/"},{"id":"school500-05-013","number":13,"speaker":"Cô giáo","en":"Of course, I will speak slowly.","vi":"Tất nhiên rồi, cô sẽ nói thật chậm nhé.","ipa":"/əv kɔrs aɪ wɪl spik sˈloʊli/"},{"id":"school500-05-014","number":14,"speaker":"Học sinh","en":"Is this correct, teacher?","vi":"Thưa cô, em làm thế này có đúng không ạ?","ipa":"/ɪz ðɪs kərˈɛkt ˈtitʃər/"},{"id":"school500-05-015","number":15,"speaker":"Cô giáo","en":"Almost correct, check the last number.","vi":"Gần đúng rồi con, hãy kiểm tra lại con số cuối cùng nhé.","ipa":"/ˈɔlˌmoʊst kərˈɛkt tʃɛk ðə læst ˈnəmbər/"},{"id":"school500-05-016","number":16,"speaker":"Học sinh","en":"I still don't know how to do it.","vi":"Dạ em vẫn chưa biết cách làm bài này ạ.","ipa":"/aɪ stɪl doʊnt noʊ haʊ tɪ du ɪt/"},{"id":"school500-05-017","number":17,"speaker":"Cô giáo","en":"Don't worry, our Robot will guide you.","vi":"Đừng lo, bạn Rô-bốt sẽ gợi ý từng bước cho con nhé.","ipa":"/doʊnt ˈwəri ɑr ˈroʊˌbət wɪl ɡaɪd ju/"},{"id":"school500-05-018","number":18,"speaker":"Học sinh","en":"Oh, I see it now!","vi":"A, bây giờ thì em hiểu rồi ạ!","ipa":"/oʊ aɪ si ɪt naʊ/"},{"id":"school500-05-019","number":19,"speaker":"Học sinh","en":"Thank you for helping me, teacher!","vi":"Em cảm ơn cô đã hướng dẫn cho em ạ!","ipa":"/θæŋk ju fər ˈhɛlpɪŋ mi ˈtitʃər/"},{"id":"school500-05-020","number":20,"speaker":"Cô giáo","en":"You are welcome. Always feel free to ask!","vi":"Không có gì con. Hãy luôn tự tin hỏi cô bất cứ lúc nào nhé!","ipa":"/ju ər ˈwɛlkəm ˈɔlˌweɪz fil fri tɪ æsk/"},{"id":"school500-05-021","number":21,"speaker":"Học sinh","en":"Teacher, I cannot hear you well.","vi":"Thưa cô, em nghe cô giảng chưa được rõ ạ.","ipa":"/ˈtitʃər aɪ ˈkænɑt hir ju wɛl/"},{"id":"school500-05-022","number":22,"speaker":"Cô giáo","en":"I will speak louder, dear.","vi":"Cô sẽ nói to hơn một chút nhé con.","ipa":"/aɪ wɪl spik ˈlaʊdər dɪr/"},{"id":"school500-05-023","number":23,"speaker":"Học sinh","en":"What page are we on, teacher?","vi":"Thưa cô, lớp mình đang học ở trang nào ạ?","ipa":"/wət peɪdʒ ər wi ɔn ˈtitʃər/"},{"id":"school500-05-024","number":24,"speaker":"Cô giáo","en":"We are on page number twenty-four.","vi":"Lớp mình đang ở trang số hai mươi tư con nhé.","ipa":"/wi ər ɔn peɪdʒ ˈnəmbər tˈwɛnti fɔr/"},{"id":"school500-05-025","number":25,"speaker":"Học sinh","en":"How do you spell this word, teacher?","vi":"Thưa cô, từ này đánh vần như thế nào ạ?","ipa":"/haʊ du ju spɛl ðɪs wərd ˈtitʃər/"},{"id":"school500-05-026","number":26,"speaker":"Cô giáo","en":"It is spelled S - C - H - O - O - L.","vi":"Đánh vần là S - C - H - O - O - L con nhé.","ipa":"/ɪt ɪz spɛld ɛs si eɪtʃ oʊ oʊ ɛl/"},{"id":"school500-05-027","number":27,"speaker":"Học sinh","en":"Does this word sound like 'cat'?","vi":"Từ này có phát âm vần giống từ 'cat' không ạ?","ipa":"/dɪz ðɪs wərd saʊnd laɪk kæt/"},{"id":"school500-05-028","number":28,"speaker":"Cô giáo","en":"Yes, exactly! Cat and bat rhyme.","vi":"Đúng rồi, chính xác! Cat và bat có vần giống nhau.","ipa":"/jɛs ɪɡˈzæktli kæt ənd bæt raɪm/"},{"id":"school500-05-029","number":29,"speaker":"Học sinh","en":"Should I write in pen or pencil?","vi":"Thưa cô, em nên viết bằng bút mực hay bút chì ạ?","ipa":"/ʃʊd aɪ raɪt ɪn pɛn ər ˈpɛnsəl/"},{"id":"school500-05-030","number":30,"speaker":"Cô giáo","en":"Please use pencil to draw shapes.","vi":"Con hãy dùng bút chì để vẽ các hình học nhé.","ipa":"/pliz juz ˈpɛnsəl tɪ drɔ ʃeɪps/"},{"id":"school500-05-031","number":31,"speaker":"Học sinh","en":"Can I do exercise three first?","vi":"Em có thể làm bài tập ba trước được không ạ?","ipa":"/kən aɪ du ˈɛksərˌsaɪz θri fərst/"},{"id":"school500-05-032","number":32,"speaker":"Cô giáo","en":"No, please finish exercise one first.","vi":"Chưa được con, hãy hoàn thành bài một trước nhé.","ipa":"/noʊ pliz ˈfɪnɪʃ ˈɛksərˌsaɪz wən fərst/"},{"id":"school500-05-033","number":33,"speaker":"Học sinh","en":"What is the difference between plus and minus?","vi":"Dấu cộng và dấu trừ khác nhau thế nào ạ cô?","ipa":"/wət ɪz ðə ˈdɪfərəns bɪtˈwin pləs ənd ˈmaɪnəs/"},{"id":"school500-05-034","number":34,"speaker":"Cô giáo","en":"Plus means add more, minus means take away.","vi":"Dấu cộng là thêm vào, còn dấu trừ là bớt đi con nhé.","ipa":"/pləs minz æd mɔr ˈmaɪnəs minz teɪk əˈweɪ/"},{"id":"school500-05-035","number":35,"speaker":"Học sinh","en":"Why is my answer wrong, teacher?","vi":"Thưa cô, vì sao bài làm này của em bị sai ạ?","ipa":"/waɪ ɪz maɪ ˈænsər rɔŋ ˈtitʃər/"},{"id":"school500-05-036","number":36,"speaker":"Cô giáo","en":"You forgot to carry the number one.","vi":"Con quên nhớ một ở hàng chục rồi nè.","ipa":"/ju fərˈɡɑt tɪ ˈkɛri ðə ˈnəmbər wən/"},{"id":"school500-05-037","number":37,"speaker":"Học sinh","en":"Oh, I forgot that step!","vi":"Ôi, em sơ ý quên mất bước nhớ ấy rồi!","ipa":"/oʊ aɪ fərˈɡɑt ðət stɛp/"},{"id":"school500-05-038","number":38,"speaker":"Cô giáo","en":"Be careful next time, my dear student.","vi":"Lần sau con chú ý cẩn thận hơn là được nhé.","ipa":"/bi ˈkɛrfəl nɛkst taɪm maɪ dɪr ˈstudənt/"},{"id":"school500-05-039","number":39,"speaker":"Học sinh","en":"Can you give an example, teacher?","vi":"Cô có thể cho một ví dụ minh họa được không ạ?","ipa":"/kən ju ɡɪv ən ɪɡˈzæmpəl ˈtitʃər/"},{"id":"school500-05-040","number":40,"speaker":"Cô giáo","en":"If you have two apples and I give you one...","vi":"Nếu con có hai quả táo và cô cho con thêm một quả...","ipa":"/ɪf ju hæv tu ˈæpəlz ənd aɪ ɡɪv ju wən/"},{"id":"school500-05-041","number":41,"speaker":"Học sinh","en":"Then I have three apples!","vi":"Dạ thế thì em có tất cả ba quả táo ạ!","ipa":"/ðɛn aɪ hæv θri ˈæpəlz/"},{"id":"school500-05-042","number":42,"speaker":"Cô giáo","en":"Exactly! That is addition.","vi":"Chính xác! Đó chính là phép cộng đấy con.","ipa":"/ɪɡˈzæktli ðət ɪz əˈdɪʃən/"},{"id":"school500-05-043","number":43,"speaker":"Học sinh","en":"Is this homework for tonight?","vi":"Đây có phải bài tập về nhà tối nay không ạ?","ipa":"/ɪz ðɪs ˈhoʊmˌwərk fər təˈnaɪt/"},{"id":"school500-05-044","number":44,"speaker":"Cô giáo","en":"Yes, do question four and five at home.","vi":"Đúng rồi, con làm câu bốn và câu năm ở nhà nhé.","ipa":"/jɛs du kˈwɛʃən fɔr ənd faɪv æt hoʊm/"},{"id":"school500-05-045","number":45,"speaker":"Học sinh","en":"Teacher, my ink has run out.","vi":"Thưa cô, bút của em vừa bị hết mực ạ.","ipa":"/ˈtitʃər maɪ ɪŋk həz rən aʊt/"},{"id":"school500-05-046","number":46,"speaker":"Cô giáo","en":"Ask your deskmate to lend you a pen.","vi":"Con hãy hỏi mượn bạn cùng bàn một chiếc bút nhé.","ipa":"/æsk jʊr ˈdɛskˌmeɪt tɪ lɛnd ju ə pɛn/"},{"id":"school500-05-047","number":47,"speaker":"Học sinh","en":"Where do I write the title?","vi":"Em viết tiêu đề bài học ở chỗ nào ạ?","ipa":"/wɛr du aɪ raɪt ðə ˈtaɪtəl/"},{"id":"school500-05-048","number":48,"speaker":"Cô giáo","en":"Write it in the center of the first line.","vi":"Con viết ngay chính giữa dòng kẻ đầu tiên nhé.","ipa":"/raɪt ɪt ɪn ðə ˈsɛnər əv ðə fərst laɪn/"},{"id":"school500-05-049","number":49,"speaker":"Học sinh","en":"Now everything is clear to me!","vi":"Bây giờ mọi thứ đã rất sáng tỏ với em rồi ạ!","ipa":"/naʊ ˈɛvriˌθɪŋ ɪz klɪr tɪ mi/"},{"id":"school500-05-050","number":50,"speaker":"Cô giáo","en":"Never hesitate to ask when you are curious!","vi":"Đừng ngần ngại hỏi khi con muốn tìm hiểu nhé!","ipa":"/ˈnɛvər ˈhɛzəˌteɪt tɪ æsk wɪn ju ər ˈkjʊriəs/"}]},{"number":6,"title":"ĐỒ DÙNG HỌC TẬP VÀ GIÚP ĐỠ BẠN BÈ","titleEn":"SCHOOL SUPPLIES & HELPING","sentences":[{"id":"school500-06-001","number":1,"speaker":"Cô giáo","en":"Take out your pencil and notebook.","vi":"Các con lấy bút chì và vở ghi ra nhé.","ipa":"/teɪk aʊt jʊr ˈpɛnsəl ənd ˈnoʊtˌbʊk/"},{"id":"school500-06-002","number":2,"speaker":"Học sinh A","en":"Can I borrow your pencil, please?","vi":"Bạn cho mình mượn cây bút chì nhé?","ipa":"/kən aɪ ˈbɑˌroʊ jʊr ˈpɛnsəl pliz/"},{"id":"school500-06-003","number":3,"speaker":"Học sinh B","en":"Yes, here you are.","vi":"Được chứ, bút của bạn đây.","ipa":"/jɛs hir ju ər/"},{"id":"school500-06-004","number":4,"speaker":"Học sinh A","en":"Thank you very much!","vi":"Cảm ơn bạn rất nhiều!","ipa":"/θæŋk ju ˈvɛri mətʃ/"},{"id":"school500-06-005","number":5,"speaker":"Học sinh B","en":"You're welcome!","vi":"Không có chi đâu bạn!","ipa":"/jʊr ˈwɛlkəm/"},{"id":"school500-06-006","number":6,"speaker":"Học sinh A","en":"Can I borrow your eraser?","vi":"Bạn cho mình mượn cục tẩy một chút nhé?","ipa":"/kən aɪ ˈbɑˌroʊ jʊr ɪˈreɪsər/"},{"id":"school500-06-007","number":7,"speaker":"Học sinh B","en":"Sure, take it.","vi":"Được chứ, bạn cầm lấy đi.","ipa":"/ʃʊr teɪk ɪt/"},{"id":"school500-06-008","number":8,"speaker":"Học sinh A","en":"Can I borrow your ruler?","vi":"Bạn có thể cho mình mượn cây thước kẻ không?","ipa":"/kən aɪ ˈbɑˌroʊ jʊr ˈrulər/"},{"id":"school500-06-009","number":9,"speaker":"Học sinh B","en":"Sorry, I am using it now.","vi":"Xin lỗi nhé, mình đang dùng mất rồi.","ipa":"/ˈsɑri aɪ æm ˈjuzɪŋ ɪt naʊ/"},{"id":"school500-06-010","number":10,"speaker":"Học sinh A","en":"That's okay, no problem.","vi":"Không sao đâu bạn, không có gì cả.","ipa":"/ðæts ˌoʊˈkeɪ noʊ ˈprɑbləm/"},{"id":"school500-06-011","number":11,"speaker":"Học sinh A","en":"Is this your pen?","vi":"Cây bút này có phải của bạn không?","ipa":"/ɪz ðɪs jʊr pɛn/"},{"id":"school500-06-012","number":12,"speaker":"Học sinh B","en":"Yes, it is mine. Thank you!","vi":"Đúng rồi, của mình đấy. Cảm ơn bạn nhé!","ipa":"/jɛs ɪt ɪz maɪn θæŋk ju/"},{"id":"school500-06-013","number":13,"speaker":"Học sinh A","en":"I dropped my book.","vi":"Tớ vừa làm rơi cuốn sách mất rồi.","ipa":"/aɪ drɑpt maɪ bʊk/"},{"id":"school500-06-014","number":14,"speaker":"Học sinh B","en":"Let me help you pick it up.","vi":"Để tớ nhặt lên giúp bạn nhé.","ipa":"/lɛt mi hɛlp ju pɪk ɪt əp/"},{"id":"school500-06-015","number":15,"speaker":"Học sinh A","en":"You are so kind, thank you!","vi":"Bạn tốt bụng quá, cảm ơn bạn nhé!","ipa":"/ju ər soʊ kaɪnd θæŋk ju/"},{"id":"school500-06-016","number":16,"speaker":"Học sinh A","en":"Oops, I am sorry!","vi":"Ôi, mình vô ý xin lỗi bạn nhé!","ipa":"/ups aɪ æm ˈsɑri/"},{"id":"school500-06-017","number":17,"speaker":"Học sinh B","en":"That's alright, don't worry.","vi":"Không sao đâu bạn, đừng lo nhé.","ipa":"/ðæts ˌɔˈlraɪt doʊnt ˈwəri/"},{"id":"school500-06-018","number":18,"speaker":"Học sinh A","en":"Let's share this book together.","vi":"Chúng mình cùng xem chung cuốn sách này nhé.","ipa":"/lɛts ʃɛr ðɪs bʊk təˈɡɛðər/"},{"id":"school500-06-019","number":19,"speaker":"Học sinh B","en":"Great idea!","vi":"Ý kiến hay quá!","ipa":"/ɡreɪt aɪˈdiə/"},{"id":"school500-06-020","number":20,"speaker":"Cô giáo","en":"Good friends always share and help.","vi":"Bạn tốt luôn biết chia sẻ và giúp đỡ nhau.","ipa":"/ɡʊd frɛndz ˈɔlˌweɪz ʃɛr ənd hɛlp/"},{"id":"school500-06-021","number":21,"speaker":"Học sinh A","en":"Do you have red crayon?","vi":"Bạn có cây bút màu sáp đỏ không?","ipa":"/du ju hæv rɛd kreɪɑn/"},{"id":"school500-06-022","number":22,"speaker":"Học sinh B","en":"Yes, I have two red crayons.","vi":"Có, tớ có hai cây bút màu sáp đỏ này.","ipa":"/jɛs aɪ hæv tu rɛd kreɪɑnz/"},{"id":"school500-06-023","number":23,"speaker":"Học sinh A","en":"Can you lend me one?","vi":"Bạn cho tớ mượn một cây nhé?","ipa":"/kən ju lɛnd mi wən/"},{"id":"school500-06-024","number":24,"speaker":"Học sinh B","en":"Here it is, draw nicely!","vi":"Của bạn đây, vẽ thật đẹp nhé!","ipa":"/hir ɪt ɪz drɔ ˈnaɪsli/"},{"id":"school500-06-025","number":25,"speaker":"Học sinh A","en":"Where is my pencil sharpener?","vi":"Cái gọt bút chì của tớ đâu rồi nhỉ?","ipa":"/wɛr ɪz maɪ ˈpɛnsəl ˈʃɑrpənər/"},{"id":"school500-06-026","number":26,"speaker":"Học sinh B","en":"You can use my sharpener.","vi":"Cậu có thể dùng cái gọt bút chì của tớ này.","ipa":"/ju kən juz maɪ ˈʃɑrpənər/"},{"id":"school500-06-027","number":27,"speaker":"Học sinh A","en":"Thanks, be careful with pencil shavings.","vi":"Cảm ơn nhé, gọt xong nhớ giữ gọt vụn kẻo bay bẩn.","ipa":"/θæŋks bi ˈkɛrfəl wɪθ ˈpɛnsəl ˈʃeɪvɪŋz/"},{"id":"school500-06-028","number":28,"speaker":"Học sinh B","en":"I will throw the shavings into the bin.","vi":"Tớ sẽ đổ vỏ bào bút chì vào sọt rác ngay.","ipa":"/aɪ wɪl θroʊ ðə ˈʃeɪvɪŋz ˈɪntu ðə bɪn/"},{"id":"school500-06-029","number":29,"speaker":"Học sinh A","en":"Can I borrow your glue stick?","vi":"Bạn cho tớ mượn thỏi keo dán giấy nhé?","ipa":"/kən aɪ ˈbɑˌroʊ jʊr ɡlu stɪk/"},{"id":"school500-06-030","number":30,"speaker":"Học sinh B","en":"Here, put the cap on after using.","vi":"Đây nè, dùng xong nhớ đậy nắp lại kẻo khô nhé.","ipa":"/hir pʊt ðə kæp ɔn ˈæftər ˈjuzɪŋ/"},{"id":"school500-06-031","number":31,"speaker":"Học sinh A","en":"Can I borrow safety scissors?","vi":"Cho mình mượn cái kéo cắt thủ công nhé?","ipa":"/kən aɪ ˈbɑˌroʊ ˈseɪfti ˈsɪzərz/"},{"id":"school500-06-032","number":32,"speaker":"Học sinh B","en":"Hold the scissors by the handle safely.","vi":"Cậu nhớ cầm kéo đằng chuôi cho an toàn nha.","ipa":"/hoʊld ðə ˈsɪzərz baɪ ðə ˈhændəl ˈseɪfli/"},{"id":"school500-06-033","number":33,"speaker":"Học sinh A","en":"I forgot my textbook at home today.","vi":"Hôm nay tớ lỡ để quên sách giáo khoa ở nhà rồi.","ipa":"/aɪ fərˈɡɑt maɪ ˈtɛkstˌbʊk æt hoʊm təˈdeɪ/"},{"id":"school500-06-034","number":34,"speaker":"Học sinh B","en":"Don't worry, look at my book with me.","vi":"Đừng lo, cậu cùng nhìn chung sách với tớ này.","ipa":"/doʊnt ˈwəri lʊk æt maɪ bʊk wɪθ mi/"},{"id":"school500-06-035","number":35,"speaker":"Học sinh A","en":"You are my best friend!","vi":"Cậu đúng là người bạn thân tuyệt nhất của tớ!","ipa":"/ju ər maɪ bɛst frɛnd/"},{"id":"school500-06-036","number":36,"speaker":"Học sinh B","en":"Friends always help each other.","vi":"Bạn bè là luôn luôn giúp đỡ nhau mà.","ipa":"/frɛndz ˈɔlˌweɪz hɛlp itʃ ˈəðər/"},{"id":"school500-06-037","number":37,"speaker":"Học sinh A","en":"Whose pencil box is this on the floor?","vi":"Hộp bút của ai bị rơi dưới sàn đây nhỉ?","ipa":"/huz ˈpɛnsəl bɑks ɪz ðɪs ɔn ðə flɔr/"},{"id":"school500-06-038","number":38,"speaker":"Học sinh C","en":"It is mine, it slipped from my desk.","vi":"Của tớ đấy, nó vừa bị tuột khỏi mép bàn.","ipa":"/ɪt ɪz maɪn ɪt slɪpt frəm maɪ dɛsk/"},{"id":"school500-06-039","number":39,"speaker":"Học sinh A","en":"Here, put it securely on your desk.","vi":"Của bạn đây, để chắc chắn vào giữa bàn nhé.","ipa":"/hir pʊt ɪt sɪˈkjʊrli ɔn jʊr dɛsk/"},{"id":"school500-06-040","number":40,"speaker":"Học sinh C","en":"Thank you for finding it for me!","vi":"Cảm ơn bạn đã tìm thấy và nhặt giúp tớ!","ipa":"/θæŋk ju fər ˈfaɪndɪŋ ɪt fər mi/"},{"id":"school500-06-041","number":41,"speaker":"Học sinh A","en":"Do you have a spare notebook?","vi":"Bạn có quyển vở ghi chép dự phòng nào không?","ipa":"/du ju hæv ə spɛr ˈnoʊtˌbʊk/"},{"id":"school500-06-042","number":42,"speaker":"Học sinh B","en":"Yes, take this new notebook.","vi":"Có nè, bạn lấy quyển vở mới này mà dùng.","ipa":"/jɛs teɪk ðɪs nu ˈnoʊtˌbʊk/"},{"id":"school500-06-043","number":43,"speaker":"Học sinh A","en":"I will return a new one tomorrow.","vi":"Ngày mai tớ sẽ mang trả lại bạn một quyển mới nhé.","ipa":"/aɪ wɪl rɪˈtərn ə nu wən təˈmɑˌroʊ/"},{"id":"school500-06-044","number":44,"speaker":"Học sinh B","en":"No worries, keep it to study.","vi":"Không sao đâu, bạn cứ giữ lấy mà học tập.","ipa":"/noʊ ˈwəriz kip ɪt tɪ ˈstədi/"},{"id":"school500-06-045","number":45,"speaker":"Học sinh A","en":"Let me sharpen your colored pencils for you.","vi":"Để tớ gọt giúp bạn mấy cây bút chì màu nhé.","ipa":"/lɛt mi ˈʃɑrpən jʊr ˈkələrd ˈpɛnsəlz fər ju/"},{"id":"school500-06-046","number":46,"speaker":"Học sinh B","en":"That is so sweet of you, thank you!","vi":"Bạn thật chu đáo và tốt bụng, cảm ơn bạn nhiều!","ipa":"/ðət ɪz soʊ swit əv ju θæŋk ju/"},{"id":"school500-06-047","number":47,"speaker":"Cô giáo","en":"I am very proud of your kindness.","vi":"Cô rất tự hào vì các con luôn yêu thương giúp đỡ nhau.","ipa":"/aɪ æm ˈvɛri praʊd əv jʊr ˈkaɪndnəs/"},{"id":"school500-06-048","number":48,"speaker":"Học sinh","en":"Sharing makes us happy, teacher!","vi":"Biết sẻ chia giúp chúng em thấy rất vui ạ!","ipa":"/ˈʃɛrɪŋ meɪks ˈjuˈɛs ˈhæpi ˈtitʃər/"},{"id":"school500-06-049","number":49,"speaker":"Cô giáo","en":"Put all borrowed items back in place.","vi":"Các con nhớ trả lại đồ dùng đã mượn về đúng chỗ nhé.","ipa":"/pʊt ɔl ˈbɑˌroʊd ˈaɪtəmz bæk ɪn pleɪs/"},{"id":"school500-06-050","number":50,"speaker":"Cả lớp","en":"Yes, we always take good care of school tools!","vi":"Vâng ạ, chúng em luôn giữ gìn đồ dùng cẩn thận!","ipa":"/jɛs wi ˈɔlˌweɪz teɪk ɡʊd kɛr əv skul tulz/"}]},{"number":7,"title":"SẮP XẾP SÁCH VỞ VÀ BÀN GHẾ NGĂN NẮP","titleEn":"ORGANIZING BOOKS & DESKS","sentences":[{"id":"school500-07-001","number":1,"speaker":"Cô giáo","en":"Let's organize our desks, children.","vi":"Các con hãy sắp xếp lại bàn học cho ngăn nắp nào.","ipa":"/lɛts ˈɔrɡəˌnaɪz ɑr dɛsks ˈtʃɪldrən/"},{"id":"school500-07-002","number":2,"speaker":"Cô giáo","en":"Put your books into your desk drawer.","vi":"Các con cất sách vào trong ngăn bàn nhé.","ipa":"/pʊt jʊr bʊks ˈɪntu jʊr dɛsk drɔr/"},{"id":"school500-07-003","number":3,"speaker":"Học sinh A","en":"My books are neat and tidy.","vi":"Sách vở của tớ đã rất gọn gàng rồi.","ipa":"/maɪ bʊks ər nit ənd ˈtaɪdi/"},{"id":"school500-07-004","number":4,"speaker":"Cô giáo","en":"Put your pens into your pencil case.","vi":"Các con hãy cất bút vào hộp bút nhé.","ipa":"/pʊt jʊr pɛnz ˈɪntu jʊr ˈpɛnsəl keɪs/"},{"id":"school500-07-005","number":5,"speaker":"Học sinh B","en":"I am putting my pencils away.","vi":"Tớ đang cất những cây bút chì vào đây.","ipa":"/aɪ æm ˈpʊtɪŋ maɪ ˈpɛnsəlz əˈweɪ/"},{"id":"school500-07-006","number":6,"speaker":"Cô giáo","en":"Zip up your pencil case, please.","vi":"Con nhớ kéo khóa hộp bút lại nhé.","ipa":"/zɪp əp jʊr ˈpɛnsəl keɪs pliz/"},{"id":"school500-07-007","number":7,"speaker":"Cô giáo","en":"Straighten your desk and chair.","vi":"Các con hãy kê bàn và ghế cho thẳng hàng nào.","ipa":"/ˈstreɪtən jʊr dɛsk ənd tʃɛr/"},{"id":"school500-07-008","number":8,"speaker":"Học sinh A","en":"Let's pull our desk forward a little.","vi":"Chúng mình kéo bàn lên phía trước một chút nhé.","ipa":"/lɛts pʊl ɑr dɛsk ˈfɔrwərd ə ˈlɪtəl/"},{"id":"school500-07-009","number":9,"speaker":"Học sinh B","en":"Is our desk straight now?","vi":"Bàn của nhóm mình đã thẳng hàng chưa nhỉ?","ipa":"/ɪz ɑr dɛsk streɪt naʊ/"},{"id":"school500-07-010","number":10,"speaker":"Học sinh A","en":"Yes, it is perfectly in line.","vi":"Thẳng hàng tăm tắp rồi đấy bạn.","ipa":"/jɛs ɪt ɪz ˈpərfəktli ɪn laɪn/"},{"id":"school500-07-011","number":11,"speaker":"Cô giáo","en":"Push your chair in under the table.","vi":"Các con nhớ đẩy ghế vào sát gầm bàn nhé.","ipa":"/pʊʃ jʊr tʃɛr ɪn ˈəndər ðə ˈteɪbəl/"},{"id":"school500-07-012","number":12,"speaker":"Học sinh B","en":"I am pushing my chair in.","vi":"Tớ đang đẩy ghế vào sát gầm bàn rồi.","ipa":"/aɪ æm ˈpʊʃɪŋ maɪ tʃɛr ɪn/"},{"id":"school500-07-013","number":13,"speaker":"Cô giáo","en":"Hang your school bag on the hook.","vi":"Các con treo cặp sách lên móc bên cạnh bàn nhé.","ipa":"/hæŋ jʊr skul bæɡ ɔn ðə hʊk/"},{"id":"school500-07-014","number":14,"speaker":"Học sinh A","en":"My bag is hung neatly.","vi":"Cặp sách của tớ đã được treo rất gọn.","ipa":"/maɪ bæɡ ɪz həŋ ˈnitli/"},{"id":"school500-07-015","number":15,"speaker":"Cô giáo","en":"Don't leave papers on your desk.","vi":"Các con đừng để giấy vụn bừa bãi trên mặt bàn nhé.","ipa":"/doʊnt liv ˈpeɪpərz ɔn jʊr dɛsk/"},{"id":"school500-07-016","number":16,"speaker":"Học sinh B","en":"Let's clear the desk surface.","vi":"Chúng mình cùng dọn sạch mặt bàn nào.","ipa":"/lɛts klɪr ðə dɛsk ˈsərfəs/"},{"id":"school500-07-017","number":17,"speaker":"Cô giáo","en":"Check your floor under the desk.","vi":"Các con kiểm tra xem dưới chân bàn có đồ rơi không nhé.","ipa":"/tʃɛk jʊr flɔr ˈəndər ðə dɛsk/"},{"id":"school500-07-018","number":18,"speaker":"Học sinh A","en":"There is nothing on the floor.","vi":"Dưới sàn không có gì rơi rớt cả.","ipa":"/ðɛr ɪz ˈnəθɪŋ ɔn ðə flɔr/"},{"id":"school500-07-019","number":19,"speaker":"Cô giáo","en":"Your classroom looks so tidy!","vi":"Lớp học của chúng mình trông thật ngăn nắp!","ipa":"/jʊr ˈklæsˌrum lʊks soʊ ˈtaɪdi/"},{"id":"school500-07-020","number":20,"speaker":"Cả lớp","en":"A tidy classroom makes learning fun!","vi":"Lớp học gọn gàng giúp học tập thật vui ạ!","ipa":"/ə ˈtaɪdi ˈklæsˌrum meɪks ˈlərnɪŋ fən/"},{"id":"school500-07-021","number":21,"speaker":"Cô giáo","en":"Sort your notebooks by subject.","vi":"Các con hãy phân loại vở theo từng môn học nhé.","ipa":"/sɔrt jʊr ˈnoʊtˌbʊks baɪ ˈsəbdʒɪkt/"},{"id":"school500-07-022","number":22,"speaker":"Học sinh A","en":"Math notebook goes on top.","vi":"Vở bài tập Toán tớ để lên phía trên cùng này.","ipa":"/mæθ ˈnoʊtˌbʊk ɡoʊz ɔn tɔp/"},{"id":"school500-07-023","number":23,"speaker":"Học sinh B","en":"English notebook goes under Math.","vi":"Vở Tiếng Anh tớ xếp ngay dưới vở Toán.","ipa":"/ˈɪŋlɪʃ ˈnoʊtˌbʊk ɡoʊz ˈəndər mæθ/"},{"id":"school500-07-024","number":24,"speaker":"Cô giáo","en":"Close all book covers neatly.","vi":"Các con nhớ vuốt mép bìa sách cho phẳng phiu nhé.","ipa":"/kloʊz ɔl bʊk ˈkəvərz ˈnitli/"},{"id":"school500-07-025","number":25,"speaker":"Học sinh A","en":"Do not fold the page corners.","vi":"Đừng làm quăn mép góc trang sách bạn nhé.","ipa":"/du nɑt foʊld ðə peɪdʒ ˈkɔrnərz/"},{"id":"school500-07-026","number":26,"speaker":"Học sinh B","en":"I use a bookmark instead of folding.","vi":"Tớ dùng thẻ kẹp sách chứ không gập mép giấy đâu.","ipa":"/aɪ juz ə ˈbʊkmɑrk ˌɪnˈstɛd əv ˈfoʊldɪŋ/"},{"id":"school500-07-027","number":27,"speaker":"Cô giáo","en":"Align all rows of desks straight.","vi":"Các con chỉnh cho các hàng bàn ghế thẳng tắp nào.","ipa":"/əˈlaɪn ɔl roʊz əv dɛsks streɪt/"},{"id":"school500-07-028","number":28,"speaker":"Học sinh A","en":"Row one is ready and straight.","vi":"Hàng số một đã ngay ngắn và thẳng hàng rồi ạ.","ipa":"/roʊ wən ɪz ˈrɛdi ənd streɪt/"},{"id":"school500-07-029","number":29,"speaker":"Học sinh B","en":"Row two is also neatly aligned.","vi":"Hàng số hai cũng thẳng tắp rồi thưa cô.","ipa":"/roʊ tu ɪz ˈɔlsoʊ ˈnitli əˈlaɪnd/"},{"id":"school500-07-030","number":30,"speaker":"Cô giáo","en":"Keep the aisle between desks clear.","vi":"Giữ cho lối đi giữa hai dãy bàn thật thông thoáng nhé.","ipa":"/kip ðə aɪəl bɪtˈwin dɛsks klɪr/"},{"id":"school500-07-031","number":31,"speaker":"Học sinh A","en":"Move your school bag off the walkway.","vi":"Cậu cất cặp vào móc kẻo vướng lối đi nha.","ipa":"/muv jʊr skul bæɡ ɔf ðə ˈwɔkˌweɪ/"},{"id":"school500-07-032","number":32,"speaker":"Học sinh B","en":"Yes, safety first in our classroom.","vi":"Đúng rồi, an toàn trong lớp học là trên hết.","ipa":"/jɛs ˈseɪfti fərst ɪn ɑr ˈklæsˌrum/"},{"id":"school500-07-033","number":33,"speaker":"Cô giáo","en":"Place your water bottle in the side pocket.","vi":"Bình nước con để vào ngăn lưới bên cạnh cặp nhé.","ipa":"/pleɪs jʊr ˈwɔtər ˈbɑtəl ɪn ðə saɪd ˈpɑkət/"},{"id":"school500-07-034","number":34,"speaker":"Học sinh A","en":"Close the water bottle cap tightly.","vi":"Nhớ vặn chặt nắp bình nước kẻo đổ ra sách.","ipa":"/kloʊz ðə ˈwɔtər ˈbɑtəl kæp ˈtaɪtli/"},{"id":"school500-07-035","number":35,"speaker":"Học sinh B","en":"My bottle is closed tightly now.","vi":"Bình nước của tớ đã được vặn thật chặt rồi.","ipa":"/maɪ ˈbɑtəl ɪz kloʊzd ˈtaɪtli naʊ/"},{"id":"school500-07-036","number":36,"speaker":"Cô giáo","en":"Clear the corner of the classroom.","vi":"Chúng mình cùng dọn gọn gàng góc lớp học nào.","ipa":"/klɪr ðə ˈkɔrnər əv ðə ˈklæsˌrum/"},{"id":"school500-07-037","number":37,"speaker":"Học sinh A","en":"Stack the extra plastic stools in the corner.","vi":"Chồng các ghế nhựa dự phòng gọn vào góc lớp nhé.","ipa":"/stæk ðə ˈɛkstrə ˈplæstɪk stulz ɪn ðə ˈkɔrnər/"},{"id":"school500-07-038","number":38,"speaker":"Học sinh B","en":"One stool on top of another.","vi":"Chồng từng chiếc ghế khít lên nhau nè.","ipa":"/wən stul ɔn tɔp əv əˈnəðər/"},{"id":"school500-07-039","number":39,"speaker":"Cô giáo","en":"Put the rulers inside your pencil pouch.","vi":"Các con cất thước kẻ vào trong túi đựng đồ nhé.","ipa":"/pʊt ðə ˈrulərz ˌɪnˈsaɪd jʊr ˈpɛnsəl paʊtʃ/"},{"id":"school500-07-040","number":40,"speaker":"Học sinh A","en":"Don't let rulers stick out.","vi":"Đừng để thước kẻ chìa ra ngoài mép bàn.","ipa":"/doʊnt lɛt ˈrulərz stɪk aʊt/"},{"id":"school500-07-041","number":41,"speaker":"Cô giáo","en":"Let's check the classroom bookshelves.","vi":"Cả lớp cùng kiểm tra lại giá sách chung của lớp nào.","ipa":"/lɛts tʃɛk ðə ˈklæsˌrum ˈbʊkˌʃɛlvz/"},{"id":"school500-07-042","number":42,"speaker":"Học sinh A","en":"Storybooks go on the first shelf.","vi":"Sách truyện tranh xếp ở ngăn thứ nhất.","ipa":"/ˈstɔriˌbʊks ɡoʊ ɔn ðə fərst ʃɛlf/"},{"id":"school500-07-043","number":43,"speaker":"Học sinh B","en":"Science magazines go on the second shelf.","vi":"Tạp chí khoa học để ở ngăn thứ hai.","ipa":"/saɪəns ˈmæɡəˌzinz ɡoʊ ɔn ðə ˈsɛkənd ʃɛlf/"},{"id":"school500-07-044","number":44,"speaker":"Học sinh C","en":"All book spines are facing outward.","vi":"Tất cả gáy sách đều quay ra ngoài rất dễ tìm.","ipa":"/ɔl bʊk spaɪnz ər ˈfeɪsɪŋ ˈaʊtwərd/"},{"id":"school500-07-045","number":45,"speaker":"Cô giáo","en":"Wonderful! The bookshelf looks beautiful.","vi":"Tuyệt vời! Giá sách của lớp trông đẹp mắt lắm.","ipa":"/ˈwəndərfəl ðə ˈbʊkˌʃɛlf lʊks ˈbjutəfəl/"},{"id":"school500-07-046","number":46,"speaker":"Học sinh A","en":"Orderly desks help our minds focus.","vi":"Bàn học ngăn nắp giúp tâm trí tập trung hơn.","ipa":"/ˈɔrdərli dɛsks hɛlp ɑr maɪndz ˈfoʊkɪs/"},{"id":"school500-07-047","number":47,"speaker":"Học sinh B","en":"We can find our things in five seconds!","vi":"Chúng mình có thể tìm thấy đồ chỉ trong năm giây!","ipa":"/wi kən faɪnd ɑr θɪŋz ɪn faɪv ˈsɛkəndz/"},{"id":"school500-07-048","number":48,"speaker":"Cô giáo","en":"Give yourselves five stars for tidiness!","vi":"Cô tặng cả lớp năm ngôi sao vì sự ngăn nắp!","ipa":"/ɡɪv ˈjɔrsɛlvz faɪv stɑrz fər ˈtaɪdinəs/"},{"id":"school500-07-049","number":49,"speaker":"Cả lớp","en":"We promise to keep our desks neat every day!","vi":"Chúng em hứa ngày nào cũng giữ bàn học thật gọn gàng!","ipa":"/wi ˈprɑməs tɪ kip ɑr dɛsks nit ˈɛvəri deɪ/"},{"id":"school500-07-050","number":50,"speaker":"Cô giáo","en":"Good habits start from your neat desk.","vi":"Thói quen tốt bắt đầu từ chính chiếc bàn học ngăn nắp.","ipa":"/ɡʊd ˈhæbəts stɑrt frəm jʊr nit dɛsk/"}]},{"number":8,"title":"VỆ SINH TRƯỜNG LỚP VÀ BẢO VỆ MÔI TRƯỜNG","titleEn":"CLEANING CLASS & CAMPUS","sentences":[{"id":"school500-08-001","number":1,"speaker":"Cô giáo","en":"It's time for our classroom cleanup duty!","vi":"Đến giờ trực nhật vệ sinh lớp học rồi các con ơi!","ipa":"/ɪts taɪm fər ɑr ˈklæsˌrum ˈkliˌnəp ˈduti/"},{"id":"school500-08-002","number":2,"speaker":"Cô giáo","en":"Group Two is on cleaning duty today.","vi":"Hôm nay Nhóm Hai đến lượt làm trực nhật nhé.","ipa":"/ɡrup tu ɪz ɔn ˈklinɪŋ ˈduti təˈdeɪ/"},{"id":"school500-08-003","number":3,"speaker":"Học sinh A","en":"I will sweep the classroom floor.","vi":"Tớ sẽ quét sạch sàn lớp học.","ipa":"/aɪ wɪl swip ðə ˈklæsˌrum flɔr/"},{"id":"school500-08-004","number":4,"speaker":"Học sinh B","en":"I will get the dustpan and broom.","vi":"Để tớ đi lấy cây chổi và cái hót rác nhé.","ipa":"/aɪ wɪl ɡɪt ðə ˈdʌstˌpæn ənd brum/"},{"id":"school500-08-005","number":5,"speaker":"Học sinh C","en":"Let me clean the green board.","vi":"Để tớ lau sạch bảng lớp học nhé.","ipa":"/lɛt mi klin ðə ɡrin bɔrd/"},{"id":"school500-08-006","number":6,"speaker":"Cô giáo","en":"Use a damp cloth to wipe the board.","vi":"Con dùng khăn ẩm để lau bảng cho sạch bụi phấn nhé.","ipa":"/juz ə dæmp klɔθ tɪ waɪp ðə bɔrd/"},{"id":"school500-08-007","number":7,"speaker":"Học sinh C","en":"The chalkboard is clean and shiny now.","vi":"Bảng lớp bây giờ đã sạch bóng rồi ạ.","ipa":"/ðə ˈtʃɔkˌbɔrd ɪz klin ənd ˈʃaɪni naʊ/"},{"id":"school500-08-008","number":8,"speaker":"Học sinh D","en":"I will wipe the teacher's desk.","vi":"Tớ sẽ lau bàn giáo viên cho sạch sẽ.","ipa":"/aɪ wɪl waɪp ðə ˈtitʃərz dɛsk/"},{"id":"school500-08-009","number":9,"speaker":"Học sinh A","en":"Pick up the trash on the floor, please.","vi":"Bạn nhặt rác vương trên sàn giúp tớ với nhé.","ipa":"/pɪk əp ðə træʃ ɔn ðə flɔr pliz/"},{"id":"school500-08-010","number":10,"speaker":"Học sinh B","en":"Put the trash into the dustbin.","vi":"Tớ bỏ rác vào thùng rác rồi nè.","ipa":"/pʊt ðə træʃ ˈɪntu ðə ˈdəstbɪn/"},{"id":"school500-08-011","number":11,"speaker":"Cô giáo","en":"Don't forget to empty the trash bin.","vi":"Các con nhớ đổ rác ở thùng rác của lớp nhé.","ipa":"/doʊnt fərˈɡɛt tɪ ˈɛmti ðə træʃ bɪn/"},{"id":"school500-08-012","number":12,"speaker":"Học sinh C","en":"Let's carry the bin to the school waste area.","vi":"Chúng mình cùng mang thùng rác ra khu tập kết của trường nhé.","ipa":"/lɛts ˈkɛri ðə bɪn tɪ ðə skul weɪst ˈɛriə/"},{"id":"school500-08-013","number":13,"speaker":"Cô giáo","en":"Let's water the flower pots at the window.","vi":"Các con tưới nước cho mấy chậu hoa bên cửa sổ nào.","ipa":"/lɛts ˈwɔtər ðə flaʊər pɑts æt ðə ˈwɪndoʊ/"},{"id":"school500-08-014","number":14,"speaker":"Học sinh D","en":"I am watering the green plants.","vi":"Tớ đang tưới nước cho cây xanh đây.","ipa":"/aɪ æm ˈwɔtərɪŋ ðə ɡrin plænts/"},{"id":"school500-08-015","number":15,"speaker":"Cô giáo","en":"Let's keep our school yard clean.","vi":"Chúng mình cùng giữ gìn sân trường thật sạch đẹp nhé.","ipa":"/lɛts kip ɑr skul jɑrd klin/"},{"id":"school500-08-016","number":16,"speaker":"Học sinh A","en":"Do not litter on the playground.","vi":"Tuyệt đối không vứt rác bừa bãi ra sân trường nhé.","ipa":"/du nɑt ˈlɪtər ɔn ðə ˈpleɪˌɡraʊnd/"},{"id":"school500-08-017","number":17,"speaker":"Cô giáo","en":"Wash your hands with soap after cleaning.","vi":"Dọn vệ sinh xong các con nhớ rửa tay bằng xà phòng nhé.","ipa":"/wɑʃ jʊr hænz wɪθ soʊp ˈæftər ˈklinɪŋ/"},{"id":"school500-08-018","number":18,"speaker":"Học sinh B","en":"We are washing our hands cleanly.","vi":"Chúng em đang rửa tay thật sạch sẽ rồi ạ.","ipa":"/wi ər ˈwɑʃɪŋ ɑr hænz ˈklinli/"},{"id":"school500-08-019","number":19,"speaker":"Cô giáo","en":"Good job, our classroom is sparkling clean!","vi":"Làm tốt lắm, lớp học của chúng ta sáng bóng và sạch đẹp rồi!","ipa":"/ɡʊd dʒɑb ɑr ˈklæsˌrum ɪz ˈspɑrkəlɪŋ klin/"},{"id":"school500-08-020","number":20,"speaker":"Cả lớp","en":"Keep our school green, clean, and beautiful!","vi":"Cùng giữ gìn trường lớp xanh, sạch, đẹp!","ipa":"/kip ɑr skul ɡrin klin ənd ˈbjutəfəl/"},{"id":"school500-08-021","number":21,"speaker":"Cô giáo","en":"Open the windows to let fresh air circulate.","vi":"Mở cửa sổ ra cho không khí trong lành lưu thông nào.","ipa":"/ˈoʊpən ðə ˈwɪndoʊz tɪ lɛt frɛʃ ɛr ˈsərkjəˌleɪt/"},{"id":"school500-08-022","number":22,"speaker":"Học sinh A","en":"I am dusting the window sills.","vi":"Tớ đang lau bụi ở gờ cửa sổ đây.","ipa":"/aɪ æm ˈdəstɪŋ ðə ˈwɪndoʊ sɪlz/"},{"id":"school500-08-023","number":23,"speaker":"Học sinh B","en":"Let's wipe the glass with newspaper.","vi":"Chúng mình dùng giấy báo lau kính cho sáng bóng nhé.","ipa":"/lɛts waɪp ðə ɡlæs wɪθ ˈnuzˌpeɪpər/"},{"id":"school500-08-024","number":24,"speaker":"Cô giáo","en":"Be careful when reaching high places.","vi":"Các con cẩn thận khi lau chùi ở chỗ cao nhé.","ipa":"/bi ˈkɛrfəl wɪn ˈritʃɪŋ haɪ ˈpleɪsɪz/"},{"id":"school500-08-025","number":25,"speaker":"Học sinh C","en":"Do not write or draw on the walls.","vi":"Tuyệt đối không viết vẽ bậy lên tường lớp học.","ipa":"/du nɑt raɪt ər drɔ ɔn ðə wɔlz/"},{"id":"school500-08-026","number":26,"speaker":"Học sinh D","en":"Our classroom walls must stay white and clean.","vi":"Tường lớp học của chúng mình phải luôn trắng sạch.","ipa":"/ɑr ˈklæsˌrum wɔlz məst steɪ waɪt ənd klin/"},{"id":"school500-08-027","number":27,"speaker":"Cô giáo","en":"Sort recyclable waste into the blue bin.","vi":"Các con phân loại rác tái chế bỏ vào thùng màu xanh nhé.","ipa":"/sɔrt riˈsaɪkləbəl weɪst ˈɪntu ðə blu bɪn/"},{"id":"school500-08-028","number":28,"speaker":"Học sinh A","en":"Paper and cardboard go into the recycling bin.","vi":"Giấy vụn và bìa các tông bỏ vào thùng tái chế.","ipa":"/ˈpeɪpər ənd ˈkɑrdˌbɔrd ɡoʊ ˈɪntu ðə riˈsaɪkəlɪŋ bɪn/"},{"id":"school500-08-029","number":29,"speaker":"Học sinh B","en":"Fruit peels go into the organic bin.","vi":"Vỏ hoa quả thì bỏ vào thùng rác hữu cơ.","ipa":"/frut pilz ɡoʊ ˈɪntu ðə ɔrˈɡænɪk bɪn/"},{"id":"school500-08-030","number":30,"speaker":"Cô giáo","en":"Turn off lights and fans before leaving.","vi":"Các con nhớ tắt điện và quạt trước khi ra khỏi phòng nhé.","ipa":"/tərn ɔf laɪts ənd fænz ˌbiˈfɔr ˈlivɪŋ/"},{"id":"school500-08-031","number":31,"speaker":"Học sinh C","en":"Saving energy protects our planet.","vi":"Tiết kiệm điện năng là bảo vệ hành tinh của chúng ta.","ipa":"/ˈseɪvɪŋ ˈɛnərdʒi prəˈtɛkts ɑr ˈplænət/"},{"id":"school500-08-032","number":32,"speaker":"Học sinh D","en":"I just turned off the ceiling fan.","vi":"Tớ vừa bấm tắt quạt trần rồi này.","ipa":"/aɪ dʒɪst tərnd ɔf ðə ˈsilɪŋ fæn/"},{"id":"school500-08-033","number":33,"speaker":"Cô giáo","en":"Turn off the water tap tightly in the restroom.","vi":"Nhớ vặn khóa chặt vòi nước trong nhà vệ sinh nhé.","ipa":"/tərn ɔf ðə ˈwɔtər tæp ˈtaɪtli ɪn ðə ˈrɛˌstrum/"},{"id":"school500-08-034","number":34,"speaker":"Học sinh A","en":"Every drop of clean water is precious.","vi":"Từng giọt nước sạch đều vô cùng quý giá.","ipa":"/ˈɛvəri drɔp əv klin ˈwɔtər ɪz ˈprɛʃəs/"},{"id":"school500-08-035","number":35,"speaker":"Học sinh B","en":"I made sure no tap is leaking.","vi":"Tớ đã kiểm tra chắc chắn không có vòi nào bị rò rỉ nước.","ipa":"/aɪ meɪd ʃʊr noʊ tæp ɪz ˈlikɪŋ/"},{"id":"school500-08-036","number":36,"speaker":"Cô giáo","en":"Let's pick up dry leaves under the banyan tree.","vi":"Chúng mình cùng nhặt lá khô dưới gốc cây bàng nào.","ipa":"/lɛts pɪk əp draɪ livz ˈəndər ðə ˈbænjən tri/"},{"id":"school500-08-037","number":37,"speaker":"Học sinh A","en":"The school yard has so many golden leaves.","vi":"Sân trường có rất nhiều lá bàng vàng rụng.","ipa":"/ðə skul jɑrd həz soʊ ˈmɛni ˈɡoʊldən livz/"},{"id":"school500-08-038","number":38,"speaker":"Học sinh B","en":"Put all dry leaves into the compost pit.","vi":"Gom hết lá khô đổ vào hố ủ phân hữu cơ nhé.","ipa":"/pʊt ɔl draɪ livz ˈɪntu ðə ˈkɑmpoʊst pɪt/"},{"id":"school500-08-039","number":39,"speaker":"Học sinh C","en":"Dry leaves make good fertilizer for trees.","vi":"Lá cây khô sẽ làm thành phân bón tốt cho cây.","ipa":"/draɪ livz meɪk ɡʊd ˈfərtəˌlaɪzər fər triz/"},{"id":"school500-08-040","number":40,"speaker":"Cô giáo","en":"Plant a new flower seedling today.","vi":"Hôm nay lớp mình cùng trồng một mầm hoa mới nhé.","ipa":"/plænt ə nu flaʊər ˈsidlɪŋ təˈdeɪ/"},{"id":"school500-08-041","number":41,"speaker":"Học sinh D","en":"I will dig a small hole in the soil.","vi":"Tớ sẽ xới một hốc đất nhỏ màu mỡ.","ipa":"/aɪ wɪl dɪɡ ə smɔl hoʊl ɪn ðə sɔɪl/"},{"id":"school500-08-042","number":42,"speaker":"Học sinh A","en":"Gently place the plant roots in.","vi":"Nhẹ nhàng đặt bộ rễ của cây non vào nhé.","ipa":"/ˈdʒɛntli pleɪs ðə plænt ruts ɪn/"},{"id":"school500-08-043","number":43,"speaker":"Học sinh B","en":"Water it with a sprinkle of water.","vi":"Tưới nhẹ một ít nước mát cho mầm cây mới trồng.","ipa":"/ˈwɔtər ɪt wɪθ ə ˈsprɪŋkəl əv ˈwɔtər/"},{"id":"school500-08-044","number":44,"speaker":"Cô giáo","en":"Watch it grow every day with love.","vi":"Mỗi ngày chúng mình cùng chăm sóc cây lớn lên bằng tình yêu thương.","ipa":"/wɔtʃ ɪt ɡroʊ ˈɛvəri deɪ wɪθ ləv/"},{"id":"school500-08-045","number":45,"speaker":"Học sinh C","en":"Put brooms and mops neatly in the back.","vi":"Xếp chổi và cây lau nhà gọn gàng phía sau lớp.","ipa":"/pʊt brumz ənd mɑps ˈnitli ɪn ðə bæk/"},{"id":"school500-08-046","number":46,"speaker":"Học sinh D","en":"Wash the cleaning cloth and hang it up.","vi":"Giặt sạch giẻ lau rồi phơi lên dây cho khô nhé.","ipa":"/wɑʃ ðə ˈklinɪŋ klɔθ ənd hæŋ ɪt əp/"},{"id":"school500-08-047","number":47,"speaker":"Cô giáo","en":"Clean environment brings good health and joy.","vi":"Môi trường trong lành mang lại sức khỏe và niềm vui.","ipa":"/klin ɪnˈvaɪrənmənt brɪŋz ɡʊd hɛlθ ənd dʒɔɪ/"},{"id":"school500-08-048","number":48,"speaker":"Học sinh A","en":"We love our fresh mountain school!","vi":"Chúng em yêu mái trường ngát xanh giữa đại ngàn!","ipa":"/wi ləv ɑr frɛʃ ˈmaʊntən skul/"},{"id":"school500-08-049","number":49,"speaker":"Cô giáo","en":"Thank you for being environmentally conscious.","vi":"Cô cảm ơn các con vì luôn có ý thức bảo vệ môi trường.","ipa":"/θæŋk ju fər biɪŋ ɪnˌvaɪrənˈmɛnəli ˈkɑnʃəs/"},{"id":"school500-08-050","number":50,"speaker":"Cả lớp","en":"Together we build a happy green school!","vi":"Cùng nhau chúng ta xây dựng ngôi trường xanh hạnh phúc!","ipa":"/təˈɡɛðər wi bɪld ə ˈhæpi ɡrin skul/"}]},{"number":9,"title":"GIAO TIẾP TRONG GIỜ ĂN BÁN TRÚ","titleEn":"BOARDING LUNCH TIME","sentences":[{"id":"school500-09-001","number":1,"speaker":"Cô giáo","en":"It's lunchtime! Let's wash our hands.","vi":"Đến giờ ăn trưa rồi! Chúng mình cùng đi rửa tay nào.","ipa":"/ɪts ˈləntʃˌtaɪm lɛts wɑʃ ɑr hænz/"},{"id":"school500-09-002","number":2,"speaker":"Cô giáo","en":"Line up politely, please.","vi":"Các con hãy xếp hàng ngay ngắn nhé.","ipa":"/laɪn əp pəˈlaɪtli pliz/"},{"id":"school500-09-003","number":3,"speaker":"Học sinh","en":"Yes, we are lining up.","vi":"Vâng ạ, chúng em đang xếp hàng rồi ạ.","ipa":"/jɛs wi ər ˈlaɪnɪŋ əp/"},{"id":"school500-09-004","number":4,"speaker":"Cô giáo","en":"Please take your food tray and spoon.","vi":"Các con hãy lấy khay ăn và thìa của mình nào.","ipa":"/pliz teɪk jʊr fud treɪ ənd spun/"},{"id":"school500-09-005","number":5,"speaker":"Học sinh A","en":"Today's food smells so good!","vi":"Cơm trưa hôm nay thơm ngon quá!","ipa":"/ˈtudeɪz fud smɛlz soʊ ɡʊd/"},{"id":"school500-09-006","number":6,"speaker":"Cô giáo","en":"Sit at your table nicely, everyone.","vi":"Các con ngồi vào bàn ăn thật ngay ngắn nào.","ipa":"/sɪt æt jʊr ˈteɪbəl ˈnaɪsli ˈɛvriˌwən/"},{"id":"school500-09-007","number":7,"speaker":"Học sinh","en":"Enjoy your lunch, teacher and friends!","vi":"Mời cô và các bạn cùng ăn cơm trưa ạ!","ipa":"/ˌɛnˈdʒɔɪ jʊr ləntʃ ˈtitʃər ənd frɛndz/"},{"id":"school500-09-008","number":8,"speaker":"Cô giáo","en":"Enjoy your lunch, children!","vi":"Cô mời các con ăn cơm ngon miệng nhé!","ipa":"/ˌɛnˈdʒɔɪ jʊr ləntʃ ˈtʃɪldrən/"},{"id":"school500-09-009","number":9,"speaker":"Học sinh A","en":"Can you pass me the water cup?","vi":"Bạn chuyền giúp mình cốc nước được không?","ipa":"/kən ju pæs mi ðə ˈwɔtər kəp/"},{"id":"school500-09-010","number":10,"speaker":"Học sinh B","en":"Here it is. Be careful!","vi":"Cốc nước đây nè, cẩn thận kẻo đổ nhé!","ipa":"/hir ɪt ɪz bi ˈkɛrfəl/"},{"id":"school500-09-011","number":11,"speaker":"Học sinh A","en":"I like this vegetable soup.","vi":"Tớ rất thích món canh rau này.","ipa":"/aɪ laɪk ðɪs ˈvɛdʒtəbəl sup/"},{"id":"school500-09-012","number":12,"speaker":"Học sinh B","en":"The chicken is very delicious.","vi":"Món thịt gà này ngon lắm đấy.","ipa":"/ðə ˈtʃɪkən ɪz ˈvɛri dɪˈlɪʃəs/"},{"id":"school500-09-013","number":13,"speaker":"Cô giáo","en":"Eat slowly and don't talk with food in your mouth.","vi":"Các con ăn chậm nhai kỹ và không nói chuyện khi đang nhai nhé.","ipa":"/it sˈloʊli ənd doʊnt tɔk wɪθ fud ɪn jʊr maʊθ/"},{"id":"school500-09-014","number":14,"speaker":"Học sinh A","en":"May I have some more rice, please?","vi":"Cô cho con xin thêm một ít cơm được không ạ?","ipa":"/meɪ aɪ hæv səm mɔr raɪs pliz/"},{"id":"school500-09-015","number":15,"speaker":"Cô giáo","en":"Sure, eat well to grow strong!","vi":"Được chứ, con ăn thật no để khỏe mạnh nhé!","ipa":"/ʃʊr it wɛl tɪ ɡroʊ strɔŋ/"},{"id":"school500-09-016","number":16,"speaker":"Học sinh B","en":"I have finished all my food!","vi":"Em đã ăn hết sạch phần cơm của mình rồi ạ!","ipa":"/aɪ hæv ˈfɪnɪʃt ɔl maɪ fud/"},{"id":"school500-09-017","number":17,"speaker":"Cô giáo","en":"Good job! You ate all your food.","vi":"Giỏi lắm! Con không bỏ thừa thức ăn.","ipa":"/ɡʊd dʒɑb ju eɪt ɔl jʊr fud/"},{"id":"school500-09-018","number":18,"speaker":"Cô giáo","en":"Put your empty tray on the rack.","vi":"Các con mang khay ăn để gọn gàng lên giá nhé.","ipa":"/pʊt jʊr ˈɛmti treɪ ɔn ðə ræk/"},{"id":"school500-09-019","number":19,"speaker":"Học sinh A","en":"Let's wipe the table clean.","vi":"Chúng mình cùng lau bàn cho sạch sẽ nhé.","ipa":"/lɛts waɪp ðə ˈteɪbəl klin/"},{"id":"school500-09-020","number":20,"speaker":"Cô giáo","en":"Rinse your mouth and get ready for nap time.","vi":"Các con súc miệng sạch sẽ rồi chuẩn bị vào giờ ngủ trưa nhé.","ipa":"/rɪns jʊr maʊθ ənd ɡɪt ˈrɛdi fər næp taɪm/"},{"id":"school500-09-021","number":21,"speaker":"Cô giáo","en":"Remember the six steps of handwashing.","vi":"Các con nhớ rửa tay đúng sáu bước bằng xà phòng nhé.","ipa":"/rɪˈmɛmbər ðə sɪks stɛps əv ˈhændˌwɑʃɪŋ/"},{"id":"school500-09-022","number":22,"speaker":"Học sinh A","en":"Wash between fingers and fingernails.","vi":"Rửa sạch các kẽ ngón tay và móng tay.","ipa":"/wɑʃ bɪtˈwin ˈfɪŋɡərz ənd ˈfɪŋɡərˌneɪlz/"},{"id":"school500-09-023","number":23,"speaker":"Học sinh B","en":"Dry your hands with a clean towel.","vi":"Lau khô tay bằng khăn sạch trước khi vào bàn ăn.","ipa":"/draɪ jʊr hænz wɪθ ə klin taʊəl/"},{"id":"school500-09-024","number":24,"speaker":"Cô giáo","en":"Don't push in the dining queue.","vi":"Khi xếp hàng lấy cơm các con không xô đẩy nhau nhé.","ipa":"/doʊnt pʊʃ ɪn ðə ˈdaɪnɪŋ kju/"},{"id":"school500-09-025","number":25,"speaker":"Học sinh A","en":"I am standing patiently behind you.","vi":"Tớ đang đứng kiên nhẫn xếp hàng sau bạn này.","ipa":"/aɪ æm ˈstændɪŋ ˈpeɪʃəntli bɪˈhaɪnd ju/"},{"id":"school500-09-026","number":26,"speaker":"Cô giáo","en":"Today we have steamed pumpkin and eggs.","vi":"Hôm nay thực đơn có món bí đỏ hấp và trứng đúc thịt.","ipa":"/təˈdeɪ wi hæv stimd ˈpəmpkɪn ənd ɛɡz/"},{"id":"school500-09-027","number":27,"speaker":"Học sinh A","en":"Pumpkin is very sweet and nutritious.","vi":"Bí đỏ ngọt bùi và rất bổ dưỡng cho mắt.","ipa":"/ˈpəmpkɪn ɪz ˈvɛri swit ənd nuˈtrɪʃəs/"},{"id":"school500-09-028","number":28,"speaker":"Học sinh B","en":"I love eating green vegetables.","vi":"Tớ rất thích ăn thật nhiều rau xanh.","ipa":"/aɪ ləv ˈitɪŋ ɡrin ˈvɛdʒtəbəlz/"},{"id":"school500-09-029","number":29,"speaker":"Cô giáo","en":"Eat vegetables to get vitamins.","vi":"Ăn nhiều rau xanh để bổ sung vitamin cho cơ thể con nhé.","ipa":"/it ˈvɛdʒtəbəlz tɪ ɡɪt ˈvaɪtəmənz/"},{"id":"school500-09-030","number":30,"speaker":"Học sinh A","en":"Be careful, the soup bowl is warm.","vi":"Cẩn thận nhé, bát canh này còn đang ấm đấy.","ipa":"/bi ˈkɛrfəl ðə sup boʊl ɪz wɔrm/"},{"id":"school500-09-031","number":31,"speaker":"Học sinh B","en":"Hold the bowl with both hands.","vi":"Hãy bưng bát bằng cả hai bàn tay cho chắc chắn.","ipa":"/hoʊld ðə boʊl wɪθ boʊθ hænz/"},{"id":"school500-09-032","number":32,"speaker":"Cô giáo","en":"Don't drop rice grains on the floor.","vi":"Các con ăn khéo léo đừng để cơm rơi vãi xuống sàn nhé.","ipa":"/doʊnt drɔp raɪs ɡreɪnz ɔn ðə flɔr/"},{"id":"school500-09-033","number":33,"speaker":"Học sinh A","en":"Every grain of rice took hard work to grow.","vi":"Từng hạt gạo đều được làm ra từ bao công sức vất vả.","ipa":"/ˈɛvəri ɡreɪn əv raɪs tʊk hɑrd wərk tɪ ɡroʊ/"},{"id":"school500-09-034","number":34,"speaker":"Học sinh B","en":"I will cherish every bit of food.","vi":"Tớ sẽ trân trọng từng hạt cơm mình ăn.","ipa":"/aɪ wɪl ˈtʃɛrɪʃ ˈɛvəri bɪt əv fud/"},{"id":"school500-09-035","number":35,"speaker":"Học sinh A","en":"Can you give me a paper napkin?","vi":"Bạn lấy giúp mình một tờ giấy ăn được không?","ipa":"/kən ju ɡɪv mi ə ˈpeɪpər ˈnæpkɪn/"},{"id":"school500-09-036","number":36,"speaker":"Học sinh B","en":"Here is a clean napkin for you.","vi":"Tờ giấy ăn sạch của bạn đây nhé.","ipa":"/hir ɪz ə klin ˈnæpkɪn fər ju/"},{"id":"school500-09-037","number":37,"speaker":"Cô giáo","en":"Drink water slowly after finishing lunch.","vi":"Ăn xong các con uống từng ngụm nước nhỏ thôi nhé.","ipa":"/drɪŋk ˈwɔtər sˈloʊli ˈæftər ˈfɪnɪʃɪŋ ləntʃ/"},{"id":"school500-09-038","number":38,"speaker":"Học sinh A","en":"Place spoons in the cutlery basin.","vi":"Để thìa vào đúng chậu rửa dụng cụ nhé.","ipa":"/pleɪs spunz ɪn ðə ˈkətləri ˈbeɪsən/"},{"id":"school500-09-039","number":39,"speaker":"Học sinh B","en":"Stack food trays in a straight pile.","vi":"Chồng các khay ăn thành một chồng thật ngay ngắn.","ipa":"/stæk fud treɪz ɪn ə streɪt paɪl/"},{"id":"school500-09-040","number":40,"speaker":"Cô giáo","en":"Check around your seat for fallen food.","vi":"Con kiểm tra quanh chỗ ngồi xem có vết bẩn nào rơi không.","ipa":"/tʃɛk əraʊnd jʊr sit fər ˈfɑlən fud/"},{"id":"school500-09-041","number":41,"speaker":"Học sinh A","en":"I picked up the dropped tissue.","vi":"Tớ vừa nhặt mẩu giấy ăn bị rơi bỏ vào sọt rác rồi.","ipa":"/aɪ pɪkt əp ðə drɑpt ˈtɪʃu/"},{"id":"school500-09-042","number":42,"speaker":"Cô giáo","en":"Brush your teeth or rinse with salt water.","vi":"Các con đánh răng hoặc súc miệng bằng nước muối ấm nhé.","ipa":"/brəʃ jʊr tiθ ər rɪns wɪθ sɔlt ˈwɔtər/"},{"id":"school500-09-043","number":43,"speaker":"Học sinh B","en":"My teeth feel so fresh and clean.","vi":"Hàm răng của tớ bây giờ sạch sẽ và thơm tho rồi.","ipa":"/maɪ tiθ fil soʊ frɛʃ ənd klin/"},{"id":"school500-09-044","number":44,"speaker":"Cô giáo","en":"Take your pillow and unfold your sleeping mat.","vi":"Các con lấy gối và trải chiếu chuẩn bị ngủ trưa nào.","ipa":"/teɪk jʊr ˈpɪloʊ ənd ənˈfoʊld jʊr sˈlipɪŋ mæt/"},{"id":"school500-09-045","number":45,"speaker":"Học sinh A","en":"Let me help you unfold this bamboo mat.","vi":"Để tớ phụ bạn trải chiếc chiếu trúc này ra nhé.","ipa":"/lɛt mi hɛlp ju ənˈfoʊld ðɪs bæmˈbu mæt/"},{"id":"school500-09-046","number":46,"speaker":"Cô giáo","en":"Pull the sleeping curtains down.","vi":"Kéo rèm cửa sổ xuống cho phòng ngủ dịu mát nhé.","ipa":"/pʊl ðə sˈlipɪŋ ˈkərtənz daʊn/"},{"id":"school500-09-047","number":47,"speaker":"Cô giáo","en":"Sleep quietly, no whispering now.","vi":"Cả lớp ngủ thật ngoan, không thì thầm nói chuyện nữa nào.","ipa":"/slip kˈwaɪətli noʊ ˈwɪspərɪŋ naʊ/"},{"id":"school500-09-048","number":48,"speaker":"Học sinh A","en":"Good afternoon nap, teacher and friends.","vi":"Chúc cô và các bạn có một giấc ngủ trưa thật ngon.","ipa":"/ɡʊd ˌæftərˈnun næp ˈtitʃər ənd frɛndz/"},{"id":"school500-09-049","number":49,"speaker":"Cô giáo","en":"Sleep well to have energy for the afternoon.","vi":"Ngủ ngon giấc để chiều nay học tập thật khỏe khoắn nhé.","ipa":"/slip wɛl tɪ hæv ˈɛnərdʒi fər ðə ˌæftərˈnun/"},{"id":"school500-09-050","number":50,"speaker":"Cả lớp","en":"Sweet dreams, everyone!","vi":"Chúc cả phòng ngủ trưa ngon giấc!","ipa":"/swit drimz ˈɛvriˌwən/"}]},{"number":10,"title":"GIỜ RA CHƠI VÀ TẠM BIỆT RA VỀ","titleEn":"BREAK TIME & FAREWELL","sentences":[{"id":"school500-10-001","number":1,"speaker":"Cô giáo","en":"It's break time now!","vi":"Đến giờ ra chơi rồi các con ơi!","ipa":"/ɪts breɪk taɪm naʊ/"},{"id":"school500-10-002","number":2,"speaker":"Học sinh","en":"Yay! Break time!","vi":"Hoan hô! Đến giờ chơi rồi!","ipa":"/jeɪ breɪk taɪm/"},{"id":"school500-10-003","number":3,"speaker":"Cô giáo","en":"Put away your books, please.","vi":"Các con cất sách vở gọn gàng vào ngăn bàn nhé.","ipa":"/pʊt əˈweɪ jʊr bʊks pliz/"},{"id":"school500-10-004","number":4,"speaker":"Cô giáo","en":"Don't run in the classroom.","vi":"Các con không chạy nhảy trong lớp học nhé.","ipa":"/doʊnt rən ɪn ðə ˈklæsˌrum/"},{"id":"school500-10-005","number":5,"speaker":"Cô giáo","en":"Walk slowly and stay safe.","vi":"Các con đi lại chậm rãi và giữ an toàn nhé.","ipa":"/wɔk sˈloʊli ənd steɪ seɪf/"},{"id":"school500-10-006","number":6,"speaker":"Học sinh A","en":"Let's go outside to play!","vi":"Chúng mình cùng ra sân chơi thôi!","ipa":"/lɛts ɡoʊ ˈaʊtˈsaɪd tɪ pleɪ/"},{"id":"school500-10-007","number":7,"speaker":"Học sinh B","en":"Yes, let's go!","vi":"Được, chúng mình đi nào!","ipa":"/jɛs lɛts ɡoʊ/"},{"id":"school500-10-008","number":8,"speaker":"Học sinh A","en":"Do you want to play shuttlecock?","vi":"Bạn có muốn chơi đá cầu cùng tớ không?","ipa":"/du ju wɔnt tɪ pleɪ ˈʃʌtəlˌkɑk/"},{"id":"school500-10-009","number":9,"speaker":"Học sinh B","en":"Yes, I love it!","vi":"Có chứ, tớ rất thích!","ipa":"/jɛs aɪ ləv ɪt/"},{"id":"school500-10-010","number":10,"speaker":"Học sinh A","en":"Do you want to jump rope?","vi":"Bạn có muốn chơi nhảy dây không?","ipa":"/du ju wɔnt tɪ dʒəmp roʊp/"},{"id":"school500-10-011","number":11,"speaker":"Học sinh B","en":"Sure, let's play together.","vi":"Chắc chắn rồi, cùng chơi nào.","ipa":"/ʃʊr lɛts pleɪ təˈɡɛðər/"},{"id":"school500-10-012","number":12,"speaker":"Cô giáo","en":"The bell is ringing, go back to class!","vi":"Trống báo hết giờ rồi, các con vào lớp thôi!","ipa":"/ðə bɛl ɪz ˈrɪŋɪŋ ɡoʊ bæk tɪ klæs/"},{"id":"school500-10-013","number":13,"speaker":"Học sinh","en":"Yes, let's go back inside.","vi":"Vâng ạ, chúng mình vào lớp thôi.","ipa":"/jɛs lɛts ɡoʊ bæk ˌɪnˈsaɪd/"},{"id":"school500-10-014","number":14,"speaker":"Cô giáo","en":"Our lesson ends here today.","vi":"Tiết học của chúng ta hôm nay kết thúc ở đây.","ipa":"/ɑr ˈlɛsən ɛndz hir təˈdeɪ/"},{"id":"school500-10-015","number":15,"speaker":"Cô giáo","en":"You all did a great job today!","vi":"Hôm nay cả lớp học rất giỏi và ngoan!","ipa":"/ju ɔl dɪd ə ɡreɪt dʒɑb təˈdeɪ/"},{"id":"school500-10-016","number":16,"speaker":"Cô giáo","en":"Remember to do your homework.","vi":"Các con nhớ hoàn thành bài tập về nhà nhé.","ipa":"/rɪˈmɛmbər tɪ du jʊr ˈhoʊmˌwərk/"},{"id":"school500-10-017","number":17,"speaker":"Cô giáo","en":"Pack your school bags, everyone.","vi":"Các con thu dọn cặp sách gọn gàng nào.","ipa":"/pæk jʊr skul bæɡz ˈɛvriˌwən/"},{"id":"school500-10-018","number":18,"speaker":"Cô giáo","en":"Goodbye, class! See you tomorrow!","vi":"Tạm biệt cả lớp! Hẹn gặp lại các con vào ngày mai nhé!","ipa":"/ˌɡʊdˈbaɪ klæs si ju təˈmɑˌroʊ/"},{"id":"school500-10-019","number":19,"speaker":"Học sinh","en":"Goodbye, teacher! See you again!","vi":"Chúng em chào cô ạ! Hẹn gặp lại cô!","ipa":"/ˌɡʊdˈbaɪ ˈtitʃər si ju əˈɡɛn/"},{"id":"school500-10-020","number":20,"speaker":"Học sinh","en":"Have a nice day, teacher!","vi":"Chúc cô một ngày thật vui vẻ ạ!","ipa":"/hæv ə nis deɪ ˈtitʃər/"},{"id":"school500-10-021","number":21,"speaker":"Học sinh A","en":"Do you want to play hide and seek?","vi":"Bạn có muốn chơi trốn tìm cùng chúng tớ không?","ipa":"/du ju wɔnt tɪ pleɪ haɪd ənd sik/"},{"id":"school500-10-022","number":22,"speaker":"Học sinh B","en":"Count to ten while we hide!","vi":"Cậu đếm từ một đến mười trong lúc chúng tớ đi trốn nhé!","ipa":"/kaʊnt tɪ tɛn waɪl wi haɪd/"},{"id":"school500-10-023","number":23,"speaker":"Học sinh A","en":"One, two, three... ready or not, here I come!","vi":"Một, hai, ba... trốn xong chưa, tớ đi tìm đây!","ipa":"/wən tu θri ˈrɛdi ər nɑt hir aɪ kəm/"},{"id":"school500-10-024","number":24,"speaker":"Học sinh C","en":"Do not run on the wet grass.","vi":"Đừng chạy trên cỏ ướt kẻo trơn trượt ngã nhé.","ipa":"/du nɑt rən ɔn ðə wɛt ɡræs/"},{"id":"school500-10-025","number":25,"speaker":"Học sinh D","en":"Let's play under the shade of the mango tree.","vi":"Chúng mình ra chơi dưới bóng mát của cây xoài đi.","ipa":"/lɛts pleɪ ˈəndər ðə ʃeɪd əv ðə ˈmæŋɡoʊ tri/"},{"id":"school500-10-026","number":26,"speaker":"Học sinh A","en":"Do you want to play chess?","vi":"Cậu có muốn chơi cờ vua với tớ không?","ipa":"/du ju wɔnt tɪ pleɪ tʃɛs/"},{"id":"school500-10-027","number":27,"speaker":"Học sinh B","en":"Yes, chess trains our logical thinking.","vi":"Có chứ, cờ vua giúp rèn luyện tư duy logic rất tốt.","ipa":"/jɛs tʃɛs treɪnz ɑr ˈlɑdʒɪkəl ˈθɪŋkɪŋ/"},{"id":"school500-10-028","number":28,"speaker":"Học sinh A","en":"Your move! Think carefully.","vi":"Đến lượt cậu đi đấy! Suy nghĩ thật kỹ nha.","ipa":"/jʊr muv θɪŋk ˈkɛrfəli/"},{"id":"school500-10-029","number":29,"speaker":"Học sinh B","en":"I will move my knight here.","vi":"Tớ sẽ di chuyển quân mã tới ô này.","ipa":"/aɪ wɪl muv maɪ naɪt hir/"},{"id":"school500-10-030","number":30,"speaker":"Cô giáo","en":"Play nicely, do not push your friends.","vi":"Các con chơi vui vẻ đoàn kết, không xô đẩy bạn nhé.","ipa":"/pleɪ ˈnaɪsli du nɑt pʊʃ jʊr frɛndz/"},{"id":"school500-10-031","number":31,"speaker":"Học sinh A","en":"Drink some water to stay hydrated.","vi":"Uống chút nước mát cho đỡ khát nào bạn ơi.","ipa":"/drɪŋk səm ˈwɔtər tɪ steɪ ˈhaɪˌdreɪtəd/"},{"id":"school500-10-032","number":32,"speaker":"Học sinh B","en":"Ah, fresh mountain water is so cool!","vi":"A, nước mát đầu nguồn thật sảng khoái!","ipa":"/ɑ frɛʃ ˈmaʊntən ˈwɔtər ɪz soʊ kul/"},{"id":"school500-10-033","number":33,"speaker":"Cô giáo","en":"The afternoon bell has rung.","vi":"Tiếng trống trường buổi chiều đã điểm rồi.","ipa":"/ðə ˌæftərˈnun bɛl həz rəŋ/"},{"id":"school500-10-034","number":34,"speaker":"Học sinh A","en":"Time to gather our books and bags.","vi":"Đến lúc thu dọn sách vở và cặp sách rồi.","ipa":"/taɪm tɪ ˈɡæðər ɑr bʊks ənd bæɡz/"},{"id":"school500-10-035","number":35,"speaker":"Cô giáo","en":"Put your notebooks into your backpack.","vi":"Các con cất cẩn thận vở ghi vào ba lô nhé.","ipa":"/pʊt jʊr ˈnoʊtˌbʊks ˈɪntu jʊr ˈbækˌpæk/"},{"id":"school500-10-036","number":36,"speaker":"Học sinh B","en":"Check your pencil box before zipping your bag.","vi":"Kiểm tra kỹ hộp bút trước khi kéo khóa ba lô lại.","ipa":"/tʃɛk jʊr ˈpɛnsəl bɑks ˌbiˈfɔr ˈzɪpɪŋ jʊr bæɡ/"},{"id":"school500-10-037","number":37,"speaker":"Cô giáo","en":"Don't leave jackets or hats behind.","vi":"Các con kiểm tra đừng để quên áo khoác hay mũ nón nhé.","ipa":"/doʊnt liv ˈdʒækɪts ər hæts bɪˈhaɪnd/"},{"id":"school500-10-038","number":38,"speaker":"Học sinh A","en":"I have my warm scarf and jacket.","vi":"Tớ đã đeo khăn ấm và mặc áo khoác rồi này.","ipa":"/aɪ hæv maɪ wɔrm skɑrf ənd ˈdʒækɪt/"},{"id":"school500-10-039","number":39,"speaker":"Cô giáo","en":"Line up at the classroom door.","vi":"Cả lớp xếp hàng thẳng trước cửa lớp để ra về nào.","ipa":"/laɪn əp æt ðə ˈklæsˌrum dɔr/"},{"id":"school500-10-040","number":40,"speaker":"Học sinh B","en":"We are walking quietly in two lines.","vi":"Chúng em đang đi trật tự thành hai hàng đây ạ.","ipa":"/wi ər ˈwɔkɪŋ kˈwaɪətli ɪn tu laɪnz/"},{"id":"school500-10-041","number":41,"speaker":"Cô giáo","en":"Walk on the right side of the road.","vi":"Các con nhớ đi nép sát lề đường bên phải nhé.","ipa":"/wɔk ɔn ðə raɪt saɪd əv ðə roʊd/"},{"id":"school500-10-042","number":42,"speaker":"Học sinh A","en":"Look left and right before crossing the road.","vi":"Nhớ nhìn trái nhìn phải cẩn thận trước khi qua đường.","ipa":"/lʊk lɛft ənd raɪt ˌbiˈfɔr ˈkrɔsɪŋ ðə roʊd/"},{"id":"school500-10-043","number":43,"speaker":"Học sinh B","en":"Hold your parent's hand tightly.","vi":"Nhớ nắm thật chặt tay bố mẹ khi ra về nha.","ipa":"/hoʊld jʊr ˈpɛrənts hænd ˈtaɪtli/"},{"id":"school500-10-044","number":44,"speaker":"Học sinh A","en":"My father is waiting at the school gate.","vi":"Bố tớ đang đợi đón tớ ở cổng trường kìa.","ipa":"/maɪ ˈfɑðər ɪz ˈweɪtɪŋ æt ðə skul ɡeɪt/"},{"id":"school500-10-045","number":45,"speaker":"Học sinh B","en":"My sister walks home with me.","vi":"Chị gái tớ cùng đi bộ về nhà với tớ.","ipa":"/maɪ ˈsɪstər wɔks hoʊm wɪθ mi/"},{"id":"school500-10-046","number":46,"speaker":"Cô giáo","en":"Have a safe trip home, children!","vi":"Chúc các con về nhà bình an và ngoan ngoãn nhé!","ipa":"/hæv ə seɪf trɪp hoʊm ˈtʃɪldrən/"},{"id":"school500-10-047","number":47,"speaker":"Học sinh","en":"Thank you, teacher! See you tomorrow morning!","vi":"Chúng em cảm ơn cô ạ! Hẹn gặp lại cô vào sáng mai!","ipa":"/θæŋk ju ˈtitʃər si ju təˈmɑˌroʊ ˈmɔrnɪŋ/"},{"id":"school500-10-048","number":48,"speaker":"Cô giáo","en":"Help your parents with chores tonight.","vi":"Tối về nhớ giúp đỡ bố mẹ việc nhà nhé các con.","ipa":"/hɛlp jʊr ˈpɛrənts wɪθ tʃɔrz təˈnaɪt/"},{"id":"school500-10-049","number":49,"speaker":"Học sinh A","en":"I will review my English and Math lessons.","vi":"Tối nay tớ sẽ ôn lại bài học Tiếng Anh và Toán.","ipa":"/aɪ wɪl ˌrivˈju maɪ ˈɪŋlɪʃ ənd mæθ ˈlɛsənz/"},{"id":"school500-10-050","number":50,"speaker":"Cả lớp","en":"Goodbye school! We had a wonderful day!","vi":"Tạm biệt trường lớp thân yêu! Hôm nay là một ngày thật tuyệt vời!","ipa":"/ˌɡʊdˈbaɪ skul wi hæd ə ˈwəndərfəl deɪ/"}]}];
// Luyện nói 500 câu: dùng lại bộ điều khiển micro và sổ sao của ứng dụng gốc.
const sp500Lessons=SP500_TOPICS.flatMap((topic,ti)=>topic.sentences.map((row,ri)=>{
 const previous=topic.sentences[ri-1];
 const context=previous&&row.speaker.startsWith('Học sinh')&&previous.speaker!==row.speaker?previous:row;
 return {id:row.id,topic:topic.title,title:`Câu ${ri+1}/50 · ${row.speaker}`,robot:context.en,robotVi:context.vi,target:row.en,vi:row.vi,ipa:row.ipa,topicIndex:ti,number:ri+1,speaker:row.speaker,model:context===row,hint:'Nghe chậm, nói từng cụm rồi nối thành câu. Máy chỉ đối chiếu câu chữ nhận dạng; không chấm chính xác từng âm.'};
}));
const sp500Ids=new Set(sp500Lessons.map(x=>x.id));
const sp500GotoBase=goto;
function sp500Nav(page){dnClose();sp500GotoBase(page)}
function sp500Art(crop){const [x,y,w,h]=crop,sw=1672,sh=941;return `--sp5-sheet:var(--sp500-reference);--sp5-ratio:${w}/${h};--sp5-size:${sw/w*100}%;--sp5-x:${x/(sw-w)*100}%;--sp5-y:${y/(sh-h)*100}%`}
function sp500ImageUrl(uri){if(!uri.startsWith("data:"))return uri;try{const parts=uri.split(','),bytes=Uint8Array.from(atob(parts[1]),x=>x.charCodeAt(0));return URL.createObjectURL(new Blob([bytes],{type:parts[0].slice(5).split(';')[0]}))}catch{return uri}}
function sp500Current(){return dnSession?sp500Lessons[dnSession.index]:null}
// Fisher–Yates: đảo theo từng chủ đề, đi hết 50 câu trước khi lặp một vòng mới.
function sp500Shuffle(values){const result=values.slice();for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]]}return result}
function sp500MakeOrder(topic,avoid=-1){const s=dnSession;if(!s)return;const old=s.order?.join(',');let order=sp500Shuffle(Array.from({length:50},(_,i)=>topic*50+i));if(order[0]===avoid)[order[0],order[1]]=[order[1],order[0]];if(order.join(',')===old)[order[1],order[2]]=[order[2],order[1]];s.order=order;s.orderTopic=topic}
function sp500SelectTopic(value){const topic=Number(value);if(dnSession&&Number.isInteger(topic)&&topic>=0&&topic<10){sp500MakeOrder(topic,dnSession.index);dnLoad(dnSession.order[0])}}
function sp500Reshuffle(){const l=sp500Current();if(!l)return;sp500MakeOrder(l.topicIndex,dnSession.index);dnLoad(dnSession.order[0])}
function sp500Advance(delta){const s=dnSession;if(!s)return;const l=sp500Current();if(s.orderTopic!==l.topicIndex)sp500MakeOrder(l.topicIndex);let position=s.order.indexOf(s.index)+delta;if(position>=50){sp500MakeOrder(l.topicIndex,s.index);position=0}else if(position<0)position=49;dnLoad(s.order[position])}
function sp500SelectSentence(value){const l=sp500Current(),n=Number(value);if(l&&Number.isInteger(n)&&n>=0&&n<50)dnLoad(l.topicIndex*50+n)}
let sp500Sound=null;
function sp500Bell(){try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;sp500Sound??=new Audio();sp500Sound.resume()?.catch(()=>{});const now=sp500Sound.currentTime;[660,880,1100].forEach((tone,i)=>{const osc=sp500Sound.createOscillator(),gain=sp500Sound.createGain();osc.frequency.value=tone;gain.gain.setValueAtTime(.035,now+i*.11);gain.gain.exponentialRampToValueAtTime(.001,now+i*.11+.2);osc.connect(gain);gain.connect(sp500Sound.destination);osc.start(now+i*.11);osc.stop(now+i*.11+.21)})}catch{}}
// Chỉ tính các ID của ngân hàng mới. Sao và lịch sử 8 câu cũ vẫn được giữ nguyên.
dnUpdateScore=function(){if(!dnSession)return;const all=[...dnSession.awarded].filter(id=>sp500Ids.has(id)),l=sp500Current();const done=all.filter(id=>id.startsWith(`school500-${String(l.topicIndex+1).padStart(2,'0')}-`)).length;
 dnElement('score').textContent=`⭐ ${all.length*2} sao · ${all.length}/500 câu`;
 dnElement('progress').value=done;dnElement('progress-text').textContent=`Chủ đề ${l.topicIndex+1}: đã luyện đạt ${done}/50 câu`;
};
dnLoad=function(index){const s=dnSession;if(!s)return;const n=Number(index);if(!Number.isFinite(n))return;clearTimeout(s.nextTimer);dnStopMic();dnCancelVoice();s.index=((Math.trunc(n)%500)+500)%500;const l=sp500Current();
 for(const [id,value] of Object.entries({topic:'🌿 '+SP500_TOPICS[l.topicIndex].title,title:l.title,question:l.robot,translation:l.robotVi,target:l.target,meaning:l.vi,ipa:l.ipa,hint:l.hint}))dnElement(id).textContent=value;
 dnElement('model-label').textContent=l.model?'Nghe rô-bốt đọc mẫu:':'Lời thoại trước trong tình huống:';
 dnElement('role').textContent=`Em luyện vai ${l.speaker.toLowerCase()}:`;
 dnElement('topic-select').value=String(l.topicIndex);
 if(s.orderTopic!==l.topicIndex)sp500MakeOrder(l.topicIndex);
 dnElement('select').innerHTML=s.order.map(index=>{const x=sp500Lessons[index];return `<option value="${x.number-1}" ${index===s.index?'selected':''}>${x.number}/50 · ${esc(x.target)}</option>`}).join('');
 dnElement('shuffle-note').textContent=`🔀 Lượt ${s.order.indexOf(s.index)+1}/50 · Câu tự động xáo trộn trong chủ đề`;
 dnElement('reward').textContent='';dnElement('heard').textContent='';dnElement('hint').hidden=true;
 dnElement('next').textContent='Câu tiếp theo →';
 dnElement('manual').open=false;dnStatus('Bấm loa nghe mẫu, sau đó bấm micro để nói.');dnPose('idle');dnUpdateScore();
};
dnGrade=function(correct,source='adult'){
 const s=dnSession;if(!s)return;if(s.person!==(state.user?.username||'guest')){dnClose();return}dnStopMic();dnCancelVoice();clearTimeout(s.nextTimer);const l=sp500Current();
 if(correct){const award=dnAward(l.id,source);if(award.ok)s.awarded.add(l.id);dnUpdateScore();dnElement('reward').textContent='⭐ ⭐ ⭐';dnPose('happy');sp500Bell();dnStatus(!award.ok?'Em đã nói được! Chưa lưu được sao trên máy; em có thể thử lại.':award.duplicate?'Rất tốt! Câu này đã nhận sao trước đó.':award.guest?'Rất tốt! +2 sao trong phiên khách. Chọn hồ sơ ở Trang chủ để lưu thành tích.':'Rất tốt! +2 sao đã được thêm vào bảng vinh danh.');dnSpeak('Excellent! Good job!',.85,'en-US','happy');
  if(award.ok){const index=s.index;s.nextTimer=setTimeout(()=>{if(dnSession===s&&s.index===index)sp500Advance(1)},4500)}
 }else{dnElement('reward').textContent='';dnElement('hint').hidden=false;dnPose('help');dnStatus('Cảm ơn em đã thử! Cùng nghe chậm rồi nói lại nhé. Không trừ sao.');dnSpeak('Good try! Listen again!',.85,'en-US','help');const index=s.index;s.nextTimer=setTimeout(()=>{if(dnSession===s&&s.index===index)dnSpeak(l.target,.6,'en-US','help')},2400)}
};
// Hủy lời đọc/phản hồi cũ trước mỗi thao tác nghe để không đọc chồng câu.
function sp500Play(kind){const s=dnSession,l=sp500Current();if(!s||!l)return;clearTimeout(s.nextTimer);dnSpeak(kind==='question'?l.robot:l.target,kind==='slow'?.6:.85)}
dnOpen=function(){
 if(dnSession)return;try{releaseRobotAudio();window.speechSynthesis?.cancel()}catch{}
 const s={index:0,ticket:0,voice:0,phase:'idle',rec:null,awarded:new Set(dnKnownAwards()),person:state.user?.username||'guest',overflow:document.body.style.overflow,focus:document.activeElement};dnSession=s;sp500MakeOrder(0);s.index=s.order[0];
 const popup=document.createElement('section');popup.id='dn-speaking';popup.className='sp500';popup.setAttribute('role','dialog');popup.setAttribute('aria-modal','true');popup.setAttribute('aria-labelledby','dn-heading');
 popup.innerHTML=`<aside class="sp5-sidebar"><button class="sp5-brand" onclick="sp500Nav('home')" aria-label="Đại Ngàn Song Ngữ · về Trang chủ"></button><nav aria-label="Điều hướng ứng dụng">${[['home','Trang chủ'],['vocab','Từ vựng'],['games','Luyện tập'],['evaluation','Góc tiến bộ'],['ranking','Thành tích'],['settings','Cài đặt']].map(([page,label],i)=>`<button class="sp5-nav sp5-nav-${i}" onclick="sp500Nav('${page}')" aria-label="${label}"></button>`).join('')}</nav></aside>
 <div class="sp5-main"><header class="sp5-hero"><h2 id="dn-heading" class="sp5-sr">Luyện nói cùng rô-bốt · Đại Ngàn Song Ngữ</h2><button id="dn-close" type="button" aria-label="Đóng luyện nói">✕ Đóng</button></header>
 <div class="sp5-toolbar"><label><span>📖 Chủ đề</span><select id="dn-topic-select" aria-label="Chọn chủ đề luyện nói">${SP500_TOPICS.map((t,i)=>`<option value="${i}">${i+1}/10 · ${esc(t.title)}</option>`).join('')}</select></label><label class="sp5-sentence-label"><span>Tình huống</span><select id="dn-select" aria-label="Chọn câu luyện nói"></select></label><strong id="dn-score"></strong></div>
 <div class="sp5-room"><aside class="sp5-scene"><div class="sp5-stage" id="dn-stage" data-state="idle"><div class="sp5-mask"><span class="sp5-avatar" style="${sp500Art([413,450,323,340])}" role="img" aria-label="Bạn Rô-bốt Dẻ Triêng mặc trang phục thổ cẩm"></span></div><span class="sp5-wave" aria-hidden="true">◖ )))</span><span class="sp5-spark" aria-hidden="true">⭐ ✨ ⭐</span></div><p id="dn-state" class="sp5-state"></p><div id="dn-reward" class="sp5-reward" role="status" aria-live="polite"></div></aside>
 <section class="sp5-lesson"><p id="dn-topic" class="sp5-topic"></p><h3 id="dn-title"></h3><div class="sp5-bubble"><span id="dn-model-label" class="sp5-model-label"></span><p id="dn-question" lang="en"></p><small id="dn-translation"></small></div><p id="dn-role" class="sp5-role"></p><p id="dn-target" class="sp5-target" lang="en"></p><p id="dn-meaning" class="sp5-meaning"></p><p id="dn-ipa" class="sp5-ipa" lang="en"></p><small class="sp5-ipa-note">IPA tham khảo · cách đọc từ điển giọng Mỹ</small>
 <div class="sp5-audio"><button id="dn-question-audio" type="button">🔊 Nghe rô-bốt nói</button><button id="dn-sample" type="button">🔊 Nghe câu trả lời</button><button id="dn-slow" type="button">🐢 Nghe chậm 0.6x</button></div>
 <div class="sp5-microw"><button id="dn-mic" type="button" aria-label="Bật micro để nói" aria-pressed="false"><svg viewBox="0 0 32 32" aria-hidden="true"><rect x="11" y="3" width="10" height="17" rx="5" fill="currentColor"/><path d="M7 15v2a9 9 0 0018 0v-2M16 26v4M11 30h10" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg></button><p id="dn-status" role="status" aria-live="polite"></p></div>
 <p id="dn-heard" class="sp5-heard"></p><p id="dn-hint" class="sp5-hint" hidden></p><label class="sp5-consent"><input id="dn-consent" type="checkbox">Người lớn đồng ý bật micro. Dịch vụ nhận dạng của trình duyệt có thể gửi giọng nói qua mạng; ứng dụng không lưu bản ghi âm.</label>
 <p id="dn-shuffle-note" class="sp5-shuffle-note"></p><div class="sp5-progress"><span id="dn-progress-text"></span><progress id="dn-progress" max="50" value="0"></progress></div><div class="sp5-pager"><button id="dn-prev" type="button">← Câu trước</button><button id="dn-reshuffle" type="button">🔀 Đảo câu</button><button id="dn-next" type="button">Câu tiếp theo →</button></div></section></div>
 <footer class="sp5-footer"><details id="dn-manual"><summary>Phụ huynh / giáo viên hỗ trợ khi không dùng micro</summary><p>Nghe học sinh nói rồi chọn nhận xét. Mỗi câu luyện đạt được +2 sao một lần cho mỗi hồ sơ.</p><button id="dn-adult-good" type="button">Đã nói được · +2 sao</button><button id="dn-adult-retry" type="button">Cùng thử lại</button></details><p>Nhận dạng chỉ đối chiếu câu chữ máy nghe được, không đánh giá chính xác từng âm. Nghe mẫu phụ thuộc giọng đọc có sẵn trên thiết bị; micro có thể cần mạng. ${state.user?'Sao được lưu vào hồ sơ đang chọn.':'Phiên khách: sao giữ trong phiên này; chọn hồ sơ để lưu thành tích.'}</p></footer></div>`;
 document.body.append(popup);document.body.style.overflow='hidden';const app=document.getElementById('app');if(app)app.inert=true;
 dnElement('close').onclick=dnClose;dnElement('prev').onclick=()=>sp500Advance(-1);dnElement('next').onclick=()=>sp500Advance(1);dnElement('reshuffle').onclick=sp500Reshuffle;dnElement('topic-select').onchange=e=>sp500SelectTopic(e.target.value);dnElement('select').onchange=e=>sp500SelectSentence(e.target.value);
 dnElement('sample').onclick=()=>sp500Play('sample');dnElement('question-audio').onclick=()=>sp500Play('question');dnElement('slow').onclick=()=>sp500Play('slow');dnElement('mic').onclick=dnStartMic;
 dnElement('consent').onchange=e=>{if(!e.target.checked){dnStopMic();dnStatus('Đã tắt micro. Em vẫn nghe mẫu và chuyển câu được.')}};
 dnElement('adult-good').onclick=()=>dnGrade(true,'adult');dnElement('adult-retry').onclick=()=>dnGrade(false,'adult');
 document.addEventListener('keydown',dnKey);document.addEventListener('visibilitychange',dnVisibility);dnLoad(s.index);dnElement('close').focus();
};
// Chỉ thay mục Luyện nói. Mọi lối vào Chăm sóc Rô-bốt giữ nguyên bộ điều khiển gốc.
goto=function(page){if(page==='speaking'){dnOpen();return}sp500GotoBase(page)};

dnStartMic=function(){
 const s=dnSession;if(!s)return;if(s.phase!=='idle'){dnFinishMic();return}
 if(!dnElement('consent').checked){dnStatus('Người lớn đọc và đánh dấu đồng ý trước khi bật micro. Em vẫn nghe mẫu, chuyển câu và chấm thủ công được.');dnElement('consent').focus();return}
 clearTimeout(s.nextTimer);dnCancelVoice();dnStopMic();const ticket=s.ticket,index=s.index;let got=false;
 try{const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(typeof Recognition!=='function'){dnStatus('Trình duyệt chưa hỗ trợ nhận dạng. Em vẫn nghe mẫu, chuyển câu và nhờ người lớn chấm được.');return}
 const rec=new Recognition();s.rec=rec;s.phase='starting';s.stopWhenReady=false;rec.lang='en-US';rec.continuous=false;rec.interimResults=false;rec.maxAlternatives=1;dnElement('mic').setAttribute('aria-pressed','true');dnPose('listening');dnStatus('Đang mở micro… Em cho phép micro nếu trình duyệt hỏi nhé.');
 const active=()=>dnSession===s&&s.ticket===ticket&&s.index===index;
 rec.onstart=()=>{if(!active())return;s.phase='listening';dnElement('mic').setAttribute('aria-label','Dừng micro');dnStatus('Đang lắng nghe em nói...');clearTimeout(s.micTimer);s.micTimer=setTimeout(dnFinishMic,12000);if(s.stopWhenReady)dnFinishMic()};
 rec.onspeechend=()=>{if(active())dnFinishMic()};
 rec.onresult=event=>{if(!active()||got)return;try{const text=event.results?.[0]?.[0]?.transcript;if(!text?.trim())return;got=true;dnElement('heard').textContent='Máy nghe được: “'+text+'”';dnGrade(dnMatches(text,sp500Lessons[index]),'recognition')}catch{dnStopMic();dnStatus('Chưa đọc được kết quả. Em thử lại hoặc nhờ người lớn chấm nhé.')}};
 rec.onerror=event=>{if(!active()||got)return;const messages={'not-allowed':'Micro bị chặn quyền.','service-not-allowed':'Dịch vụ nhận dạng đang bị chặn.','audio-capture':'Chưa tìm thấy micro.','network':'Nhận dạng cần mạng hoặc đang lỗi mạng.','no-speech':'Chưa nghe rõ câu của em.','aborted':'Đã dừng micro.'};dnStopMic();dnStatus((messages[event.error]||'Micro chưa dùng được.')+' Em vẫn nghe mẫu, chuyển câu và chấm thủ công được.')};
 rec.onend=()=>{if(!active()||got)return;dnStopMic();dnStatus('Chưa nhận được câu nói. Em thử lại khi sẵn sàng nhé.')};
 s.micTimer=setTimeout(()=>{if(active()){dnStopMic();dnStatus('Micro chưa khởi động được. Em vẫn nghe mẫu và chuyển câu được.')}},12000);rec.start()
 }catch{dnStopMic();dnStatus('Không mở được micro. Kiểm tra quyền hoặc dùng phần chấm của người lớn; các nút khác vẫn hoạt động.')}
};

document.documentElement.style.setProperty("--sp500-reference",'url("'+sp500ImageUrl("./assets/7365e70faf73c1b92973c790.webp")+'")');

// Chỉ thay giao diện Từ vựng.
// Giao diện Từ vựng: giữ nguyên ngân hàng từ, ID và các hàm lưu dữ liệu gốc.
const vuPriority=['pencil','classroom','teacher','student','textbook','desk','chair','school bag','notebook','blackboard'];
const vuCrops={pencil:[331,561,161,109],classroom:[526,561,161,109],teacher:[723,561,161,109],student:[919,561,161,109],textbook:[1115,561,161,109],desk:[331,746,161,109],chair:[526,746,161,109],'school bag':[723,746,161,109],notebook:[919,746,161,109],blackboard:[1115,746,161,109]};
function vuSprite(crop){const [x,y,w,h]=crop,sw=1672,sh=941;return `--vu-ratio:${w}/${h};--vu-size:${sw/w*100}%;--vu-x:${x/(sw-w)*100}%;--vu-y:${y/(sh-h)*100}%`}
function vuImageUrl(uri){if(!uri.startsWith("data:"))return uri;try{const parts=uri.split(','),bytes=Uint8Array.from(atob(parts[1]),x=>x.charCodeAt(0));return URL.createObjectURL(new Blob([bytes],{type:parts[0].slice(5).split(';')[0]}))}catch{return uri}}
function vuFavorites(){const saved=favorites();return Array.isArray(saved)?saved:[]}
function vuWords(){const data=state.data.vocabulary;const selected=vuPriority.map(en=>data.find(w=>w.en.toLowerCase()===en)).filter(Boolean),ids=new Set(selected.map(w=>w.id));return [...selected,...data.filter(w=>!ids.has(w.id))]}
function vuFiltered(){const fav=new Set(vuFavorites()),learned=new Set(state.progress.learned);return vuWords().filter(w=>(state.category==='Tất cả'||w.category===state.category)&&(!state.onlyLearned||learned.has(w.id))&&(!state.onlyFavorites||fav.has(w.id))&&(`${w.en} ${w.vi}`.toLocaleLowerCase('vi').includes(state.term.toLocaleLowerCase('vi'))))}
function vuFilter(mode){if(mode==='all'){state.onlyLearned=false;state.onlyFavorites=false}else if(mode==='learned')state.onlyLearned=!state.onlyLearned;else if(mode==='favorites')state.onlyFavorites=!state.onlyFavorites;state.vocabPage=0;render()}
function vuPicture(word){const crop=vuCrops[word.en.toLowerCase()];if(crop)return `<span class="vu-sprite vu-word-art" style="${vuSprite(crop)}" role="img" aria-label="Minh họa: ${esc(word.vi)}"></span>`;return `<span class="vu-word-art vu-original-art"><img src="${esc(ASSET_URLS[word.image]||word.image)}" alt="${word.imageKind==='minh họa'?'Minh họa':'Hình gợi nhớ'}: ${esc(word.vi)}" loading="lazy" decoding="async" draggable="false"></span>`}
function vuCard(word){const favorite=vuFavorites().includes(word.id),done=state.progress.learned.includes(word.id);return `<article class="vu-card" data-vu-id="${esc(word.id)}"><button type="button" class="vu-favorite ${favorite?'is-favorite':''}" aria-pressed="${favorite}" aria-label="${favorite?'Bỏ lưu':'Lưu'} ${esc(word.en)} yêu thích" onclick="toggleFavorite(${esc(JSON.stringify(word.id))})">${favorite?'★':'☆'}</button><details class="vu-word-details"><summary aria-label="Xem nghĩa và tiến độ từ ${esc(word.en)}">${vuPicture(word)}<span class="vu-word-title" lang="en">${esc(word.en)}</span><span class="vu-sr"> · Chạm để xem nghĩa</span><button type="button" class="vu-speak" aria-label="Nghe ${esc(word.en)}" onclick="event.preventDefault();event.stopPropagation();say(${esc(JSON.stringify(word.en))})"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 9h4l5-4v14l-5-4H3z" fill="currentColor"/><path d="M16 8c2 2 2 6 0 8m3-11c4 4 4 10 0 14" stroke="currentColor" fill="none" stroke-width="2" stroke-linecap="round"/></svg></button></summary><div class="vu-word-meaning">${word.ipa?`<p class="vu-ipa" lang="en">${esc(word.ipa)}</p>`:''}<strong>${esc(word.vi)}</strong><small>${esc(word.category)}</small>${word.example?`<p lang="en">${esc(word.example)}</p>`:''}<button type="button" class="vu-learn ${done?'is-learned':''}" onclick="learn(${esc(JSON.stringify(word.id))})">${done?'✓ Đã học':'☆ Em đã nhớ từ này'}</button></div></details>${done?'<span class="vu-done" aria-label="Đã học">✓</span>':''}</article>`}
function vuHelp(){robot('🤖 Em cần giúp?', '<p>Gõ một từ tiếng Anh hoặc nghĩa tiếng Việt để tìm. Chọn chủ đề, Đã học hoặc Yêu thích để lọc.</p><p>Chạm vào tranh để xem nghĩa, phiên âm và ví dụ. Bấm loa để nghe; bấm ngôi sao để lưu yêu thích.</p><p>Khi đã nhớ từ, mở thẻ và bấm “Em đã nhớ từ này”. Chọn hồ sơ để lưu tiến độ học tập.</p>',false)}
vocabulary=function(){const all=state.data.vocabulary,filtered=vuFiltered(),pages=Math.max(1,Math.ceil(filtered.length/10));state.vocabPage=Math.max(0,Math.min(state.vocabPage,pages-1));const shown=filtered.slice(state.vocabPage*10,state.vocabPage*10+10),learned=all.filter(w=>state.progress.learned.includes(w.id)).length,fav=all.filter(w=>vuFavorites().includes(w.id)).length,categories=[...new Set(all.map(w=>w.category))];
return `<div class="vu-app"><aside class="vu-sidebar"><button type="button" class="vu-brand" aria-label="Đại Ngàn Song Ngữ · về Trang chủ" onclick="goto('home')"></button><nav aria-label="Điều hướng ứng dụng">${[['home','Trang chủ'],['vocab','Từ vựng'],['games','Luyện tập'],['evaluation','Góc tiến bộ'],['ranking','Thành tích'],['settings','Cài đặt']].map(([page,label],i)=>`<button type="button" class="vu-nav vu-nav-${i}" ${page==='vocab'?'aria-current="page"':''} aria-label="${label}" onclick="goto('${page}')"></button>`).join('')}</nav></aside>
<main class="vu-main"><header class="vu-banner"><h1 class="vu-sr">1000 TỪ VỰNG GIAO TIẾP TRÊN TRƯỜNG HỌC</h1><p class="vu-sr">43 chủ đề · Từ và cụm từ trong học tập, hoạt động và cuộc sống quanh em</p><button type="button" class="vu-login ${state.user?'has-profile':''}" aria-label="${state.user?'Hồ sơ '+esc(state.user.name):'Đăng nhập / chọn hồ sơ'}" onclick="${state.user?"goto('settings')":"openAuth()"}">${state.user?'👤 '+esc(state.user.name):'<span class="vu-sr">Đăng nhập / Login</span>'}</button></header>
<div class="vu-board"><section class="vu-library" aria-label="Kho từ vựng"><div class="vu-toolbar"><label>Tìm từ<span class="vu-search-wrap"><span aria-hidden="true">⌕</span><input type="search" class="search vu-search" placeholder="Tìm từ tiếng Anh hoặc tiếng Việt..." value="${esc(state.term)}" oninput="updateVocabSearch(this)"></span></label><label>Chủ đề<select aria-label="Chủ đề từ vựng" onchange="state.category=this.value;state.vocabPage=0;render()"><option ${state.category==='Tất cả'?'selected':''}>Tất cả</option>${categories.map(c=>`<option ${state.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label></div>
<div class="vu-filters" aria-label="Lọc trạng thái từ vựng"><button type="button" aria-pressed="${!state.onlyLearned&&!state.onlyFavorites}" class="${!state.onlyLearned&&!state.onlyFavorites?'is-active':''}" onclick="vuFilter('all')">📚 Tất cả</button><button type="button" aria-pressed="${state.onlyLearned}" class="${state.onlyLearned?'is-active':''}" onclick="vuFilter('learned')">✅ Đã học</button><button type="button" aria-pressed="${state.onlyFavorites}" class="${state.onlyFavorites?'is-active':''}" onclick="vuFilter('favorites')">❤️ Yêu thích</button><span class="vu-result" role="status">${filtered.length} mục</span></div>
<div class="vu-grid">${shown.map(vuCard).join('')||'<div class="vu-empty" role="status">🔎 Không tìm thấy từ phù hợp. Em thử từ khóa khác hoặc chọn Tất cả nhé.</div>'}</div>${pager('vocabPage',state.vocabPage,pages)}<p class="vu-tip">Chạm vào tranh để xem nghĩa, ví dụ và đánh dấu đã học.</p><details class="vu-subjects" id="existing-subjects"><summary>📚 Từ vựng các môn học · 11 môn × 100 từ/cụm từ</summary>${existingSubjectNav()}</details></section>
<aside class="vu-statistics" aria-label="Thống kê học từ vựng"><section class="vu-progress-card"><h2 class="vu-sprite vu-stat-title" style="${vuSprite([1321,358,324,78])}"><span class="vu-sr">🏆 TỪ ĐÃ HỌC</span></h2><p class="vu-count"><strong>${learned}</strong><span>/${all.length.toLocaleString('de-DE')}</span></p><progress value="${learned}" max="${all.length}" aria-label="Tiến độ từ đã học">${learned}/${all.length}</progress><p class="vu-fav-count">❤️ ${fav} mục yêu thích</p><button type="button" class="vu-flash" onclick="startFlashcard()">🃏 Lật thẻ từ vựng</button><button type="button" class="vu-practice" onclick="goto('games')">⚡ Luyện tập ngay</button>${state.user?`<p class="vu-profile">Hồ sơ: ${esc(state.user.name)}</p>`:'<p class="vu-profile">Chọn hồ sơ để lưu tiến độ học.</p>'}</section></aside></div></main><button type="button" class="vu-help vu-sprite" style="${vuSprite([1355,784,291,113])}" aria-label="Em cần giúp?" onclick="vuHelp()"><span class="vu-sr">Em cần giúp?</span></button></div>`;
};
// Chỉ thay khung của trang Từ vựng; các trang còn lại dùng đúng layout cũ.
const vuLayoutBase=layout;layout=function(body){return state.page==='vocab'?body:vuLayoutBase(body)};

document.documentElement.style.setProperty("--vu-reference",'url("'+vuImageUrl("./assets/bb2701ec09fc6e8b8b0b62b3.webp")+'")');

// Giao diện ba trang: giữ nguyên dữ liệu và các API lưu trữ hiện có.
// Ba giao diện mới chỉ đọc dữ liệu hiện có; không sửa hồ sơ, điểm hoặc lịch sử.
const tpPages=new Set(['settings','evaluation','ranking']);
const tpNames={settings:['CÀI ĐẶT','Hồ sơ và âm thanh'],evaluation:['ĐÁNH GIÁ HỌC TẬP','Theo dõi tiến bộ của em · Mỗi ngôi sao là một nỗ lực'],ranking:['BẢNG XẾP HẠNG THÀNH TÍCH CẢ LỚP','Cùng học · Cùng tiến bộ · Mỗi ngôi sao đều quý giá']};
function tpSprite(sheet,crop){const [x,y,w,h]=crop,sw=1672,sh=941;return `--tp-sheet:var(--tp-${sheet});--tp-ratio:${w}/${h};--tp-size:${sw/w*100}%;--tp-x:${x/(sw-w)*100}%;--tp-y:${y/(sh-h)*100}%`}
function tpImageUrl(uri){if(!uri.startsWith("data:"))return uri;try{const p=uri.split(','),bytes=Uint8Array.from(atob(p[1]),x=>x.charCodeAt(0));return URL.createObjectURL(new Blob([bytes],{type:p[0].slice(5).split(';')[0]}))}catch{return uri}}
// Quy tắc hình minh họa do người dùng yêu cầu: họ Y → bạn nữ, họ A → bạn nam.
// Tên khác dùng biểu tượng chung; không suy đoán hoặc lưu thông tin giới tính.
function tpAvatarKind(name){const first=String(name||'').trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').split(/\s+/)[0].toUpperCase();return first==='Y'?'girl':first==='A'?'boy':'neutral'}
function tpAvatar(name){const kind=tpAvatarKind(name);if(kind==='neutral')return '<span class="tp-avatar tp-neutral" role="img" aria-label="Biểu tượng học sinh">👤</span>';return `<span class="tp-avatar tp-sprite" data-avatar="${kind}" style="${tpSprite('ranking',kind==='girl'?[665,480,100,100]:[884,426,112,112])}" role="img" aria-label="${kind==='girl'?'Hình bạn nữ':'Hình bạn nam'}"></span>`}
function tpIcon(icon){const path=emojiImage(icon);return path?`<img class="tp-icon" src="${esc(ASSET_URLS[path]||path)}" alt="" draggable="false">`:`<span aria-hidden="true">${icon}</span>`}
function tpHelp(){robot('🤖 Em cần giúp?',state.page==='settings'?'<p>Chọn tốc độ giọng đọc phù hợp. Nút Tải kết quả tạo tệp CSV của lớp đang chọn trên thiết bị này.</p>':state.page==='evaluation'?'<p>Mỗi thẻ cho biết số sao em đã tích lũy theo kỹ năng. Biểu đồ dùng chính kết quả của em. Bấm Tiếp tục học để mở Luyện tập.</p>':'<p>Bảng xếp hạng dùng kết quả các hồ sơ cùng lớp trên thiết bị này. Sao và lượt luyện cập nhật từ hoạt động học. Bấm Xuất bảng kết quả để tải tệp CSV.</p>',false)}
function tpShell(body){const page=state.page,names=tpNames[page],nav=[['home','🏠','Trang chủ'],['vocab','📖','Từ vựng'],['games','✏️','Luyện tập'],['evaluation','📊','Góc tiến bộ'],['ranking','🏆','Thành tích'],['lessons','💬','Giao tiếp lớp học'],['stories','📚','Kể chuyện bản làng'],['grammar','📗','Cấu trúc & ngữ pháp'],['settings','⚙️','Cài đặt'],['speaking','🤖','Luyện nói cùng rô-bốt'],['teacher','👩‍🏫','Góc giáo viên']];return `<div class="tp-app tp-${page}" style="--tp-current:var(--tp-${page})"><aside class="tp-sidebar"><button class="tp-brand" onclick="goto('home')" aria-label="Đại Ngàn Song Ngữ · về Trang chủ"></button><nav aria-label="Điều hướng ứng dụng">${nav.map(([id,icon,label])=>`<button type="button" class="${page===id?'is-active':''}" ${page===id?'aria-current="page"':''} onclick="goto('${id}')">${tpIcon(icon)}<span>${label}</span></button>`).join('')}</nav></aside><main class="tp-main"><header class="tp-hero"><h1 class="tp-sr">${names[0]}</h1><p class="tp-sr">${names[1]}</p><div class="tp-account">${state.user?`<span class="tp-account-stars">⭐ ${total()} sao</span><button onclick="goto('settings')">${tpAvatar(state.user.name)}<b>${esc(state.user.name)} · ${esc(state.user.class_name)}</b></button><button onclick="logout()">Thoát</button>`:'<button onclick="openAuth()">👤 ĐĂNG NHẬP / LOGIN</button>'}</div></header>${page==='settings'?`<div class="tp-settings-title tp-sprite" style="${tpSprite('settings',[254,256,1399,174])}" role="img" aria-label="Cài đặt · Hồ sơ và âm thanh"></div>`:''}<div class="tp-content ${!state.user?'tp-guest':''}">${body}</div><footer class="tp-footer">⭐ Học vui mỗi ngày · Giao tiếp tự tin · Thành công ở trường và trong cuộc sống!<small>Bản xem trước · Đại Ngàn Song Ngữ · Hồ sơ lưu trên thiết bị</small></footer></main><button class="tp-help tp-sprite" style="${tpSprite('settings',[1467,850,187,74])}" aria-label="Em cần giúp?" onclick="tpHelp()"></button></div>`}
function tpSettings(){const u=state.user;if(!u)return '';const speed=localStorage.getItem('voice-speed')||'0.85';return `<section class="tp-settings-card"><div class="tp-settings-form"><div class="tp-profile">${tpAvatar(u.name)}<div><h2>${esc(u.name)}</h2><p>Lớp ${esc(u.class_name)}</p><small>Tên đăng nhập: ${esc(u.username)}</small></div></div><p>Hồ sơ học tập lưu trên thiết bị này, không xác minh mật khẩu.</p><label class="tp-speed" for="voice-speed">Tốc độ giọng đọc<select id="voice-speed" onchange="localStorage.setItem('voice-speed',this.value)">${[['0.65','Chậm'],['0.85','Vừa'],['1','Bình thường']].map(([value,label])=>`<option value="${value}" ${speed===value?'selected':''}>${label}</option>`).join('')}</select></label><p>Ưu tiên giọng tiếng Anh Mỹ trên thiết bị. Chất lượng và giọng nữ tùy thuộc trình duyệt.</p><button class="tp-button" onclick="exportResults()">⬇️ Tải kết quả lớp trên thiết bị</button></div><div class="tp-settings-art tp-sprite" style="${tpSprite('settings',[1100,455,538,348])}" role="img" aria-label="Học sinh và rô-bốt cùng học bên máy tính"></div></section><button class="tp-teacher-link" onclick="goto('teacher')">Góc giáo viên</button>`}
function tpEvaluation(){const skills=['Nghe','Nói','Đọc','Viết'],values=skills.map(skill=>Math.max(0,Number(state.progress.skills.find(x=>x.skill===skill)?.stars)||0)),max=Math.max(1,...values),magnitude=10**Math.floor(Math.log10(max/5)),step=Math.max(1,Math.ceil(max/5/magnitude)*magnitude),top=Math.ceil(max/step)*step,ticks=Array.from({length:Math.ceil(top/step)+1},(_,i)=>top-i*step),icons=[[372,310,95,83],[674,325,68,65],[934,324,65,66],[1183,324,91,68],[1457,324,80,72]];
return `<section class="tp-stat-row" aria-label="Tổng sao và sao theo kỹ năng">${[['TỔNG SAO CỦA EM',total()],...skills.map((s,i)=>[s,values[i]])].map(([label,value],i)=>`<article class="tp-stat tp-stat-${i}"><span class="tp-stat-icon tp-sprite" style="${tpSprite('evaluation',icons[i])}" aria-hidden="true"></span><strong>${value}</strong><b>${label}</b></article>`).join('')}</section><section class="tp-chart-card"><h2 class="tp-chart-title tp-sprite" style="${tpSprite('evaluation',[281,515,488,68])}"><span class="tp-sr">Ngôi sao theo kỹ năng</span></h2><div class="tp-chart" role="img" aria-label="${skills.map((s,i)=>s+': '+values[i]+' sao').join(', ')}"><div class="tp-axis" aria-hidden="true">${ticks.map(t=>`<span style="top:${(top-t)/top*100}%">${t}</span>`).join('')}</div><div class="tp-chart-grid" style="--tp-grid-size:${100/(ticks.length-1)}%"><div class="tp-bars">${values.map((v,i)=>`<div class="tp-column"><div class="tp-bar tp-bar-${i}" style="height:${v/top*100}%"><strong>${v}</strong></div><span class="tp-bar-label">${tpIcon(['🎧','🎤','📖','✏️'][i])}${skills[i]}</span></div>`).join('')}</div></div></div></section><section class="tp-continue"><p>📚 Đã ghi nhớ <b>${state.progress.learned.length}</b> mục học tập</p><button class="tp-button" onclick="goto('games')">Tiếp tục học ❯</button></section>`}
function tpPodium(index){const row=state.leaders[index];return `<article class="tp-podium-item tp-place-${index+1}"><div class="tp-podium-profile"><span class="tp-medal" aria-label="Hạng ${index+1}">${['👑','🥈','🥉'][index]}</span>${tpAvatar(row?.name)}<b>${row?esc(row.name):'Chờ ngôi sao mới'}</b><strong>⭐ ${row?.stars||0}</strong></div><div class="tp-podium-base">${index+1}</div></article>`}
function tpRanking(){return `<section class="tp-class-summary"><span>🏫 Lớp ${esc(state.user?.class_name||'')}</span><span>👥 ${state.leaders.length} học sinh</span><span>⭐ ${classStars()} sao cả lớp</span></section><section class="tp-podium-scene" aria-label="Ba vị trí vinh danh"><span class="tp-nature-left tp-sprite" style="${tpSprite('ranking',[240,377,355,327])}" aria-hidden="true"></span><span class="tp-nature-right tp-sprite" style="${tpSprite('ranking',[1282,377,382,327])}" aria-hidden="true"></span><div class="tp-podium">${[1,0,2].map(tpPodium).join('')}</div></section><section class="tp-ranking-card"><div class="tp-table-scroll"><table><thead><tr><th>Hạng</th><th>Học sinh</th><th>⭐ Sao tích lũy</th><th>🎮 Lượt luyện</th></tr></thead><tbody>${state.leaders.map((x,i)=>`<tr><td><span class="tp-row-medal">${['🥇','🥈','🥉'][i]||i+1}</span></td><td><span class="tp-table-student">${tpAvatar(x.name)}<b>${esc(x.name)}</b></span></td><td>${x.stars}</td><td>${x.plays}</td></tr>`).join('')||'<tr><td colspan="4">Chưa có hồ sơ cùng lớp trên thiết bị này.</td></tr>'}</tbody></table></div><button class="tp-button" onclick="exportResults()">⬇️ Xuất bảng kết quả</button><p class="tp-local-note">Bảng này gồm các hồ sơ cùng lớp trên trình duyệt hiện tại.</p></section>`}
const tpOldBasicPage=basicPage;basicPage=function(){return state.page==='settings'?tpSettings():tpOldBasicPage()};
evaluation=tpEvaluation;ranking=tpRanking;
const tpOldLayout=layout;layout=function(body){return tpPages.has(state.page)?tpShell(body):tpOldLayout(body)};

const TP_SHEETS={"settings":"./assets/98b0b17db4a4ed4723b48bdf.webp","evaluation":"./assets/4db19e62f0aa4361cd28ca5e.webp","ranking":"./assets/b1c52b332becc96053023095.webp"};
for(const [key,image] of Object.entries(TP_SHEETS))document.documentElement.style.setProperty("--tp-"+key,'url("'+tpImageUrl(image)+'")');

const ST_CULTURE=[{"id":"highland-bamboo","title":"The Fragrant Bamboo Rice","vi":"Cơm Lam","type":"Văn hóa Tây Nguyên","grade":5,"icon":"📖","paras":[["Highland hunters and farmers often needed a convenient meal while working deep inside the forest or on distant mountain slopes. They invented Com lam by packing fragrant mountain sticky rice and fresh spring water inside young green bamboo tubes, plugging the ends with banana leaves, and roasting them slowly over glowing charcoal embers. When cooked, peeling away the charred bamboo layer reveals a thin, sweet bamboo skin wrapping around soft, aromatic rice. It is a delicious gift of the mountain.","Người thợ săn và nông dân vùng cao thường cần một bữa ăn tiện lợi khi làm việc trong rừng sâu hay trên nương rẫy xa. Họ đã sáng tạo ra món cơm lam bằng cách cho nếp nương thơm và nước suối mát vào những ống tre non xanh, bịt hai đầu bằng lá chuối rồi nướng chậm trên than hồng. Khi chín, bóc lớp tre cháy sém bên ngoài sẽ lộ ra lớp lụa tre mỏng, ngọt nhẹ, ôm lấy những hạt cơm dẻo và thơm. Đó là một món quà ngon lành của núi rừng."]],"words":80,"source":"Phiếu học tập do người dùng cung cấp","adaptation":"Nội dung được nhập từ phiếu học tập đính kèm. Câu hỏi được chuẩn hóa thành bốn lựa chọn; bổ sung phương án nhiễu ở những câu nguồn chỉ có ba lựa chọn.","moral":"Value local food and the skills passed down through generations.","moralVi":"Trân trọng món ăn quê hương và kinh nghiệm được truyền qua nhiều thế hệ.","worksheet":"8f4c8450-82b3-4979-99b4-15caa30f1e31.png","crop":[28,108,830,537],"questions":[{"en":"Why did highland hunters and farmers need Com lam?","vi":"Vì sao người vùng cao cần cơm lam?","choices":["They wanted a meal for working far away","They wanted to decorate their homes","They wanted to sell toys","They wanted to build bridges"],"answer":0,"explain":"Cơm lam là bữa ăn tiện lợi khi làm việc trong rừng sâu hoặc trên nương xa."},{"en":"What is put inside the bamboo tubes?","vi":"Trong ống tre có gì?","choices":["Corn and milk","Mountain sticky rice and spring water","Fish and salt","Bread and butter"],"answer":1,"explain":"Trong ống tre có nếp nương và nước suối."},{"en":"What do people use to close the ends of the bamboo tubes?","vi":"Người ta bịt đầu ống tre bằng gì?","choices":["Plastic caps","Banana leaves","Cloth bags","Metal lids"],"answer":1,"explain":"Hai đầu ống tre được bịt bằng lá chuối."},{"en":"Where are the bamboo tubes roasted?","vi":"Ống tre được nướng ở đâu?","choices":["In a refrigerator","Over glowing charcoal embers","Under the rain","In cold water"],"answer":1,"explain":"Ống tre được nướng chậm trên than hồng."},{"en":"What happens when the bamboo layer is peeled away?","vi":"Điều gì xảy ra khi bóc lớp tre?","choices":["The rice falls into the fire","A thin bamboo skin is revealed around the rice","The tube becomes full of water","The food turns cold"],"answer":1,"explain":"Bóc lớp tre cháy sém sẽ thấy lớp lụa tre mỏng ôm lấy cơm."},{"en":"What kind of rice is used to make Com lam?","vi":"Loại gạo nào dùng để làm cơm lam?","choices":["Instant rice","Mountain sticky rice","Brown bread","Corn flour"],"answer":1,"explain":"Bài đọc nhắc tới mountain sticky rice, nghĩa là nếp nương."},{"en":"How is the cooked rice described?","vi":"Cơm chín được miêu tả như thế nào?","choices":["Hard and sour","Soft and aromatic","Bitter and dry","Cold and salty"],"answer":1,"explain":"Cơm chín mềm, dẻo và thơm: soft and aromatic."},{"en":"What does the passage call Com lam?","vi":"Bài đọc gọi cơm lam là gì?","choices":["A city snack","A delicious gift of the mountain","A modern machine","A school lunch box"],"answer":1,"explain":"Cơm lam được gọi là món quà ngon lành của núi rừng."}],"cast":[]},{"id":"highland-rong","title":"The Majestic Rong House","vi":"Nhà Rông Tây Nguyên","type":"Văn hóa Tây Nguyên","grade":5,"icon":"📖","paras":[["The Rong house is the traditional communal stilt house of ethnic minority groups in the Northern Central Highlands. Built on massive sturdy wooden pillars high above the ground, it features a soaring, majestic thatched roof shaped like a giant axe blade pointing up to the sky. Inside, the warm central hearth is always burning for village meetings, festivals, and ceremonies. It serves as the spiritual and cultural heart where generations gather to preserve traditions.","Nhà Rông là ngôi nhà sàn sinh hoạt cộng đồng truyền thống của các dân tộc thiểu số ở Bắc Tây Nguyên. Được xây dựng trên những cột gỗ lớn, vững chãi và cao khỏi mặt đất, ngôi nhà nổi bật với mái tranh vươn cao, uy nghi, có hình như một lưỡi rìu khổng lồ chĩa thẳng lên bầu trời. Bên trong, bếp lửa trung tâm luôn bập bùng cho những buổi họp làng, lễ hội và nghi lễ. Đây là trái tim văn hóa và tâm linh, nơi các thế hệ quây quần gìn giữ truyền thống."]],"words":74,"source":"Phiếu học tập do người dùng cung cấp","adaptation":"Nội dung được nhập từ phiếu học tập đính kèm. Câu hỏi được chuẩn hóa thành bốn lựa chọn; bổ sung phương án nhiễu ở những câu nguồn chỉ có ba lựa chọn.","moral":"Community spaces help generations keep traditions alive.","moralVi":"Không gian sinh hoạt chung kết nối các thế hệ và gìn giữ truyền thống.","worksheet":"c15cb16b-d574-4239-942e-dd4942a53116(1).png","crop":[27,105,824,552],"questions":[{"en":"What is the Rong house?","vi":"Nhà Rông là gì?","choices":["A private bedroom","A traditional communal stilt house","A modern shopping mall","A small fishing boat"],"answer":1,"explain":"Nhà Rông là nhà sàn sinh hoạt cộng đồng truyền thống."},{"en":"Where is the Rong house commonly found?","vi":"Nhà Rông thường có ở đâu?","choices":["In the Northern Central Highlands","In the middle of the ocean","In a desert area","In a large foreign city"],"answer":0,"explain":"Bài đọc nói tới Bắc Tây Nguyên: Northern Central Highlands."},{"en":"What supports the Rong house above the ground?","vi":"Bộ phận nào nâng nhà khỏi mặt đất?","choices":["Glass walls","Massive sturdy wooden pillars","Iron chains","Plastic pipes"],"answer":1,"explain":"Những cột gỗ lớn và vững chắc nâng ngôi nhà lên cao."},{"en":"What shape is the roof compared to in the passage?","vi":"Mái nhà được so sánh với hình gì?","choices":["A bird's wing","A giant axe blade","A round basket","A flower petal"],"answer":1,"explain":"Mái tranh cao được ví như lưỡi rìu khổng lồ."},{"en":"What is always burning inside the Rong house?","vi":"Trong nhà luôn có gì?","choices":["A television screen","A warm central hearth","A candle tower","A gas lamp outside"],"answer":1,"explain":"Bài đọc nhắc đến bếp lửa ấm ở trung tâm ngôi nhà."},{"en":"What kinds of activities take place in the Rong house?","vi":"Những hoạt động nào diễn ra tại đây?","choices":["Village meetings, festivals, and ceremonies","Car races and swimming lessons","Shopping and selling mobile phones","Flying kites only"],"answer":0,"explain":"Nhà Rông là nơi họp làng, tổ chức lễ hội và nghi lễ."},{"en":"What does the Rong house symbolize?","vi":"Nhà Rông tượng trưng cho điều gì?","choices":["A private place for one person","The spiritual and cultural heart of the village","A place for storing machines","A hotel for tourists"],"answer":1,"explain":"Đây là trái tim văn hóa và tâm linh của buôn làng."},{"en":"Who gathers there to preserve traditions?","vi":"Ai quây quần để gìn giữ truyền thống?","choices":["Only visitors from cities","Only teachers","Generations of villagers","Only very young children"],"answer":2,"explain":"Nhiều thế hệ dân làng cùng gặp gỡ và gìn giữ truyền thống."}],"cast":[]},{"id":"highland-weaving","title":"The Traditional Brocade Weaving","vi":"Nghề dệt thổ cẩm Tây Nguyên","type":"Văn hóa Tây Nguyên","grade":5,"icon":"📖","paras":[["Brocade weaving is a traditional craft of ethnic minority groups in the Central Highlands. Women use a wooden loom to weave colorful threads into beautiful patterns. Each pattern tells a story about nature, mountains, animals or the life of the village. The brocade cloth is used to make traditional clothes, bags and decorations. This craft shows the talent, patience and creativity of the highland people and helps to keep their culture alive.","Dệt thổ cẩm là nghề truyền thống của các dân tộc thiểu số ở Tây Nguyên. Người phụ nữ dùng khung dệt gỗ để dệt những sợi chỉ nhiều màu sắc thành các hoa văn đẹp. Mỗi hoa văn đều kể một câu chuyện về thiên nhiên, núi rừng, loài vật hoặc cuộc sống của buôn làng. Vải thổ cẩm được dùng để làm trang phục truyền thống, túi xách và các vật trang trí. Nghề dệt thổ cẩm thể hiện tài năng, sự kiên nhẫn và óc sáng tạo của người dân vùng cao, đồng thời giúp gìn giữ văn hóa truyền thống."]],"words":72,"source":"Phiếu học tập do người dùng cung cấp","adaptation":"Nội dung được nhập từ phiếu học tập đính kèm. Câu hỏi được chuẩn hóa thành bốn lựa chọn; bổ sung phương án nhiễu ở những câu nguồn chỉ có ba lựa chọn.","moral":"Patience and creativity help preserve traditional crafts.","moralVi":"Kiên nhẫn và sáng tạo giúp gìn giữ nghề truyền thống.","worksheet":"82814fd3-b75d-4127-aa8e-7f09b9e78357 - Sao chép.png","crop":[22,80,595,364],"questions":[{"en":"What is brocade weaving?","vi":"Dệt thổ cẩm là gì?","choices":["A modern factory job","A traditional craft","A cooking activity","A computer game"],"answer":1,"explain":"Dệt thổ cẩm là một nghề thủ công truyền thống."},{"en":"Who usually weaves brocade cloth?","vi":"Theo bài, ai thường dệt thổ cẩm?","choices":["Men and boys","Women","Tourists","Teachers"],"answer":1,"explain":"Bài đọc mô tả người phụ nữ sử dụng khung dệt gỗ."},{"en":"What do women use to weave?","vi":"Người phụ nữ dùng gì để dệt?","choices":["A metal machine","A wooden loom","A computer","A cooking pot"],"answer":1,"explain":"Wooden loom nghĩa là khung dệt gỗ."},{"en":"What are the threads like?","vi":"Các sợi chỉ như thế nào?","choices":["Black only","White only","Colorful","Transparent"],"answer":2,"explain":"Những sợi chỉ nhiều màu tạo thành hoa văn đẹp."},{"en":"What do the patterns tell us about?","vi":"Hoa văn kể về điều gì?","choices":["City life","Nature, mountains, animals or village life","Modern technology","Foreign countries"],"answer":1,"explain":"Hoa văn gợi chuyện thiên nhiên, núi rừng, loài vật và buôn làng."},{"en":"What is the brocade cloth used for?","vi":"Vải thổ cẩm dùng để làm gì?","choices":["Cars and bikes","Traditional clothes, bags and decorations","School books","Mobile phones"],"answer":1,"explain":"Vải dùng làm trang phục, túi xách và đồ trang trí."},{"en":"What does this craft show?","vi":"Nghề này thể hiện điều gì?","choices":["The talent, patience and creativity of the people","The speed of machines","The wealth of the city","The power of the government"],"answer":0,"explain":"Nghề dệt thể hiện tài năng, sự kiên nhẫn và óc sáng tạo."},{"en":"What does brocade weaving help to do?","vi":"Nghề dệt giúp làm gì?","choices":["Build new roads","Keep their culture alive","Catch more fish","Plant more trees"],"answer":1,"explain":"Nghề dệt góp phần gìn giữ văn hóa truyền thống."}],"cast":[]},{"id":"highland-statues","title":"The Tomb Statues","vi":"Tượng nhà mồ Tây Nguyên","type":"Văn hóa Tây Nguyên","grade":5,"icon":"📖","paras":[["Tomb statues are special wooden statues placed around the tomb house of ethnic minority groups in the Central Highlands. They are carved into human and animal figures, such as men, women, elephants, buffaloes or birds. The statues show respect and farewell to the deceased. They also express the belief that the spirit will have a happy journey to the next world. Each statue has a different shape and meaning. The tomb statues are a unique and important part of the cultural traditions of the Central Highlands.","Tượng nhà mồ là những bức tượng gỗ đặc biệt được đặt xung quanh nhà mồ của các dân tộc thiểu số ở Tây Nguyên. Chúng được tạc thành hình người và hình con vật, như đàn ông, phụ nữ, voi, trâu hoặc chim. Những bức tượng thể hiện sự tôn kính và tiễn biệt người đã khuất. Đồng thời, chúng cũng thể hiện niềm tin rằng linh hồn sẽ có một hành trình hạnh phúc đến thế giới bên kia. Mỗi bức tượng có hình dáng và ý nghĩa khác nhau. Tượng nhà mồ là một phần văn hóa độc đáo và quan trọng trong truyền thống của Tây Nguyên."]],"words":86,"source":"Phiếu học tập do người dùng cung cấp","adaptation":"Nội dung được nhập từ phiếu học tập đính kèm. Câu hỏi được chuẩn hóa thành bốn lựa chọn; bổ sung phương án nhiễu ở những câu nguồn chỉ có ba lựa chọn.","moral":"Respect cultural traditions and the memories of those who came before us.","moralVi":"Tôn trọng truyền thống văn hóa và tưởng nhớ người đi trước.","worksheet":"82814fd3-b75d-4127-aa8e-7f09b9e78357(2).png","crop":[20,79,594,365],"questions":[{"en":"What are tomb statues?","vi":"Tượng nhà mồ là gì?","choices":["Stone buildings","Special wooden statues","Modern paintings","Musical instruments"],"answer":1,"explain":"Tượng nhà mồ là các bức tượng gỗ đặc biệt."},{"en":"Where are the tomb statues placed?","vi":"Tượng được đặt ở đâu?","choices":["Around the tomb house","Inside the classroom","In front of the city gate","On the beach"],"answer":0,"explain":"Tượng được đặt quanh nhà mồ."},{"en":"What are the statues carved into?","vi":"Tượng được tạc thành hình gì?","choices":["Only human figures","Only animal figures","Human and animal figures","Only tree shapes"],"answer":2,"explain":"Tượng có cả hình người và hình con vật."},{"en":"Which animals are mentioned in the passage?","vi":"Những con vật nào được nhắc đến?","choices":["Tigers and lions","Elephants, buffaloes or birds","Cats and dogs","Fish and dolphins"],"answer":1,"explain":"Bài đọc nêu voi, trâu và chim."},{"en":"What do the statues show?","vi":"Tượng thể hiện điều gì?","choices":["A new festival","Respect and farewell to the deceased","A modern lifestyle","A rich harvest"],"answer":1,"explain":"Tượng thể hiện sự tôn kính và tiễn biệt người đã khuất."},{"en":"What is the belief about the spirit?","vi":"Niềm tin về linh hồn là gì?","choices":["It will stay in the village","It will have a happy journey to the next world","It will become a farmer","It will return the next day"],"answer":1,"explain":"Theo niềm tin được mô tả, linh hồn có hành trình hạnh phúc đến thế giới bên kia."},{"en":"Do all the statues have the same shape and meaning?","vi":"Tất cả tượng có giống nhau không?","choices":["Yes, all the same","No, each statue is different","Only the human statues are different","They are all round"],"answer":1,"explain":"Mỗi tượng có hình dáng và ý nghĩa khác nhau."},{"en":"What are the tomb statues?","vi":"Tượng nhà mồ có vai trò gì?","choices":["A unique and important part of cultural traditions","A modern tourist service","A type of food","A musical instrument"],"answer":0,"explain":"Đây là một phần độc đáo và quan trọng của truyền thống văn hóa."}],"cast":[]},{"id":"highland-gong","title":"The Echoing Gong Culture","vi":"Cồng chiêng Tây Nguyên","type":"Văn hóa Tây Nguyên","grade":5,"icon":"📖","paras":[["The gong culture of the Central Highlands is a special cultural treasure of Vietnam. For a long time, ethnic minority groups have used gongs in festivals, village meetings, and important ceremonies. The sound of the gong is strong, deep, and echoing. People play the gongs together to create beautiful rhythms. The gong is not only a musical instrument but also a symbol of community spirit. Today, the gong culture is carefully preserved as an important heritage of the Central Highlands.","Không gian văn hóa cồng chiêng Tây Nguyên là một kho tàng văn hóa đặc biệt của Việt Nam. Từ lâu, các dân tộc thiểu số đã sử dụng cồng chiêng trong lễ hội, họp làng và những nghi lễ quan trọng. Âm thanh cồng chiêng vang vọng, mạnh mẽ và sâu lắng. Mọi người cùng hòa tấu để tạo nên những nhịp điệu đẹp. Cồng chiêng không chỉ là một nhạc cụ mà còn là biểu tượng của tinh thần cộng đồng. Ngày nay, văn hóa cồng chiêng đang được gìn giữ như một di sản quan trọng của Tây Nguyên."]],"words":80,"source":"Phiếu học tập do người dùng cung cấp","adaptation":"Nội dung được nhập từ phiếu học tập đính kèm. Câu hỏi được chuẩn hóa thành bốn lựa chọn; bổ sung phương án nhiễu ở những câu nguồn chỉ có ba lựa chọn.","moral":"Making music together strengthens community spirit.","moralVi":"Cùng hòa nhạc góp phần gắn kết cộng đồng.","worksheet":"8cf23243-d010-429f-80f2-fba7d12bcdf1.png","crop":[26,95,853,540],"questions":[{"en":"What is the gong culture of the Central Highlands?","vi":"Văn hóa cồng chiêng Tây Nguyên là gì?","choices":["A cultural treasure","A school subject","A kind of food","A sport game"],"answer":0,"explain":"Đó là một kho tàng văn hóa đặc biệt của Việt Nam."},{"en":"When are gongs often used?","vi":"Khi nào cồng chiêng thường được sử dụng?","choices":["In festivals and ceremonies","In supermarkets","In computer rooms","On fishing boats"],"answer":0,"explain":"Cồng chiêng được dùng trong lễ hội và nghi lễ."},{"en":"How does the sound of the gong feel?","vi":"Âm thanh cồng chiêng như thế nào?","choices":["Strong, deep, and echoing","Soft like paper","Silent and dark","Tiny and weak"],"answer":0,"explain":"Âm thanh mạnh mẽ, sâu lắng và vang vọng."},{"en":"What do people create when playing together?","vi":"Mọi người tạo nên điều gì khi hòa tấu?","choices":["Beautiful rhythms","Tall buildings","Plastic toys","New roads"],"answer":0,"explain":"Mọi người tạo nên những nhịp điệu đẹp."},{"en":"What is a gong?","vi":"Cồng chiêng là gì?","choices":["A musical instrument","A cooking pot","A school bag","A flower vase"],"answer":0,"explain":"Gong là một nhạc cụ."},{"en":"What does the gong symbolize?","vi":"Cồng chiêng tượng trưng cho điều gì?","choices":["Community spirit","City traffic","Modern machines","Private secrets"],"answer":0,"explain":"Cồng chiêng tượng trưng cho tinh thần cộng đồng."},{"en":"Why is the gong culture preserved today?","vi":"Vì sao văn hóa này được gìn giữ?","choices":["It is an important heritage","It is made of plastic","It is easy to throw away","It is only a toy"],"answer":0,"explain":"Đây là một di sản quan trọng cần được gìn giữ."},{"en":"Where does gong culture belong?","vi":"Văn hóa cồng chiêng thuộc về đâu?","choices":["The Central Highlands","The ocean floor","A desert country","The moon"],"answer":0,"explain":"Bài đọc nói về văn hóa cồng chiêng Tây Nguyên."}],"cast":[]},{"id":"highland-stone","title":"The Ancient Stone Xylophone","vi":"Đàn đá Tây Nguyên","type":"Văn hóa Tây Nguyên","grade":5,"icon":"📖","paras":[["The stone xylophone, or đàn đá, is one of the oldest musical instruments in Vietnam. It is made of carefully chosen stone bars with different sizes. When people gently strike the stones with small mallets, the instrument creates clear and interesting sounds. Many people believe the stone xylophone has been part of life in the Central Highlands for a very long time. Today, it is not only a musical instrument but also a precious cultural treasure. Listening to the stone xylophone helps us feel the beauty of ancient music.","Đàn đá là một trong những nhạc cụ cổ xưa nhất của Việt Nam. Nhạc cụ này được làm từ những thanh đá được lựa chọn cẩn thận với kích thước khác nhau. Khi người ta dùng dùi nhỏ gõ nhẹ vào các thanh đá, đàn sẽ tạo ra những âm thanh trong trẻo và thú vị. Nhiều người tin rằng đàn đá đã gắn bó với đời sống ở Tây Nguyên từ rất lâu. Ngày nay, đàn đá không chỉ là một nhạc cụ mà còn là một báu vật văn hóa quý giá. Lắng nghe tiếng đàn đá giúp chúng ta cảm nhận vẻ đẹp của âm nhạc cổ xưa."]],"words":89,"source":"Phiếu học tập do người dùng cung cấp","adaptation":"Nội dung được nhập từ phiếu học tập đính kèm. Câu hỏi được chuẩn hóa thành bốn lựa chọn; bổ sung phương án nhiễu ở những câu nguồn chỉ có ba lựa chọn.","moral":"Listen carefully and treasure traditional music.","moralVi":"Lắng nghe và trân trọng âm nhạc truyền thống.","worksheet":"e5d9c5e9-67bf-47ac-9240-6c3aa0d60bd0.png","crop":[27,97,848,500],"questions":[{"en":"What is đàn đá?","vi":"Đàn đá là gì?","choices":["A stone xylophone","A bamboo basket","A type of soup","A painting tool"],"answer":0,"explain":"Đàn đá là nhạc cụ stone xylophone."},{"en":"What is the instrument made of?","vi":"Nhạc cụ được làm từ gì?","choices":["Stone bars","Paper sheets","Iron chains","Cotton ropes"],"answer":0,"explain":"Đàn được làm từ những thanh đá."},{"en":"How do people play đàn đá?","vi":"Mọi người chơi đàn đá thế nào?","choices":["By striking the stones with small mallets","By blowing into it","By shaking it in water","By pulling long strings"],"answer":0,"explain":"Người chơi dùng dùi nhỏ gõ nhẹ vào thanh đá."},{"en":"What kind of sound does đàn đá make?","vi":"Đàn đá tạo ra âm thanh thế nào?","choices":["Clear and interesting sounds","No sound at all","Only very loud noise","Only animal sounds"],"answer":0,"explain":"Âm thanh trong trẻo và thú vị."},{"en":"How old is đàn đá?","vi":"Đàn đá cổ như thế nào?","choices":["It is one of the oldest musical instruments in Vietnam","It was invented yesterday","It is a modern machine","It is brand new every year"],"answer":0,"explain":"Bài đọc nói đây là một trong những nhạc cụ cổ xưa nhất Việt Nam."},{"en":"Where has đàn đá been part of life for a long time?","vi":"Đàn đá gắn bó với đời sống ở đâu?","choices":["The Central Highlands","Outer space","Deep under the sea","A snowy island"],"answer":0,"explain":"Đàn đá gắn bó với đời sống Tây Nguyên."},{"en":"What is đàn đá today?","vi":"Ngày nay đàn đá là gì?","choices":["A precious cultural treasure","A plastic toy","A city bus","A sports uniform"],"answer":0,"explain":"Đàn đá còn là báu vật văn hóa quý giá."},{"en":"What can listening to đàn đá help us feel?","vi":"Nghe đàn đá giúp ta cảm nhận điều gì?","choices":["The beauty of ancient music","The heat of summer","The taste of candy","The speed of cars"],"answer":0,"explain":"Tiếng đàn giúp ta cảm nhận vẻ đẹp của âm nhạc cổ xưa."}],"cast":[]},{"id":"highland-rice-mountain","title":"The Legend of Rice Pot Mountain","vi":"Sự tích Núi Nồi Cơm","type":"Văn hóa Tây Nguyên","grade":5,"icon":"📖","paras":[["Long ago, the Gie-Trieng people told a legend about Rice Pot Mountain. They said rice grains were once so large that one grain could feed a family. One day, a young woman cooked too much rice by mistake. The rice rose higher and higher until the huge pot looked like a mountain. People remembered this amazing story and named the mountain Rice Pot Mountain. Today, the story reminds children to value food and listen carefully.","Ngày xưa, người Giẻ-Triêng kể lại một truyền thuyết về Núi Nồi Cơm. Họ nói rằng hạt gạo ngày trước to đến mức chỉ một hạt cũng đủ nuôi cả gia đình. Một ngày nọ, một người phụ nữ vô tình nấu quá nhiều cơm. Hạt cơm nở cao dần, cao dần cho đến khi chiếc nồi khổng lồ trông như một ngọn núi. Người dân nhớ mãi câu chuyện tuyệt vời này và đặt tên ngọn núi là Núi Nồi Cơm. Ngày nay, câu chuyện nhắc nhở các em hãy biết quý trọng thức ăn và luôn lắng nghe cẩn thận."]],"words":75,"source":"Phiếu học tập do người dùng cung cấp","adaptation":"Nội dung được nhập từ phiếu học tập đính kèm. Câu hỏi được chuẩn hóa thành bốn lựa chọn; bổ sung phương án nhiễu ở những câu nguồn chỉ có ba lựa chọn.","moral":"Value food and listen carefully.","moralVi":"Quý trọng thức ăn và lắng nghe cẩn thận.","worksheet":"40c38692-9192-4ece-bd67-01beec5a858e.png","crop":[19,94,1176,430],"questions":[{"en":"Who told the legend about Rice Pot Mountain?","vi":"Ai kể truyền thuyết về Núi Nồi Cơm?","choices":["The Gie-Trieng people","Tourists from the city","Scientists","A king"],"answer":0,"explain":"Theo phiếu học tập, người Giẻ-Triêng kể truyền thuyết này."},{"en":"How large were the rice grains in the legend?","vi":"Hạt gạo trong truyền thuyết to thế nào?","choices":["Very small","As big as a stone","One grain could feed a family","As small as a seed"],"answer":2,"explain":"Một hạt gạo đã có thể nuôi cả gia đình."},{"en":"How many grains were needed to feed a family?","vi":"Cần bao nhiêu hạt để nuôi một gia đình?","choices":["Many grains","Ten grains","One grain","A hundred grains"],"answer":2,"explain":"Theo truyền thuyết, chỉ cần một hạt."},{"en":"Who cooked too much rice by mistake?","vi":"Ai vô tình nấu quá nhiều cơm?","choices":["An old man","A young woman","A child","A village chief"],"answer":1,"explain":"Một người phụ nữ trẻ đã vô tình nấu quá nhiều cơm."},{"en":"Why did the rice rise higher and higher?","vi":"Vì sao cơm nở cao dần?","choices":["Because of strong wind","Because the pot was magical","Because the woman cooked too much rice","Because it started to rain"],"answer":2,"explain":"Trong truyện, người phụ nữ nấu quá nhiều cơm."},{"en":"What did the huge pot look like?","vi":"Chiếc nồi khổng lồ trông như gì?","choices":["A house","A boat","A mountain","A tree"],"answer":2,"explain":"Chiếc nồi trông như một ngọn núi."},{"en":"What is the mountain called?","vi":"Ngọn núi được đặt tên là gì?","choices":["Ngoc Linh Mountain","Rice Pot Mountain","Elephant Mountain","Cloud Mountain"],"answer":1,"explain":"Ngọn núi được gọi là Rice Pot Mountain: Núi Nồi Cơm."},{"en":"What does the story remind children to do?","vi":"Câu chuyện nhắc trẻ em điều gì?","choices":["Buy more food","Value food and listen carefully","Travel to the city","Cook quickly"],"answer":1,"explain":"Bài học là quý trọng thức ăn và lắng nghe cẩn thận."}],"cast":[]},{"id":"highland-festival","title":"The New Rice Festival","vi":"Lễ hội mừng lúa mới","type":"Văn hóa Tây Nguyên","grade":5,"icon":"📖","paras":[["The New Rice Festival is an important celebration in many Central Highlands villages. After the harvest season, villagers gather to thank heaven, earth, and nature for a good crop. They prepare fresh rice, traditional food, and jars of water or rice drink for the ceremony. Elders pray for health, peace, and another successful harvest. After that, everyone eats, sings, dances, and shares joy together. The festival shows gratitude, unity, and love for the land.","Lễ hội mừng lúa mới là một ngày hội quan trọng ở nhiều buôn làng Tây Nguyên. Sau mùa gặt, người dân cùng nhau tạ ơn trời đất và thiên nhiên vì một vụ mùa tốt đẹp. Họ chuẩn bị gạo mới, các món ăn truyền thống và những ché nước hoặc rượu cần cho nghi lễ. Già làng cầu mong sức khỏe, bình yên và một mùa lúa bội thu tiếp theo. Sau đó, mọi người cùng ăn uống, ca hát, nhảy múa và chia sẻ niềm vui. Lễ hội thể hiện lòng biết ơn, tinh thần đoàn kết và tình yêu với đất đai."]],"words":74,"source":"Phiếu học tập do người dùng cung cấp","adaptation":"Nội dung được nhập từ phiếu học tập đính kèm. Câu hỏi được chuẩn hóa thành bốn lựa chọn; bổ sung phương án nhiễu ở những câu nguồn chỉ có ba lựa chọn.","moral":"Be thankful for the harvest and care for the land together.","moralVi":"Biết ơn mùa màng và cùng nhau yêu quý đất đai.","worksheet":"e610c095-284e-4763-907e-858f32ec1e61(1).png","crop":[23,103,827,526],"questions":[{"en":"What is the New Rice Festival for?","vi":"Vì sao tổ chức lễ hội mừng lúa mới?","choices":["To thank for a good harvest","To build a new house","To sell clothes","To learn swimming"],"answer":0,"explain":"Lễ hội bày tỏ lòng biết ơn vì vụ mùa tốt đẹp."},{"en":"When do villagers celebrate it?","vi":"Người dân tổ chức khi nào?","choices":["Before planting rice","After the harvest season","During a storm","At midnight only"],"answer":1,"explain":"Lễ hội diễn ra sau mùa gặt."},{"en":"What do villagers prepare?","vi":"Người dân chuẩn bị những gì?","choices":["New rice and traditional food","Cars and machines","School books","Plastic toys"],"answer":0,"explain":"Họ chuẩn bị gạo mới và món ăn truyền thống."},{"en":"Who prays during the ceremony?","vi":"Ai cầu nguyện trong nghi lễ?","choices":["Tourists","Shopkeepers","Elders","Drivers"],"answer":2,"explain":"Già làng cầu mong điều tốt lành."},{"en":"What do elders pray for?","vi":"Già làng cầu mong điều gì?","choices":["Health, peace, and a good harvest","A new airport","More traffic","Bigger cities"],"answer":0,"explain":"Họ cầu mong sức khỏe, bình yên và mùa màng tốt tươi."},{"en":"What do people do after the ceremony?","vi":"Mọi người làm gì sau nghi lễ?","choices":["Eat, sing, and dance together","Go to sleep immediately","Leave the village forever","Build a bridge"],"answer":0,"explain":"Mọi người ăn uống, ca hát và nhảy múa cùng nhau."},{"en":"What does the festival show?","vi":"Lễ hội thể hiện điều gì?","choices":["Gratitude and unity","Anger and noise","City life only","A sports competition"],"answer":0,"explain":"Lễ hội thể hiện lòng biết ơn và đoàn kết."},{"en":"What do villagers love through the festival?","vi":"Người dân thể hiện tình yêu với điều gì?","choices":["The land","Television","The supermarket","The airport"],"answer":0,"explain":"Lễ hội thể hiện tình yêu đối với đất đai."}],"cast":[]},{"id":"highland-damsan","title":"The Epic of Dam San","vi":"Sử thi Đam San","type":"Văn hóa Tây Nguyên","grade":5,"icon":"📖","paras":[["The Epic of Dam San is a famous story of the Central Highlands. Dam San is remembered as a strong and brave hero who wanted to protect his village and bring honor to his people. In the story, he overcomes many challenges and wins great victories. The epic also describes the beauty of village life, the Rong house, festivals, and the spirit of the community. Today, people still tell the story to remember courage, wisdom, and traditional values.","Sử thi Đam San là một câu chuyện nổi tiếng của Tây Nguyên. Đam San được nhớ đến như một người anh hùng mạnh mẽ và dũng cảm, luôn muốn bảo vệ buôn làng và mang lại vinh dự cho dân tộc mình. Trong câu chuyện, chàng vượt qua nhiều thử thách và giành được những chiến thắng lớn. Sử thi cũng miêu tả vẻ đẹp của đời sống buôn làng, nhà Rông, lễ hội và tinh thần cộng đồng. Ngày nay, mọi người vẫn kể lại câu chuyện để nhắc nhớ về lòng dũng cảm, trí tuệ và các giá trị truyền thống."]],"words":78,"source":"Phiếu học tập do người dùng cung cấp","adaptation":"Nội dung được nhập từ phiếu học tập đính kèm. Câu hỏi được chuẩn hóa thành bốn lựa chọn; bổ sung phương án nhiễu ở những câu nguồn chỉ có ba lựa chọn.","moral":"Remember courage, wisdom, and the value of community.","moralVi":"Ghi nhớ lòng dũng cảm, trí tuệ và giá trị cộng đồng.","worksheet":"image-edit-target-d1f240aba1dd9b2f.png","crop":[23,102,825,552],"questions":[{"en":"What is The Epic of Dam San?","vi":"Sử thi Đam San là gì?","choices":["A famous story of the Central Highlands","A new television show","A city map","A recipe book"],"answer":0,"explain":"Đây là một câu chuyện nổi tiếng của Tây Nguyên trong phiếu học tập."},{"en":"Who is Dam San?","vi":"Đam San là ai?","choices":["A school teacher","A strong and brave hero","A shop owner","A fisherman"],"answer":1,"explain":"Đam San được miêu tả là người anh hùng mạnh mẽ và dũng cảm."},{"en":"What did Dam San want to protect?","vi":"Đam San muốn bảo vệ điều gì?","choices":["His village","A train station","A supermarket","A football field"],"answer":0,"explain":"Chàng muốn bảo vệ buôn làng."},{"en":"What does he win in the story?","vi":"Chàng giành được gì trong truyện?","choices":["Great victories","Plastic toys","A bus ticket","A computer game"],"answer":0,"explain":"Chàng vượt thử thách và giành những chiến thắng lớn."},{"en":"What else does the epic describe?","vi":"Sử thi còn miêu tả điều gì?","choices":["Village life and the Rong house","Ocean animals only","Airplanes and robots only","Tall city buildings"],"answer":0,"explain":"Phiếu nhắc tới đời sống buôn làng và nhà Rông."},{"en":"What spirit is shown in the story?","vi":"Câu chuyện thể hiện tinh thần gì?","choices":["Community spirit","Laziness","Fear of learning","Silence only"],"answer":0,"explain":"Sử thi thể hiện tinh thần cộng đồng."},{"en":"Why do people still tell the story today?","vi":"Vì sao ngày nay vẫn kể câu chuyện?","choices":["To remember courage, wisdom, and traditions","To sell food","To build roads","To find treasure"],"answer":0,"explain":"Câu chuyện nhắc nhớ lòng dũng cảm, trí tuệ và truyền thống."},{"en":"What kind of values does the story teach?","vi":"Câu chuyện dạy những giá trị gì?","choices":["Traditional values","Shopping habits","Racing skills","Video game skills"],"answer":0,"explain":"Câu chuyện giúp ghi nhớ những giá trị truyền thống."}],"cast":[]},{"id":"highland-ngoclinh","title":"Ngoc Linh Mountain","vi":"Núi Ngọc Linh","type":"Văn hóa Tây Nguyên","grade":5,"icon":"📖","paras":[["Ngọc Linh is a high and majestic mountain in the Central Highlands. It is famous for the rare Ngọc Linh ginseng, a precious medicinal plant that has many health benefits. The mountain is also home to diverse forests, many animals and rare plants. People work together to protect the forest and conserve Ngọc Linh ginseng, so that the natural treasures of Núi Ngọc Linh can be preserved for future generations.","Núi Ngọc Linh là một ngọn núi cao và hùng vĩ ở Tây Nguyên. Nơi đây nổi tiếng với sâm Ngọc Linh – một loại dược liệu quý hiếm có nhiều lợi ích cho sức khỏe. Ngọn núi còn là nơi có rừng nguyên sinh đa dạng, nhiều loài động vật và thực vật quý hiếm. Người dân cùng nhau bảo vệ rừng và gìn giữ sâm Ngọc Linh, để những giá trị thiên nhiên quý báu của núi Ngọc Linh được giữ gìn cho các thế hệ mai sau."]],"words":70,"source":"Phiếu học tập do người dùng cung cấp","adaptation":"Nội dung được nhập từ phiếu học tập đính kèm. Câu hỏi được chuẩn hóa thành bốn lựa chọn; bổ sung phương án nhiễu ở những câu nguồn chỉ có ba lựa chọn.","moral":"Protect forests and conserve natural treasures for future generations.","moralVi":"Bảo vệ rừng và gìn giữ tài nguyên thiên nhiên cho thế hệ mai sau.","worksheet":"2afc2e29-8caf-4feb-ac5f-2d6477311b94(1).png","crop":[9,80,565,359],"questions":[{"en":"What is Núi Ngọc Linh famous for?","vi":"Núi Ngọc Linh nổi tiếng với gì?","choices":["A beautiful beach","Rare ginseng","An ancient castle","A large lake"],"answer":1,"explain":"Núi nổi tiếng với sâm Ngọc Linh quý hiếm."},{"en":"What is Ngọc Linh ginseng?","vi":"Sâm Ngọc Linh là gì?","choices":["A type of animal","A precious medicinal plant","A kind of stone","A traditional house"],"answer":1,"explain":"Sâm Ngọc Linh là một loại dược liệu quý."},{"en":"What else can be found in Núi Ngọc Linh?","vi":"Núi còn có những gì?","choices":["Many buildings and roads","Diverse forests, many animals and rare plants","A big harbor","A shopping center"],"answer":1,"explain":"Bài đọc nói tới rừng đa dạng, động vật và thực vật quý hiếm."},{"en":"Why is Ngọc Linh ginseng important?","vi":"Vì sao sâm Ngọc Linh quan trọng?","choices":["It is a type of food","It has many health benefits","It can be used to build houses","It is a musical instrument"],"answer":1,"explain":"Theo bài đọc, sâm có nhiều lợi ích cho sức khỏe."},{"en":"What do people do to protect Núi Ngọc Linh?","vi":"Mọi người làm gì để bảo vệ núi?","choices":["Cut down more trees","Work together to protect the forest","Build more factories","Hunt more animals"],"answer":1,"explain":"Mọi người cùng bảo vệ rừng và gìn giữ sâm."},{"en":"What kind of forest is in Núi Ngọc Linh?","vi":"Trên núi có loại rừng nào?","choices":["A mangrove forest","A pine forest near the sea","A tropical rainforest","A primary forest"],"answer":3,"explain":"Bản dịch trong phiếu nhắc tới rừng nguyên sinh: primary forest."},{"en":"What should we do with the natural treasures?","vi":"Ta nên làm gì với những giá trị thiên nhiên?","choices":["Use them quickly","Sell them to other countries","Preserve them for future generations","Keep them a secret"],"answer":2,"explain":"Cần gìn giữ cho những thế hệ mai sau."},{"en":"What is the main message of the passage?","vi":"Thông điệp chính của đoạn văn là gì?","choices":["The mountain is a good place for shopping","We should protect the forest and conserve nature","People should move to the city","The mountain is only for tourists"],"answer":1,"explain":"Thông điệp là bảo vệ rừng và bảo tồn thiên nhiên."}],"cast":[]}];
