const ST_IMAGE_URLS=Object.fromEntries(Object.entries(ST_IMAGES).map(([key,meta])=>[key,tpImageUrl(meta.uri)]));
for(const [key,meta] of Object.entries(ST_IMAGES))document.documentElement.style.setProperty("--st-"+key,'url("'+ST_IMAGE_URLS[key]+'")');
// Thư viện truyện: chỉ bổ sung dữ liệu mới; giữ nguyên 50 truyện và mọi API gốc.
const stCulture=ST_CULTURE;
for(const s of stCulture)if(!window.EMBEDDED_DATA.content.stories.some(x=>x.id===s.id))window.EMBEDDED_DATA.content.stories.push(s);
const stUi={quiz:null,answers:{},returnFocus:null};
function stArt(s,small=false){const a=ST_ART[s.id];if(a){const [key,x,y,w,h]=a,meta=ST_IMAGES[key];return `<div class="st-art ${small?'st-thumb':''}" role="img" aria-label="Minh họa ${esc(s.vi)}"><svg viewBox="${x} ${y} ${w} ${h}" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><image href="${esc(ST_IMAGE_URLS[key])}" width="${meta.w}" height="${meta.h}"/></svg></div>`}return `<div class="st-composed ${small?'st-thumb':''}" role="img" aria-label="Minh họa các nhân vật truyện ${esc(s.vi)}"><span class="st-sun"></span><span class="st-hills"></span>${(s.cast||[s.image]).slice(0,4).map((src,i)=>`<img src="${esc(ASSET_URLS[src]||src)}" class="st-character st-character-${i}" alt="" loading="lazy">`).join('')}</div>`}
function stShell(body){const nav=[['home','🏠','Trang chủ'],['vocab','📖','Từ vựng'],['games','✏️','Luyện tập'],['evaluation','📊','Góc tiến bộ'],['ranking','🏆','Thành tích'],['stories','📚','Kể chuyện bản làng'],['grammar','📗','Cấu trúc & ngữ pháp'],['lessons','💬','Giao tiếp lớp học'],['settings','⚙️','Cài đặt'],['speaking','🤖','Luyện nói cùng rô-bốt'],['teacher','👩‍🏫','Góc giáo viên']];return `<div class="st-app"><aside class="st-sidebar"><button class="st-brand" onclick="goto('home')" aria-label="Đại Ngàn Song Ngữ – Trang chủ"></button><nav aria-label="Điều hướng chính">${nav.map(([id,icon,name])=>`<button class="${id==='stories'?'active':''}" onclick="goto('${id}')" ${id==='stories'?'aria-current="page"':''}>${tpIcon(icon)}<span>${name}</span></button>`).join('')}</nav></aside><main class="st-main"><header class="st-banner"><h1 class="st-sr">Kể chuyện bản làng</h1><p class="st-sr">Những câu chuyện hay – Bài học ý nghĩa – Song ngữ Anh Việt</p></header>${body}</main><button class="st-help" onclick="stHelp()">${stRobotImage()}<b>Em cần giúp?</b></button></div>`}
function stRobotImage(){return `<svg class="st-robot" role="img" aria-label="Bạn Rô-bốt hướng dẫn" viewBox="535 450 235 208"><image href="${esc(ST_IMAGE_URLS['highland-damsan'])}" width="1055" height="1491"/></svg>`}
function stHelp(){robot('Cùng khám phá câu chuyện!',`<p>Chọn truyện ở bên trái. Em đọc bản Anh ở hàng trên và bản Việt ở hàng dưới, chạm từ tiếng Anh để tra nghĩa.</p><p>Bấm <b>Tìm hiểu câu truyện</b> để trả lời câu hỏi. Nếu chưa đúng, mình sẽ nhận xét lựa chọn và giải thích để em thử lại.</p>`,false)}
function stWords(text){return text.split(/(\s+)/).map(w=>!w.trim()?w:`<button onclick="wordInfo(${esc(JSON.stringify(w.replace(/^[^a-z]+|[^a-z]+$/gi,'')))})">${esc(w)}</button>`).join('')}
function stStory(){const s=state.data.stories[state.story]||state.data.stories[0],all=state.data.stories,order=stCulture.map(x=>x.id);const sorted=all.map((x,i)=>({x,i})).sort((a,b)=>(order.indexOf(a.x.id)<0?100+a.i:order.indexOf(a.x.id))-(order.indexOf(b.x.id)<0?100+b.i:order.indexOf(b.x.id)));const term=state.storySearch.toLocaleLowerCase('vi');const arr=sorted.filter(({x})=>(`${x.title} ${x.vi}`.toLocaleLowerCase('vi').includes(term)));const status=readState()[readingIdentity()]||{},pages=Math.max(1,Math.ceil(s.paras.length/2));state.storyPart=Math.max(0,Math.min(state.storyPart,pages-1));const paragraphs=state.storyMode==='full'?s.paras:s.paras.slice(state.storyPart*2,state.storyPart*2+2);return `<section class="st-library"><aside class="st-shelf"><h2>📚 Thư viện truyện</h2><div class="st-shelf-inner"><label class="st-search">🔎<input class="story-search" placeholder="Tìm truyện..." aria-label="Tìm truyện tiếng Anh hoặc tiếng Việt" value="${esc(state.storySearch)}" oninput="searchStories(this)"><button onclick="state.storySearch='';render()" aria-label="Xóa tìm kiếm">×</button></label><p class="st-count">${arr.length} truyện · ${all.filter(x=>status[x.id]?.read).length} đã đọc</p><div class="st-covers">${arr.map(({x,i})=>`<button class="st-cover ${i===state.story?'selected':''}" onclick="selectStory(${i})" ${i===state.story?'aria-current="true"':''}>${stArt(x,true)}<b>${esc(x.title)}</b><small>${esc(x.vi)}</small>${status[x.id]?.read?'<span>✓ Đã đọc</span>':''}</button>`).join('')||'<p>Chưa tìm thấy truyện. Em thử từ khóa khác nhé.</p>'}</div></div></aside><article class="st-reader picture-book"><div class="st-title"><span>📖</span><div><h2>${esc(s.title)}</h2><p>${esc(s.vi)}</p></div><button class="st-speaker" aria-label="Nghe toàn bộ truyện" onclick="say(${esc(JSON.stringify(s.paras.map(p=>p[0]).join(' ')))})">🔊</button></div>${stArt(s)}<div class="st-tools"><button onclick="state.storyMode='full';render()" aria-pressed="${state.storyMode==='full'}">Toàn truyện</button><button onclick="state.storyMode='pages';render()" aria-pressed="${state.storyMode==='pages'}">Lật trang</button><button onclick="state.readTranslation=!state.readTranslation;render()">${state.readTranslation?'Ẩn':'Hiện'} bản dịch</button><button aria-label="Giảm cỡ chữ" onclick="state.storyFont=Math.max(16,state.storyFont-1);render()">A−</button><button aria-label="Tăng cỡ chữ" onclick="state.storyFont=Math.min(27,state.storyFont+1);render()">A+</button></div><div class="st-reading" style="--st-font:${state.storyFont}px">${paragraphs.map((p,i)=>`<section class="st-pair ${state.readTranslation?'':'st-en-only'}"><div class="st-en" lang="en"><b class="st-language">EN</b><p>${stWords(p[0])}</p><button class="st-paragraph-speaker" onclick="say(${esc(JSON.stringify(p[0]))})" aria-label="Nghe đoạn ${state.storyMode==='full'?i+1:state.storyPart*2+i+1}">🔊 Nghe đoạn ${state.storyMode==='full'?i+1:state.storyPart*2+i+1}</button></div>${state.readTranslation?`<div class="st-vi" lang="vi"><b class="st-language">VI</b><p>${esc(p[1])}</p></div>`:''}</section>`).join('')}</div>${state.storyMode==='pages'?`<div class="st-pages"><button ${state.storyPart===0?'disabled':''} onclick="turnStory(-1)">← Trước</button><b>Trang ${state.storyPart+1}/${pages}</b><button ${state.storyPart===pages-1?'disabled':''} onclick="turnStory(1)">Sau →</button></div>`:''}<section class="st-moral"><h3>🌱 Bài học từ câu chuyện</h3><b>${esc(s.moral)}</b>${state.readTranslation?`<p>${esc(s.moralVi)}</p>`:''}</section><div class="st-actions"><button class="st-primary" onclick="say(${esc(JSON.stringify(paragraphs.map(p=>p[0]).join(' ')))})">🔊 Nghe ${state.storyMode==='full'?'truyện':'trang này'}</button><button onclick="stopSpeech()">■ Dừng đọc</button><button onclick="markStoryRead()">${status[s.id]?.read?'✓ Đã đọc':'☆ Đánh dấu đã đọc'}</button></div><div class="st-extra"><button class="st-discover" onclick="stOpenQuiz()">🔎 Tìm hiểu câu truyện <span>❯</span></button></div><details class="st-source"><summary>Về câu chuyện và học liệu</summary><p>${esc(s.source)} · ${s.words} từ tiếng Anh</p><p>${esc(s.adaptation)}</p></details></article></section>`}
function stQuestions(s){if(s.questions)return s.questions;const others=state.data.stories.filter(x=>x.id!==s.id&&x.type===s.type);const make=(en,vi,answer,choices,explain,seed)=>{const options=[answer,...choices.filter(x=>x!==answer)].slice(0,4),offset=seed%4;for(let i=0;i<offset;i++)options.push(options.shift());return {en,vi,choices:options,answer:options.indexOf(answer),explain}};return [make('What is the Vietnamese title of this story?','Tên tiếng Việt của câu chuyện này là gì?',s.vi,others.slice(0,3).map(x=>x.vi),'Câu chuyện “'+s.title+'” có tên tiếng Việt là “'+s.vi+'”.',1),make('Which lesson belongs to this story?','Đâu là bài học của câu chuyện?',s.moralVi,others.slice(0,3).map(x=>x.moralVi),'Bài học của câu chuyện: '+s.moralVi,2),...s.paras.slice(0,3).map((p,i)=>make('What does this part mean? '+p[0],'Chọn bản dịch đúng của đoạn truyện trên.',p[1],s.paras.filter(x=>x!==p).map(x=>x[1]).concat(others.map(x=>x.paras[0][1])),'Đọc lại đoạn '+(i+1)+' và đối chiếu hai cột. '+p[1],i))]}
// Hộp tương tác riêng: không thay API chấm điểm hay trò chơi đọc hiểu hiện có.
function stDialog(title,body){stCloseDialog();stUi.returnFocus=document.activeElement;const d=document.createElement('div');d.id='st-dialog';d.className='st-dialog';d.innerHTML=`<section role="dialog" aria-modal="true" aria-labelledby="st-dialog-title" tabindex="-1"><header><h2 id="st-dialog-title">${esc(title)}</h2><button onclick="stCloseDialog()" aria-label="Đóng">×</button></header>${body}</section>`;d.addEventListener('click',e=>{if(e.target===d)stCloseDialog()});d.addEventListener('keydown',e=>{if(e.key==='Escape')stCloseDialog();if(e.key==='Tab'){const f=[...d.querySelectorAll('button,input,textarea,select,[tabindex="0"]')].filter(x=>!x.disabled),a=f[0],z=f[f.length-1];if(e.shiftKey&&document.activeElement===a){e.preventDefault();z.focus()}else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus()}}});document.body.append(d);d.querySelector('section').focus()}
function stCloseDialog(){document.getElementById('st-dialog')?.remove();stUi.returnFocus?.focus?.()}
function stOpenQuiz(){const s=state.data.stories[state.story];stUi.quiz={id:s.id,questions:stQuestions(s),index:0,correct:new Set(),attempts:0};stShowQuestion()}
function stShowQuestion(){const t=stUi.quiz,q=t.questions[t.index];stDialog('Tìm hiểu câu truyện',`<div class="st-quiz"><p class="st-quiz-progress">Câu ${t.index+1}/${t.questions.length} · Đã hiểu đúng ${t.correct.size} câu</p><progress max="${t.questions.length}" value="${t.correct.size}"></progress><h3>${esc(q.en)}</h3><p>${esc(q.vi)}</p><button onclick="stReadQuestion()">🔊 Nghe câu hỏi</button><div class="st-answers">${q.choices.map((x,i)=>`<button id="st-option-${i}" onclick="stAnswer(${i})"><b>${'ABCD'[i]}</b><span>${esc(x)}</span></button>`).join('')}</div><div id="st-feedback" role="status" aria-live="polite"></div><div class="st-quiz-nav"><button ${t.index===0?'disabled':''} onclick="stUi.quiz.index--;stShowQuestion()">← Câu trước</button><button onclick="stQuizNext()">${t.index===t.questions.length-1?'Xem kết quả':'Câu tiếp theo →'}</button></div><small>Em có thể thử lại và đọc lời giải ngay tại thư viện truyện.</small></div>`)}
function stReadQuestion(){const q=stUi.quiz.questions[stUi.quiz.index];say(q.en+' '+q.choices.map((x,i)=>'ABCD'[i]+'. '+x).join('. '))}
function stAnswer(i){const t=stUi.quiz,q=t.questions[t.index],good=i===q.answer;t.attempts++;const feedback=document.getElementById('st-feedback');for(let k=0;k<4;k++){const b=document.getElementById('st-option-'+k);b.classList.toggle('is-wrong',k===i&&!good);b.classList.toggle('is-correct',k===q.answer&&good)}if(good){t.correct.add(t.index);feedback.innerHTML=`<div class="st-good">🌟 Giỏi lắm! Em đã hiểu đúng.<p>${esc(q.explain)}</p></div>`;document.querySelector('.st-quiz-progress').textContent=`Câu ${t.index+1}/${t.questions.length} · Đã hiểu đúng ${t.correct.size} câu`;document.querySelector('.st-quiz progress').value=t.correct.size}else feedback.innerHTML=`<div class="st-guide">${stFeedbackRobotImage()}<div><b>Rô-bốt nhận xét: Mình cùng đọc lại nhé!</b><p>Em chọn <b>${'ABCD'[i]}. ${esc(q.choices[i])}</b>. Lựa chọn này chưa phù hợp với nội dung bài đọc.</p><p><b>Giải thích:</b> ${esc(q.explain)}</p><p>Vì vậy, đáp án phù hợp là <b>${'ABCD'[q.answer]}. ${esc(q.choices[q.answer])}</b>. Em thử chọn lại nhé!</p></div></div>`}
function stQuizNext(){const t=stUi.quiz;if(t.index<t.questions.length-1){t.index++;stShowQuestion();return}stDialog('Em đã hoàn thành lượt tìm hiểu!',`<div class="st-result">${stRobotImage()}<h3>🌟 Đã hiểu đúng ${t.correct.size}/${t.questions.length} câu</h3><p>Em có thể trở lại câu chuyện hoặc luyện lại để nhớ lâu hơn.</p><button onclick="stOpenQuiz()">Luyện lại</button><button onclick="stCloseDialog()">Đọc tiếp câu chuyện</button></div>`)}
