function hmHome(){return `<section class="hm-home" aria-label="Trang chủ Đại Ngàn Song Ngữ"><h1 class="hm-sr">Đại Ngàn Song Ngữ – Học vui bản làng, vươn xa thế giới</h1><img class="hm-art" src="${esc(HM_HOME_URL)}" width="1672" height="941" alt="Đại Ngàn Song Ngữ: biển gỗ, học sinh và rô-bốt giữa buôn làng"><nav class="hm-hotspots" aria-label="Điều hướng trang chủ">${hmHomeActions.map(([name,x,y,w,h,action])=>`<button type="button" class="hm-hotspot" style="left:${x}%;top:${y}%;width:${w}%;height:${h}%" aria-label="${esc(name)}" title="${esc(name)}" onclick="${esc(action)}"><span class="hm-sr">${esc(name)}</span></button>`).join('')}</nav><div class="hm-honor" aria-label="Bảng vinh danh · kết quả các hồ sơ trên thiết bị">${[0,1,2].map(i=>{const row=state.leaders[i];return `<button type="button" onclick="goto('ranking')" aria-label="${row?esc(row.name)+' · '+row.stars+' sao':'Chờ ngôi sao mới'}"><b class="hm-medal">${i+1}</b>${hmHomeAvatar(row?.name)}<span class="hm-name">${row?esc(row.name):'Chờ ngôi sao mới'}</span><strong>⭐ ${row?.stars||0}</strong></button>`}).join('')}</div></section>`}
landing=hmHome;
layout=function(body){return state.page==='home'?`<div class="hm-shell">${body}</div>`:hmHomeBaseLayout(body)};


