let grFirstVisit=true;
function grSprite(crop){const [x,y,w,h]=crop;return `<svg viewBox="${x} ${y} ${w} ${h}" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><image href="${esc(GR_REFERENCE_URL)}" width="1672" height="941"/></svg>`}
function grSpeaker(){return '<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M3 9h4l5-4v14l-5-4H3z"/><path fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" d="M16 8c2 2 2 6 0 8m3-11c4 4 4 10 0 14"/></svg>'}
function grArt(x){const text=(x.topic+' '+x.pattern).toLocaleLowerCase('vi');const index=/gia đình|family|father|mother|sister|brother/.test(text)?2:/trường|class|school|student|book|lesson/.test(text)?3:/viet nam|vietnam/i.test(x.pattern)?1:/quốc tịch|quê quán/.test(x.topic)||/\?$/.test(x.pattern)?0:3;const crops=[[695,587,238,153],[1316,587,303,153],[640,770,294,150],[1270,770,350,150]],c=crops[index],[a,b,w,h]=c,id='gr-art-'+x.id;return `<svg viewBox="${a} ${b} ${w} ${h}" preserveAspectRatio="xMidYMax slice" aria-hidden="true"><defs><clipPath id="${id}"><path d="M ${a} ${b} H ${a+w-80} V ${b+80} H ${a+w} V ${b+h} H ${a} Z"/></clipPath></defs><image href="${esc(GR_REFERENCE_URL)}" width="1672" height="941" clip-path="url(#${id})"/></svg>`}
function grChangeGrade(g){state.grade=String(g);state.grammarTopic='Tất cả';state.grammarPage=0;render()}
function grGrammar(){if(grFirstVisit){grFirstVisit=false;state.grade='3';state.grammarTopic='Tất cả';state.grammarPage=0}const arr=state.data.grammar[state.grade]||[],topics=[...new Set(arr.map(x=>x.topic))],filtered=arr.filter(x=>state.grammarTopic==='Tất cả'||x.topic===state.grammarTopic),pages=Math.max(1,Math.ceil(filtered.length/10)),done=arr.filter(x=>state.progress.learned.includes(x.id)).length;state.grammarPage=Math.max(0,Math.min(state.grammarPage,pages-1));return `<nav class="gr-grades" aria-label="Chọn khối lớp">${[1,2,3,4,5].map(g=>`<button class="gr-grade gr-grade-${g} ${state.grade==g?'selected':''}" onclick="grChangeGrade(${g})" aria-pressed="${state.grade==g}"><span>⭐</span> Lớp ${g}</button>`).join('')}</nav><section class="gr-panel"><div class="gr-toolbar"><div class="gr-grade-info"><h2>📗 Lớp ${state.grade} · ${arr.length} mẫu câu</h2><p>${['Làm quen qua lời nói, đồ vật và hoạt động gần gũi.','Mở rộng từ câu ngắn đến hỏi đáp, sở hữu và vị trí.','Giao tiếp về bản thân, trường lớp, gia đình và hoạt động.','Thói quen, quá khứ, dự định và giao tiếp theo tình huống.','Mở rộng kể chuyện, kế hoạch, so sánh và nêu ý kiến.'][state.grade-1]}</p></div><label class="gr-topic" for="gr-topic">Nhóm kiến thức<select id="gr-topic" onchange="state.grammarTopic=this.value;state.grammarPage=0;render()">${['Tất cả',...topics].map(t=>`<option ${state.grammarTopic===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label><div class="gr-progress"><b>⭐ Đã học ${done}/${arr.length}</b><div role="progressbar" aria-label="Tiến độ ngữ pháp lớp ${state.grade}" aria-valuemin="0" aria-valuemax="${arr.length}" aria-valuenow="${done}"><i style="width:${arr.length?done/arr.length*100:0}%"></i></div></div></div><div class="gr-cards">${filtered.slice(state.grammarPage*10,state.grammarPage*10+10).map(x=>`<article class="gr-card" data-grammar-id="${esc(x.id)}"><div class="gr-card-visual"><div class="gr-card-art">${grArt(x)}</div><span class="gr-number gr-number-${arr.indexOf(x)%5}">${arr.indexOf(x)+1}</span><div class="gr-card-text"><span class="gr-pill">${esc(x.topic)}${x.level==='Mở rộng'?' · Mở rộng':''}</span><h3>${esc(x.pattern)}</h3><p lang="vi">${esc(x.vi)}</p></div><button class="gr-audio" aria-label="Nghe ${esc(x.example)}" onclick="say(${esc(JSON.stringify(x.example))})">${grSpeaker()}</button></div><div class="gr-card-actions"><details class="gr-rule"><summary>💡 Giải thích</summary><p>${esc(x.rule)}</p><p><b>Ví dụ:</b> ${esc(x.example)}</p></details><button onclick="practiceSentence(${esc(JSON.stringify(x.example))})">🎤 Đọc theo</button><button onclick="grammarPractice(${esc(JSON.stringify(x.id))})">✏️ Luyện tập</button><button class="${state.progress.learned.includes(x.id)?'is-learned':''}" onclick="learn(${esc(JSON.stringify(x.id))})">${state.progress.learned.includes(x.id)?'✅ Đã học':'☆ Ghi nhớ'}</button></div></article>`).join('')||'<p class="gr-empty">Chưa có mẫu câu trong nhóm đang chọn.</p>'}</div><div class="gr-pagination">${pager('grammarPage',state.grammarPage,pages)}</div><details class="gr-note"><summary>📘 Về phạm vi học liệu</summary><p>Mỗi lớp có 100 mẫu câu ứng dụng trong 20 nhóm, gồm lời nói giao tiếp và cấu trúc ngữ pháp; không có nghĩa là 100 quy tắc độc lập. Các lớp có nội dung riêng và có ôn lại kiến thức nền. Lớp 1–2 thiên về nghe, nói và làm quen; một số mục lớp 4–5 được đánh dấu mở rộng. Học liệu tự biên soạn theo định hướng chủ đề của CTGDPT 2018, chưa được xác nhận khớp từng bài của một bộ SGK.</p></details></section>`}
function grHelp(){robot('Cùng học cấu trúc và ngữ pháp!',`<p>Chọn lớp và nhóm kiến thức em muốn học. Bấm nút loa để nghe mẫu, bấm <b>Giải thích</b> để xem cách dùng.</p><p><b>Đọc theo</b> mở hướng dẫn luyện nói; <b>Luyện tập</b> mở bài điền từ của mẫu câu. Bấm <b>Ghi nhớ</b> để lưu tiến độ như trước.</p>`,false)}
function grShell(body){const nav=[['home','🏠','Trang chủ'],['vocab','📖','Từ vựng'],['games','✏️','Luyện tập'],['grammar','📚','Cấu trúc và ngữ pháp'],['evaluation','📊','Góc tiến bộ'],['ranking','🏆','Thành tích'],['settings','⚙️','Cài đặt'],['lessons','💬','Giao tiếp lớp học'],['stories','📘','Kể chuyện bản làng'],['speaking','🤖','Luyện nói cùng rô-bốt'],['teacher','👩‍🏫','Góc giáo viên']];return `<div class="gr-app"><aside class="gr-sidebar"><button class="gr-brand" onclick="goto('home')" aria-label="Đại Ngàn Song Ngữ – Trang chủ">${grSprite([0,0,265,237])}</button><nav aria-label="Điều hướng ứng dụng">${nav.map(([id,icon,label])=>`<button class="${id==='grammar'?'active':''}" onclick="goto('${id}')" ${id==='grammar'?'aria-current="page"':''}>${tpIcon(icon)}<span>${label}</span></button>`).join('')}</nav><p class="gr-motto">Cùng nhau học tốt<br>vươn tới tương lai! 🌿</p></aside><main class="gr-main"><header class="gr-banner">${grSprite([266,0,1406,313])}<h1 class="gr-sr">CẤU TRÚC &amp; NGỮ PHÁP THEO TỪNG LỚP</h1><p class="gr-sr">100 mẫu câu ứng dụng mỗi lớp · 20 nhóm chủ đề · Nghe, hiểu và thực hành</p></header>${body}</main><button class="gr-help" onclick="grHelp()" aria-label="Em cần giúp?">${grSprite([1436,849,220,80])}</button></div>`}
const grOriginalGrammar=grammar;grammar=grGrammar;
const grOriginalLayout=layout;layout=function(body){return state.page==='grammar'?grShell(body):grOriginalLayout(body)};


