function sbSvg(crop,cls='',shape=''){const [x,y,w,h]=crop;const art=`<svg x="0" y="0" width="100" height="100" viewBox="${x} ${y} ${w} ${h}" preserveAspectRatio="xMidYMid meet"><image href="${esc(HM_HOME_URL)}" width="1672" height="941"/></svg>`;return `<svg class="${cls}" viewBox="0 0 100 100" aria-hidden="true">${shape?`<defs><clipPath id="sb-mask-${shape}"><polygon points="${SB_MASKS[shape]}"/></clipPath></defs><g clip-path="url(#sb-mask-${shape})">${art}</g>`:art}</svg>`}
