const BK_COVERS={"gs1":"./assets/e348bfadde87a50ad134bc2f.webp","gs2":"./assets/86545a5cd4a02a610d933501.webp","gs3-1":"./assets/1c88c9d2456185bcc1614d27.webp","gs3-2":"./assets/d2eb14c8415df2a5610ee622.webp","gs4-1":"./assets/e083f0513ddd5274c8e269d5.webp","gs4-2":"./assets/0feab59d267c3c4e916f15e1.webp","gs5-1":"./assets/ab5850b68eecee45fa008427.webp","gs5-2":"./assets/fc3f18b8d99a42f910bb3372.webp"};
/* Kho SGK: PDF gốc được mở cạnh HTML hoặc chọn từ thiết bị; không nhúng lại 315 MB sách.
 * BK_INDEX chứa OCR tiếng Anh của tất cả 631 trang (số trang PDF, tính cả bìa).
 * OCR dùng để tìm nguồn, không phải đáp án chuẩn hay nội dung đã được AI xác minh.
 * AI dùng endpoint hiện có. Chỉ gửi tối đa 3 đoạn liên quan, không gửi toàn bộ PDF.
 */
const bkState={grade:'all',query:'',book:null,page:1,tutorGrade:'all',context:null,urls:new Map(),files:new Map(),restoreStarted:false,status:'',hits:[]};
const BK_HELP_SELECTOR='.robot-float,.vu-help,.tp-help,.st-help,.gr-help';
const bkPages=BK_INDEX.map(p=>({...p,norm:dtNorm(p.text),grade:BK_BOOKS.find(b=>b.id===p.book).grade}));
const BK_STOP=new Set('hay em minh toi ban giup hay giai thich dich nghia la gi ve cua trong sach tieng anh lop unit trang pdf tap bai lesson the a an is are am to and of in on for with what how do does i you my your me please help explain translate'.split(' '));
function bkBook(id){return BK_BOOKS.find(b=>b.id===id)}
function bkFileURL(id){return bkState.urls.get(id)||'./'+encodeURIComponent(bkBook(id).file)}
function bkPDFURL(id,page=1){return bkFileURL(id)+'#page='+Math.max(1,Math.min(bkBook(id).pages,Number(page)||1))+'&view=FitH'}
function bkGradeQuery(q){const m=dtNorm(q).match(/\b(?:lop|grade|class|tieng anh)\s*([1-5])\b/);return m?m[1]:null}
function bkRetrieve(query,options={}){const n=dtNorm(query);const explicitGrade=bkGradeQuery(query),grade=explicitGrade||options.grade||'all';const unit=n.match(/\bunit\s*(\d{1,2})\b/);const tokens=[...new Set(n.split(' ').filter(x=>x.length>1&&!BK_STOP.has(x)&&!/^\d+$/.test(x)))];const phrase=(query.match(/["“]([^"”]+)["”]/)||[])[1];const needle=dtNorm(phrase||'');let rows=bkPages.filter(p=>(grade==='all'||p.grade===Number(grade))&&(!options.book||p.book===options.book)&&(!options.page||p.page===Number(options.page)));return rows.map(p=>{let score=0;let matched=0;for(const t of tokens){if((' '+p.norm+' ').includes(' '+t+' ')){score+=Math.min(6,(p.norm.split(t).length-1))*2;matched++}}if(tokens.length&&!options.page&&matched/tokens.length<.45)return {p,score:0};if(tokens.length)score+=matched/tokens.length*10;if(needle&&p.norm.includes(needle))score+=35;if(unit){if(new RegExp('\\bunit '+unit[1]+'\\b').test(p.norm))score+=22;else if(tokens.length===0)score=0}if(options.page&&p.text.trim())score+=40;if(p.page<=6&&!options.page)score*=.35;return {p,score}}).filter(x=>x.score>0&&x.p.text.trim()).sort((a,b)=>b.score-a.score||a.p.page-b.p.page).slice(0,options.limit||6)}
function bkExcerpt(text,query,max=560){const tokens=dtNorm(query).split(' ').filter(x=>x.length>2&&!BK_STOP.has(x));const lines=String(text).split('\n');let start=lines.findIndex(l=>tokens.some(t=>dtNorm(l).includes(t)));start=Math.max(0,start-1);let excerpt=lines.slice(start).join('\n');if(excerpt.length<80)excerpt=text;return excerpt.length>max?excerpt.slice(0,max)+'…':excerpt}
function bkOpenReader(id,page=1){const book=bkBook(id);if(!book)return;bkState.book=id;bkState.page=Math.max(1,Math.min(book.pages,Math.floor(Number(page)||1)));goto('books');document.getElementById('bk-reader')?.scrollIntoView({behavior:'smooth',block:'start'})}
function bkChangePage(delta){bkOpenReader(bkState.book,bkState.page+delta)}
function bkGoPage(value){bkOpenReader(bkState.book,value)}
function bkSetGrade(value){bkState.grade=['all','1','2','3','4','5'].includes(value)?value:'all';bkState.hits=bkState.query?bkRetrieve(bkState.query,{grade:bkState.grade}):[];render()}
function bkSearchSubmit(event){event?.preventDefault();bkState.query=document.getElementById('bk-query').value.trim().slice(0,200);bkState.hits=bkState.query?bkRetrieve(bkState.query,{grade:bkState.grade,limit:8}):[];render()}
function bkClearSearch(){bkState.query='';bkState.hits=[];render()}
function bkCard(book){return `<article class="bk-card"><button type="button" class="bk-cover-button" onclick="bkOpenReader('${book.id}')" aria-label="Đọc ${book.title}"><img class="bk-cover" src="${BK_COVERS[book.id]}" alt="Bìa ${book.title} Global Success" loading="lazy"></button><div class="bk-card-body"><span class="bk-badge">Lớp ${book.grade}${book.volume?' · Tập '+book.volume:''}</span><h3>${book.title}</h3><p>${book.pages} trang PDF · ${(book.bytes/1048576).toFixed(1)} MB</p><p>${bkState.urls.has(book.id)?'✓ Đã chọn tệp trên thiết bị':'PDF gốc · đặt cùng thư mục HTML'}</p><div class="bk-card-actions"><button type="button" class="bk-btn bk-primary" onclick="bkOpenReader('${book.id}')">📖 Đọc sách</button><a class="bk-btn" href="${esc(bkPDFURL(book.id))}" target="_blank" rel="noopener">Mở PDF ↗</a></div></div></article>`}
function bkResults(){if(!bkState.query)return '';return `<section class="bk-panel" aria-label="Kết quả tìm trong sách"><h2>🔎 Kết quả cho “${esc(bkState.query)}”</h2><p class="bk-notice">Trích chữ nhận dạng tự động; có thể có lỗi hoặc thiếu chữ trong tranh. Số trang dưới đây là trang PDF, bao gồm bìa.</p><div class="bk-results">${bkState.hits.map(({p})=>`<article class="bk-hit"><h3>${esc(bkBook(p.book).title)} · Trang PDF ${p.page}</h3><p>${esc(bkExcerpt(p.text,bkState.query))}</p><div class="bk-hit-actions"><button class="bk-btn" onclick="bkOpenReader('${p.book}',${p.page})">Mở đúng trang</button><button class="bk-btn bk-primary" onclick="bkAskPage('${p.book}',${p.page})">Hỏi gia sư về trang này</button></div></article>`).join('')||'<p class="bk-empty">Chưa tìm được chữ phù hợp. Em thử một từ tiếng Anh, tên bài hoặc “Unit 1”, rồi chọn lớp nhé.</p>'}</div></section>`}
function bkReader(){const b=bkBook(bkState.book);if(!b)return '';return `<section class="bk-panel" id="bk-reader"><h2>📖 ${b.title}</h2><div class="bk-reader-controls"><button class="bk-btn" onclick="bkChangePage(-1)" ${bkState.page<=1?'disabled':''}>← Trang trước</button><label>Trang PDF <input type="number" min="1" max="${b.pages}" value="${bkState.page}" aria-label="Trang PDF cần mở" onchange="bkGoPage(this.value)"> / ${b.pages}</label><button class="bk-btn" onclick="bkGoPage(document.querySelector('#bk-reader input').value)">Đến trang</button><button class="bk-btn" onclick="bkChangePage(1)" ${bkState.page>=b.pages?'disabled':''}>Trang sau →</button><a class="bk-btn" href="${esc(bkPDFURL(b.id,bkState.page))}" target="_blank" rel="noopener">Mở ở tab riêng ↗</a><button class="bk-btn bk-primary" onclick="bkAskPage('${b.id}',${bkState.page})">✨ Hỏi gia sư trang này</button></div><iframe class="bk-pdf" title="${b.title} – trang PDF ${bkState.page}" src="${esc(bkPDFURL(b.id,bkState.page))}"></iframe><p class="bk-notice">Nếu khung đọc chưa hiện sách, bấm “Mở ở tab riêng” hoặc “Chọn các file PDF” ở trên. Trên điện thoại, trình duyệt có thể tải PDF thay vì hiển thị trong khung. Số trong ô là trang đã yêu cầu mở, không theo dõi vị trí cuộn bên trong trình xem PDF.</p></section>`}
function bkShelf(){const books=BK_BOOKS.filter(b=>bkState.grade==='all'||b.grade===Number(bkState.grade));return `<div class="bk-app"><aside class="sidebar bk-sidebar"></aside><main class="bk-main"><header class="bk-hero"><small>ĐẠI NGÀN SONG NGỮ</small><h1>KHO SÁCH TIẾNG ANH</h1><p>Cùng mở sách · Tìm bài học · Hỏi gia sư</p><div class="bk-summary"><span>📚 8 PDF · Lớp 1–5</span><span>📄 631 trang PDF gốc</span><span>🔎 Tra cứu OCR có dẫn trang</span></div></header><section class="bk-panel"><form class="bk-toolbar" onsubmit="bkSearchSubmit(event)"><label class="bk-search-label">Tìm nội dung trong sách<input id="bk-query" maxlength="200" value="${esc(bkState.query)}" placeholder="Ví dụ: school, Unit 1, Where are you from?"></label><label>Khối lớp<select onchange="bkSetGrade(this.value)"><option value="all">Tất cả lớp</option>${[1,2,3,4,5].map(g=>`<option value="${g}" ${String(g)===bkState.grade?'selected':''}>Lớp ${g}</option>`).join('')}</select></label><button class="bk-btn bk-primary" type="submit">🔎 Tìm trong sách</button>${bkState.query?'<button class="bk-btn" type="button" onclick="bkClearSearch()">Xóa tìm kiếm</button>':''}</form><div class="bk-import"><button class="bk-btn" onclick="document.getElementById('bk-files').click()">📂 Chọn các file PDF trên máy</button><input id="bk-files" type="file" accept="application/pdf,.pdf" multiple hidden onchange="bkChooseFiles(this)"><label><input class="bk-check" type="checkbox" id="bk-keep"> Lưu bản sao sách trong trình duyệt để đọc lần sau</label><button class="bk-btn" onclick="bkSetupHelp()">Cách đặt file sách</button></div><p class="bk-status" role="status">${esc(bkState.status)}</p><p class="bk-notice">Đặt 8 PDF gốc cạnh file HTML, giữ nguyên tên file, để các liên kết mở trực tiếp. Hoặc chọn sách trên máy; sách không bị tải lên mạng. Gia sư đã có chỉ mục OCR; AI tạo sinh vẫn cần kết nối máy chủ do thầy cô cấu hình.</p></section>${bkResults()}<div class="bk-grid">${books.map(bkCard).join('')}</div>${bkReader()}</main></div>`}
function bkSetupHelp(){robot('Cách đặt file sách',`<p>Đặt file HTML này và cả 8 PDF gốc trong cùng một thư mục. Giữ nguyên tên PDF như lúc tải lên:</p><ul style="font-size:12px;overflow-wrap:anywhere">${BK_BOOKS.map(b=>`<li>${esc(b.file)}</li>`).join('')}</ul><p>Bấm <b>Đọc sách</b> hoặc <b>Mở PDF</b>. Nếu trình duyệt chặn file cục bộ, dùng <b>Chọn các file PDF trên máy</b>. Khi đưa lên web, tải HTML và 8 PDF lên cùng một thư mục của máy chủ.</p>`,false);document.getElementById('robot-overlay')?.classList.add('bk-guide-overlay')}
function bkDB(){return new Promise((resolve,reject)=>{if(!window.indexedDB){reject(new Error('unsupported'));return}const r=indexedDB.open('daingan-textbooks-v1',1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('pdfs'))r.result.createObjectStore('pdfs')};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function bkStoreFile(id,file){const db=await bkDB();try{await new Promise((resolve,reject)=>{const tx=db.transaction('pdfs','readwrite');tx.objectStore('pdfs').put(file,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('quota'))})}finally{db.close()}}
function bkUseFile(id,file){const old=bkState.urls.get(id);if(old)URL.revokeObjectURL(old);bkState.files.set(id,file);bkState.urls.set(id,URL.createObjectURL(file))}
async function bkRestoreBooks(){if(bkState.restoreStarted)return;bkState.restoreStarted=true;let db;try{db=await bkDB();const found=await new Promise((resolve,reject)=>{const tx=db.transaction('pdfs','readonly'),store=tx.objectStore('pdfs');const rows=[];for(const b of BK_BOOKS){const r=store.get(b.id);r.onsuccess=()=>{if(r.result&&r.result.size===b.bytes)rows.push([b.id,r.result])}}tx.oncomplete=()=>resolve(rows);tx.onerror=()=>reject(tx.error)});for(const [id,file] of found)if(!bkState.urls.has(id))bkUseFile(id,file);if(found.length){bkState.status=`Đã khôi phục ${found.length}/8 PDF đã lưu trên trình duyệt.`;if(state.page==='books')render()}}catch{}finally{db?.close()}}
async function bkChooseFiles(input){const selected=[...input.files];const keep=document.getElementById('bk-keep').checked;let loaded=0,ignored=0,failedSave=0;for(const file of selected){const b=BK_BOOKS.find(b=>b.file===file.name);if(!b||file.size!==b.bytes){ignored++;continue}try{const header=await file.slice(0,5).text();if(header!=='%PDF-'){ignored++;continue}bkUseFile(b.id,file);loaded++;if(keep)try{await bkStoreFile(b.id,file)}catch{failedSave++}}catch{ignored++}}bkState.status=`Đã chọn ${loaded} PDF; hiện có ${bkState.urls.size}/8 sách trên thiết bị.${ignored?' '+ignored+' tệp không khớp tên/kích thước PDF gốc.':''}${failedSave?' '+failedSave+' sách chỉ dùng trong phiên này vì không lưu được trên trình duyệt.':''}`;if(state.page==='books')render()}
function bkAskPage(id,page){const p=bkPages.find(p=>p.book===id&&p.page===Number(page));if(!p)return;bkState.context={book:id,page:p.page};bkState.tutorGrade=String(bkBook(id).grade);dtToggle(true);dtSettings(false);bkSyncTutor();document.getElementById('dt-input').value=`Giải thích nội dung ${bkBook(id).title}, trang PDF ${p.page}.`;document.getElementById('dt-input').focus();dtStatus('Đã chọn trang sách làm nguồn. Em sửa câu hỏi rồi bấm Gửi nhé.')}
function bkTutorRows(query){const queryGrade=bkGradeQuery(query);const explicitPage=dtNorm(query).match(/\btrang(?: pdf)?\s*(\d{1,3})\b/);const ctx=bkState.context;const selectedContext=ctx&&(!queryGrade||Number(queryGrade)===bkBook(ctx.book).grade)&&(!explicitPage||Number(explicitPage[1])===ctx.page);if(selectedContext)return bkRetrieve(query,{book:ctx.book,page:ctx.page,grade:'all',limit:3});return bkRetrieve(query,{grade:queryGrade||bkState.tutorGrade,limit:3})}
function bkSyncTutor(){const h=document.getElementById('dn-tutor');if(!h)return;const cfg=null;if(cfg&&!cfg.querySelector('.bk-ai-disclosure')){const p=document.createElement('p');p.className='bk-ai-disclosure';p.textContent='Khi bật AI và tìm được nguồn, gửi thêm tối đa 3 trích đoạn OCR liên quan kèm tên sách, trang PDF tới máy chủ đã chọn; không gửi toàn bộ sách.';cfg.append(p)}let box=h.querySelector('.bk-tutor-source');if(!box){box=document.createElement('div');box.className='bk-tutor-source';box.innerHTML='<label for="bk-tutor-grade">Nguồn sách</label><select id="bk-tutor-grade"><option value="all">Lớp 1–5</option>'+[1,2,3,4,5].map(g=>`<option value="${g}">Lớp ${g}</option>`).join('')+'</select><button type="button" class="dt-small" id="bk-tutor-reset">Bỏ chọn trang</button><small class="bk-source-note"></small>';h.querySelector('.dt-head').after(box);box.querySelector('select').addEventListener('change',e=>{bkState.tutorGrade=e.target.value;bkState.context=null;bkSyncTutor()});box.querySelector('#bk-tutor-reset').addEventListener('click',()=>{bkState.context=null;bkSyncTutor()})}box.querySelector('select').value=bkState.tutorGrade;box.querySelector('#bk-tutor-reset').hidden=!bkState.context;box.querySelector('.bk-source-note').textContent=bkState.context?`${bkBook(bkState.context.book).title} · trang PDF ${bkState.context.page} đang được chọn`:'8 sách đã có chỉ mục OCR · mở PDF để đối chiếu chữ và tranh';const mode=h.querySelector('#dt-mode');if(mode)mode.textContent=dtConfig().enabled?'AI trực tuyến · có nguồn SGK khi tìm được':'Tra học liệu và SGK · chưa kết nối AI'}
const bkOriginalLocalAnswer=dtLocalAnswer;
dtLocalAnswer=function(query){const rows=bkTutorRows(query);const n=dtNorm(query);const wantsBook=!!bkState.context||/\b(sach|sgk|unit|trang|lop|grade|textbook)\b/.test(n);const base=bkOriginalLocalAnswer(query);if(!rows.length)return base;if(!wantsBook&&!base.source.includes('Chưa có')&&!base.source.includes('gần đúng'))return {...base,bookSources:rows.map(r=>({book:r.p.book,page:r.p.page}))};return {text:'📚 Mình tìm được nguồn trong sách của em:\n\n'+rows.slice(0,2).map(({p})=>`${bkBook(p.book).title} · Trang PDF ${p.page}\n${bkExcerpt(p.text,query,650)}`).join('\n\n')+'\n\n🔎 Đây là chữ OCR để em tra cứu, có thể nhận dạng sai; không phải đáp án hay lời giải do AI tạo ra. Em mở trang gốc để đọc cả chữ và tranh nhé. Muốn giải thích câu hỏi mở, thầy cô cần bật AI trực tuyến.',english:'',source:'Tra sách gốc · số trang PDF bao gồm bìa',bookSources:rows.map(r=>({book:r.p.book,page:r.p.page}))};};

const bkOriginalAdd=dtAdd;dtAdd=function(role,result){const box=bkOriginalAdd(role,result);if(role==='assistant'&&result.bookSources?.length){const links=document.createElement('div');links.className='bk-source-links';for(const ref of result.bookSources){const b=bkBook(ref.book);if(!b)continue;const btn=document.createElement('button');btn.type='button';btn.className='dt-small';btn.textContent=`📖 ${b.title} · PDF ${ref.page}`;btn.addEventListener('click',()=>{dtToggle(false);bkOpenReader(b.id,ref.page)});links.append(btn)}box.append(links)}return box};
const bkOriginalMode=dtMode;dtMode=function(){bkOriginalMode();bkSyncTutor()};
const bkOriginalClear=dtClear;dtClear=function(){bkState.context=null;bkOriginalClear();bkSyncTutor()};
function bkGuideOpen(){const fn=state.page==='vocab'?vuHelp:state.page==='grammar'?grHelp:state.page==='stories'?stHelp:['settings','evaluation','ranking'].includes(state.page)?tpHelp:null;if(fn)fn();else robot('Hướng dẫn thực hiện',state.page==='books'?'<p>Chọn lớp, mở bìa sách hoặc bấm <b>Đọc sách</b>. Dùng ô tìm kiếm để tìm chữ trong cả bộ sách; mỗi kết quả có liên kết mở đúng trang PDF.</p><p>Bấm <b>Hỏi gia sư trang này</b> để chọn nguồn. Gia sư nằm ở góc phải, phần hướng dẫn ở góc trái.</p><p>Nếu chưa mở được PDF, chọn lại các file gốc trên thiết bị hoặc đặt chúng cạnh file HTML.</p>':'<p>Chọn một mục trên menu trái để học. Bấm loa để nghe tiếng Anh; chọn hồ sơ để lưu kết quả như trước.</p><p><b>Kho sách Tiếng Anh</b> nằm dưới Cấu trúc và ngữ pháp. Gia sư tiếng Anh nằm ở góc phải, giúp tra học liệu và sách.</p>',false);const overlay=document.getElementById('robot-overlay');if(overlay){overlay.classList.add('bk-guide-overlay');overlay.querySelector('.robot-face')?.remove();const title=overlay.querySelector('h2');if(title)title.textContent='Hướng dẫn thực hiện';overlay.querySelector('button')?.focus();overlay.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();closeRobot();document.getElementById('bk-guide-button')?.focus()}})}}
function bkMountGuide(){for(const node of document.querySelectorAll(BK_HELP_SELECTOR))node.remove();if(!document.getElementById('bk-guide-button')){const b=document.createElement('button');b.id='bk-guide-button';b.type='button';b.textContent='📋 Hướng dẫn thực hiện';b.addEventListener('click',bkGuideOpen);document.body.append(b)}bkSyncTutor()}
// Thêm duy nhất một mục vào menu chung, giữ nguyên ID và liên kết cũ.
SB_LINKS.splice(SB_LINKS.findIndex(x=>x[0]==='grammar')+1,0,['books','Kho sách Tiếng Anh',[31,289,56,49],'book']);
const bkPreviousRender=render;render=function(){let result;if(state.page==='books'){document.getElementById('app').innerHTML=bkShelf();sbMount();bkRestoreBooks()}else result=bkPreviousRender();bkMountGuide();return result};
bkMountGuide();

/* Sửa riêng hội thoại gia sư và tốc độ đọc truyện. Không đổi học liệu hay điểm số. */
const CS_STORY_RATE_KEY='daingan-story-voice-rate-v1';
function csStoryRate(){try{const n=Number(localStorage.getItem(CS_STORY_RATE_KEY));return [.65,.85,1].includes(n)?n:.65}catch{return .65}}
function csSetStoryRate(value){const n=Number(value);if(![.65,.85,1].includes(n))return;try{localStorage.setItem(CS_STORY_RATE_KEY,String(n))}catch{}csStoryRateSession=n;stopSpeech()}
let csStoryRateSession=csStoryRate();
const csOriginalSay=say;
say=function(text,rateOverride=null){return csOriginalSay(text,rateOverride===null&&state.page==='stories'?csStoryRateSession:rateOverride)};
const csOriginalStory=story;
story=function(){const html=csOriginalStory();const controls=`<label class="cs-story-speed">🐢 Tốc độ đọc <select aria-label="Tốc độ đọc truyện" onchange="csSetStoryRate(this.value)">${[[.65,'Chậm · 0,65×'],[.85,'Vừa · 0,85×'],[1,'Nhanh · 1×']].map(([rate,label])=>`<option value="${rate}" ${rate===csStoryRateSession?'selected':''}>${label}</option>`).join('')}</select><small>Áp dụng cho lần nghe tiếp theo.</small></label>`;return html.replace('<div class="st-tools">','<div class="st-tools">'+controls)};
// Giữ nguồn sách để truy xuất bên trong, bỏ bảng nguồn và tên tài liệu khỏi hội thoại.
const csPreviousSync=bkSyncTutor;
bkSyncTutor=function(){csPreviousSync();const h=document.getElementById('dn-tutor');if(!h)return;const label=h.querySelector('label[for="bk-tutor-grade"]');if(label)label.textContent='Khối lớp';const note=h.querySelector('.bk-source-note');if(note)note.textContent='';const reset=h.querySelector('#bk-tutor-reset');if(reset)reset.textContent='Bỏ chọn bài';const mode=h.querySelector('#dt-mode');if(mode)mode.textContent=dtConfig().enabled?'Gia sư AI · cùng em học tiếng Anh':'Bạn học tiếng Anh · chế độ học liệu có sẵn'};
function csCleanReply(value){let s=String(value||'').replace(/\r/g,'');s=s.replace(/\[([^\]]*)\]\((?:https?:\/\/|blob:|file:|\.\/)[^)]+\)/gi,'$1').replace(/(?:https?:\/\/|blob:|file:\/\/|www\.)\S+/gi,'').replace(/\b[\w.%+\/-]+\.pdf\b(?:[^\s]*)/gi,'');s=s.replace(/^\s*(?:nguồn|nguon|tài liệu tham khảo|tai lieu tham khao|tham khảo|source|sources|references?|trích dẫn|trich dan)\s*[:：].*$/gim,'');s=s.replace(/(?:Tiếng|Tieng)\s*Anh\s*[1-5]\s*(?:[·–—-]\s*)?(?:(?:Tập|Tap)\s*[12])?(?:\s*[·–—,-]\s*)?(?:(?:trang\s*)?PDF\s*\d+|trang\s*\d+)?/gi,'');s=s.replace(/\b(?:trang\s*)?PDF\s*\d+\b/gi,'').replace(/\[\d+\]/g,'').replace(/\*\*/g,'').replace(/\n{3,}/g,'\n\n').trim();if(s.length>950){const clip=s.slice(0,950);const end=Math.max(clip.lastIndexOf('. '),clip.lastIndexOf('! '),clip.lastIndexOf('? '),clip.lastIndexOf('\n'));s=(end>350?clip.slice(0,end+1):clip)+'…'}return s||'🌱 Em gửi một từ hoặc câu tiếng Anh cụ thể nhé. Mình sẽ cùng em tìm hiểu từng bước.'}
function csLooksRawReply(text,rows){const n=dtNorm(text);if(n.length<220)return false;return rows.some(({p})=>{const source=dtNorm(p.text);return source.includes(n.slice(0,180))||String(p.text).split('\n').some(line=>dtNorm(line).length>150&&n.includes(dtNorm(line)))})}
function csContextLesson(){if(!bkState.context)return null;const p=bkPages.find(p=>p.book===bkState.context.book&&p.page===bkState.context.page);if(!p?.text)return null;const normalized=dtNorm(p.text);const records=Object.values(state.data?.grammar||window.EMBEDDED_DATA.content.grammar).flat();const seen=new Set();const matches=records.filter(x=>{const en=dtNorm(x.pattern);if(en.length<12||seen.has(en)||!normalized.includes(en))return false;seen.add(en);return true}).sort((a,b)=>b.pattern.length-a.pattern.length);return matches[0]||null}
dtLocalAnswer=function(query){const n=dtNorm(query);if(/^(hello|hi|xin chao|chao (?:ban|robot|gia su))$/.test(n))return {text:'👋 Hello! Mình rất vui được học cùng em. Em muốn hỏi từ mới, dịch câu hay tìm hiểu ngữ pháp nào?',english:'Hello! Nice to meet you!'};if(/^what(?:'s| is) your name$/.test(n))return {text:'🤖 My name is Buddy. Mình là bạn gia sư của em! Em có thể tập đáp: “My name is …” với một tên tưởng tượng nhé.',english:'My name is Buddy. What is your name?'};if(/^how are you(?: today)?$/.test(n))return {text:'😊 I am happy, thank you! How are you?\nMình vui, cảm ơn em! Em có thể đáp: “I am fine, thank you.”',english:'I am happy, thank you! How are you? I am fine, thank you.'};const generic=/\b(noi dung|bai nay|trang nay|giai thich bai|giai thich sach)\b/.test(n);if(generic&&bkState.context){const lesson=csContextLesson();if(lesson)return {text:csCleanReply(`🌱 Mình cùng học mẫu câu này nhé:\n${lesson.pattern}\nNghĩa: ${lesson.vi}\n${lesson.rule}\nEm thử đặt một câu tương tự nhé!`),english:lesson.example||lesson.pattern};return {text:'🌱 Em muốn hỏi phần nào trong bài này? Hãy gõ một từ, một câu hoặc câu hỏi cụ thể để mình giải thích ngắn gọn nhé.',english:''}}const result=bkOriginalLocalAnswer(query);if(/Chưa có|gần đúng|chưa có/i.test(result.source||''))return {text:'🌱 Mình chưa có lời giải chắc chắn cho câu này. Em gửi rõ từ hoặc câu tiếng Anh muốn hỏi nhé. Với câu hỏi mở rộng, thầy cô cần bật kết nối AI để mình hỗ trợ thêm.',english:''};return {text:csCleanReply(result.text),english:String(result.english||'').slice(0,500)};};
// Luôn dựng hai vai trò bằng textContent, không tạo liên kết từ câu trả lời.
dtAdd=function(role,result){const log=document.querySelector('#dn-tutor .dt-log');const box=document.createElement('div');box.className='dt-message'+(role==='user'?' dt-user':'');box.dataset.role=role;const label=document.createElement('strong');label.className='cs-role';label.textContent=role==='user'?'🧑 Em hỏi':'🤖 Gia sư';box.append(label);const text=document.createElement('div');text.className='dt-text';text.textContent=role==='user'?String(result.text||''):csCleanReply(result.text);box.append(text);if(role==='assistant'&&result.english){const controls=document.createElement('div');controls.className='dt-audio';for(const [caption,rate] of [['🔊 Nghe mẫu',null],['🐢 Nghe chậm',.6]]){const b=document.createElement('button');b.type='button';b.className='dt-small';b.textContent=caption;b.addEventListener('click',()=>csOriginalSay(result.english,rate));controls.append(b)}box.append(controls)}log.append(box);while(log.children.length>36){log.firstElementChild.remove();if(log.firstElementChild?.dataset.role==='assistant')log.firstElementChild.remove()}log.scrollTop=log.scrollHeight;return box};
async function csSubmit(){const input=document.querySelector('#dn-tutor textarea');const query=input.value.trim();if(dtState.busy||!query)return;if(query.length>800){dtStatus('Em viết tối đa 800 ký tự mỗi lần nhé.');return}input.value='';const question=dtAdd('user',{text:query});dtSetBusy(true);dtStatus('Gia sư đang trả lời…');const request=++dtState.request;let timer,result,failed=false;try{if(dtConfig().enabled){dtState.controller=new AbortController();timer=setTimeout(()=>dtState.controller?.abort(),20000);result=await dtRemote(query,dtState.controller.signal)}else result=dtLocalAnswer(query)}catch{if(request!==dtState.request)return;failed=true;result=dtLocalAnswer(query)}finally{clearTimeout(timer);if(request===dtState.request){dtState.controller=null;dtSetBusy(false)}}if(request!==dtState.request)return;dtStatus(failed?'Chưa kết nối được AI; mình đang hỗ trợ bằng học liệu có sẵn.':'');dtAdd('assistant',result);dtState.history.push({role:'user',content:query},{role:'assistant',content:result.text});dtState.history=dtState.history.slice(-8);const log=document.querySelector('#dn-tutor .dt-log');if(question.isConnected)log.scrollTop=Math.max(0,question.offsetTop-log.offsetTop-8);}
dtSubmit=csSubmit;
dtWelcome=function(){dtAdd('assistant',{text:'👋 Chào em! Em muốn hỏi từ mới, dịch câu hay tìm hiểu ngữ pháp? Hãy gõ câu hỏi bên dưới nhé.',english:'Hello! Let us learn English together.'})};
const csPreviousAsk=bkAskPage;bkAskPage=function(id,page){csPreviousAsk(id,page);document.getElementById('dt-input').value='Giúp em hiểu nội dung bài này.';dtStatus('Em nhập phần muốn hỏi rồi bấm Gửi nhé.');bkSyncTutor()};
// Thay lời chào ban đầu; chat không bị dựng lại khi người dùng chuyển trang.
const csLog=document.querySelector('#dn-tutor .dt-log');if(csLog){csLog.replaceChildren();dtWelcome()}bkSyncTutor();

